  function clearGhostTrainCannonballs() {
    for (var i = state.ghostTrainCannonballs.length - 1; i >= 0; i--) {
      var ball = state.ghostTrainCannonballs[i];
      releaseGhostTrainCannonballState(ball);
    }
    state.ghostTrainCannonballs.length = 0;
  }

  function clearGhostTrainCannonTelegraphs(encounter) {
    if (!encounter || !encounter.cannonTelegraphs) return;
    for (var i = encounter.cannonTelegraphs.length - 1; i >= 0; i--) {
      var telegraph = encounter.cannonTelegraphs[i];
      if (telegraph && telegraph.trajectory) releaseGhostTrainCannonTrajectoryVisual(telegraph.trajectory);
    }
    encounter.cannonTelegraphs.length = 0;
  }

  function clearGhostTrainEncounter() {
    var encounter = state.ghostTrain;
    clearGhostTrainCannonballs();
    if (!encounter) return;
    clearGhostTrainCannonTelegraphs(encounter);
    if (encounter.steamWaves) encounter.steamWaves.length = 0;
    if (encounter.steamWavePool) encounter.steamWavePool.length = 0;
    var detached = encounter.detachedWagons || [];
    for (var d = 0; d < detached.length; d++) {
      if (detached[d].warningRing) removeObject3D(detached[d].warningRing);
    }
    if (encounter.visualBundle) {
      if (encounter.rearGunModel && encounter.rearGunModel.parent) encounter.rearGunModel.parent.remove(encounter.rearGunModel);
      releaseGhostTrainVisualBundle(encounter.visualBundle);
      encounter.visualBundle = null;
    } else {
      // Defensive compatibility for encounters created before the visual pool was initialized.
      if (encounter.cannonVisualBatch) disposeGhostTrainCannonVisualBatch(encounter.cannonVisualBatch);
      if (encounter.tunnelVisualBatch) disposeGhostTrainTunnelVisualBatch(encounter.tunnelVisualBatch);
      if (encounter.rearGunTracerBatch) disposeGhostTrainRearGunTracerBatch(encounter.rearGunTracerBatch);
      if (encounter.steamWaveVisualBatch) disposeGhostTrainSteamWaveVisualBatch(encounter.steamWaveVisualBatch);
      if (encounter.rearGunModel) removeObject3D(encounter.rearGunModel);
      if (encounter.trackVisual && encounter.trackVisual.group) {
        [encounter.trackVisual.rails, encounter.trackVisual.ties, encounter.trackVisual.glow].forEach(function (mesh) {
          if (mesh && typeof mesh.dispose === "function") mesh.dispose();
        });
        removeObject3D(encounter.trackVisual.group);
      }
      var segments = encounter.segments || [];
      for (var i = 0; i < segments.length; i++) {
        if (segments[i].group) removeObject3D(segments[i].group);
        segments[i].group = null;
      }
    }
    state.ghostTrain = null;
    if (bossHud) {
      bossHud.hidden = true;
      bossHud.classList.remove("is-ghost-train", "is-spectral", "is-materialized");
    }
  }

  function isGhostTrainAlive() {
    var encounter = state.ghostTrain;
    return !!(encounter && encounter.active && encounter.boss && encounter.boss.active !== false && encounter.boss.hp > 0);
  }

  function getActiveGhostTrainDamageTarget() {
    var encounter = state.ghostTrain;
    if (!encounter || !encounter.active || encounter.defeated || !encounter.materialized || !encounter.vulnerable) return null;
    var segment = encounter.segments[encounter.activeTailIndex];
    if (!segment || !segment.attached || segment.hp <= 0) return null;
    segment.vulnerableTarget = true;
    return segment;
  }

  function findGhostTrainSegmentByNetworkId(id) {
    var encounter = state.ghostTrain;
    if (!encounter) return null;
    for (var i = 0; i < encounter.segments.length; i++) {
      if (String(encounter.segments[i].networkId) === String(id)) return encounter.segments[i];
    }
    return null;
  }

  function getGhostTrainAttackDuration(encounter) {
    return GHOST_TRAIN_ATTACK_TIMES[clamp(Math.floor(encounter.phase || 0), 0, GHOST_TRAIN_ATTACK_TIMES.length - 1)];
  }

  function getGhostTrainCannonInterval(encounter) {
    var phase = clamp(Math.floor(encounter && encounter.phase || 0), 0, GHOST_TRAIN_CANNON_INTERVALS.length - 1);
    return GHOST_TRAIN_CANNON_INTERVALS[phase];
  }

  function getGhostTrainCannonWarningLead(encounter) {
    var interval = getGhostTrainCannonInterval(encounter);
    return Math.min(GHOST_TRAIN_CANNON_WARNING_LEAD, Math.max(0.085, interval * 0.82));
  }

  function chooseGhostTrainAttack(encounter) {
    var phase = clamp(Math.floor(encounter.phase || 0), 0, 4);
    if (phase >= 4) return "ram";
    if (phase === 3) return encounter.actionSequence % 2 ? "ram" : "crossfire";
    if (phase >= 1 && encounter.actionSequence % 2) return "crossfire";
    return "broadside";
  }

  function getGhostTrainAttackSide(encounter) {
    var engine = encounter && encounter.segments && encounter.segments[0];
    if (!engine) return 1;
    var targetX = Number(encounter.plannerTargetX) || engine.x;
    var targetZ = Number(encounter.plannerTargetZ) || engine.z;
    var rightX = Math.cos(engine.facingAngle || 0);
    var rightZ = -Math.sin(engine.facingAngle || 0);
    return (targetX - engine.x) * rightX + (targetZ - engine.z) * rightZ >= 0 ? 1 : -1;
  }

  function getGhostTrainMaterializeCooldownRemaining(encounter) {
    if (!encounter) return 0;
    var lastMaterializeAt = Number(encounter.lastMaterializeAt);
    if (!Number.isFinite(lastMaterializeAt)) return 0;
    return Math.max(0, GHOST_TRAIN_MATERIALIZE_COOLDOWN - Math.max(0, state.time - lastMaterializeAt));
  }

  function canGhostTrainMaterialize(encounter) {
    return getGhostTrainMaterializeCooldownRemaining(encounter) <= 0.0001;
  }

  function activateGhostTrainFinalMaterialApproach(encounter) {
    if (
      !encounter || encounter.replica || encounter.phase < 4 || encounter.action !== "spectral" ||
      encounter.tunnelActive || !encounter.attackApproachActive
    ) return false;
    if (isGhostTrainFinalMaterialApproach(encounter) && encounter.finalPhaseApproachActivated) {
      encounter.finalMaterialApproachPending = false;
      return true;
    }
    if (!canGhostTrainMaterialize(encounter)) return false;
    prewarmGhostTrainCannonVisualBatch(encounter.cannonVisualBatch);
    prewarmGhostTrainCannonAudio();
    encounter.lastMaterializeAt = state.time;
    encounter.materializationCount = Math.max(0, encounter.materializationCount || 0) + 1;
    encounter.finalPhaseApproachActivated = true;
    encounter.materialized = true;
    encounter.vulnerable = true;
    encounter.finalMaterialApproachPending = false;
    encounter.attackKind = chooseGhostTrainAttack(encounter);
    encounter.attackSide = getGhostTrainAttackSide(encounter);
    encounter.trainHitIds = Object.create(null);
    playGhostTrainWhistle(encounter.boss.x, encounter.boss.z, false);
    addShockwave(encounter.boss.x, encounter.boss.z, 4.4, 0.42, 0x43f5c9);
    addLightFlash(encounter.boss.x, 2.8, encounter.boss.z, 0x35ffd0, 3.8, 11, 0.24);
    return true;
  }

  function beginGhostTrainAction(encounter, action, duration) {
    if (!encounter || !encounter.boss) return false;
    if (action === "materialize" && !canGhostTrainMaterialize(encounter)) return false;
    clearGhostTrainCannonTelegraphs(encounter);
    duration = Math.max(0, Number(duration) || 0);
    if (
      encounter.tunnelActive &&
      (action !== "spectral" || Math.abs(duration - GHOST_TRAIN_TUNNEL_DURATION) > 0.001)
    ) finishGhostTrainTunnelTransit(encounter);
    encounter.action = action;
    encounter.actionDuration = duration;
    encounter.actionTimer = duration;
    encounter.actionSequence = Math.max(0, encounter.actionSequence || 0) + 1;
    encounter.boss.action = action;
    encounter.boss.actionDuration = duration;
    encounter.boss.actionTimer = duration;
    encounter.boss.actionSequence = encounter.actionSequence;
    encounter.lastCannonStep = -1;
    encounter.trainHitIds = Object.create(null);
    encounter.finalMaterialApproachPending = false;
    if (action === "spectral") {
      releaseGhostTrainCannonAim(encounter);
      encounter.materialized = false;
      encounter.vulnerable = false;
      encounter.attackApproachActive = false;
      encounter.attackApproachUsesExistingRail = false;
      encounter.attackApproachAge = 0;
      encounter.spectralTargetAge = 0;
      encounter.plannerRefreshTimer = 0;
      chooseGhostTrainTarget(encounter);
      updateGhostTrainSpectralPatrol(encounter);
    } else if (action === "materialize") {
      prewarmGhostTrainCannonVisualBatch(encounter.cannonVisualBatch);
      prewarmGhostTrainCannonAudio();
      encounter.lastMaterializeAt = state.time;
      encounter.materializationCount = Math.max(0, encounter.materializationCount || 0) + 1;
      var committedApproach = !!encounter.attackApproachActive;
      encounter.lastApproachUsedExistingRail = !!encounter.attackApproachUsesExistingRail;
      encounter.attackApproachActive = false;
      encounter.attackApproachUsesExistingRail = false;
      encounter.attackApproachAge = 0;
      encounter.materialized = false;
      encounter.vulnerable = false;
      encounter.spectralGroupHook = false;
      if (!committedApproach) updateGhostTrainPlannerTarget(encounter, true);
      encounter.routeSequence += 1;
      encounter.attackKind = chooseGhostTrainAttack(encounter);
      encounter.attackSide = getGhostTrainAttackSide(encounter);
      primeGhostTrainCannonAim(encounter, duration + 0.32);
      playGhostTrainWhistle(encounter.boss.x, encounter.boss.z, false);
    } else if (action === "broadside" || action === "crossfire" || action === "ram") {
      encounter.attackApproachActive = false;
      encounter.materialized = true;
      encounter.vulnerable = true;
      encounter.attackKind = action;
      encounter.attackSide = getGhostTrainAttackSide(encounter);
      primeGhostTrainCannonAim(encounter, 0.42);
      addShockwave(encounter.boss.x, encounter.boss.z, 4.8, 0.48, 0x43f5c9);
      addLightFlash(encounter.boss.x, 2.8, encounter.boss.z, 0x35ffd0, 4.2, 12, 0.28);
    } else if (action === "dematerialize" || action === "detach") {
      releaseGhostTrainCannonAim(encounter);
      encounter.attackApproachActive = false;
      encounter.vulnerable = false;
      encounter.materialized = false;
    }
    // The locomotive's last stand is fully corporeal. Action names such as
    // spectral/dematerialize still drive routing and tunnel presentation, but
    // they can no longer close the final damage window.
    if (encounter.phase >= 4) {
      encounter.materialized = true;
      encounter.vulnerable = true;
    }
    if (!encounter.materialized) {
      encounter.rearGunActive = false;
      encounter.rearGunTargetPlayerId = "";
      encounter.rearGunTargetDistance = 0;
      encounter.rearGunCooldown = 0;
    }
    for (var i = 0; i < encounter.segments.length; i++) encounter.segments[i].vulnerableTarget = false;
    return true;
  }

  function createGhostTrainCannonInstancedMesh(name, geometry, material, capacity, renderOrder) {
    var mesh = new THREE.InstancedMesh(geometry, material, capacity);
    mesh.name = name;
    mesh.count = 0;
    mesh.castShadow = false;
    mesh.receiveShadow = false;
    mesh.frustumCulled = false;
    mesh.renderOrder = renderOrder || 0;
    mesh.userData.disposeGeometry = false;
    mesh.userData.disposeMaterial = false;
    if (mesh.instanceMatrix && typeof mesh.instanceMatrix.setUsage === "function" && THREE.DynamicDrawUsage != null) {
      mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    }
    return mesh;
  }

  function createGhostTrainCannonVisualBatch() {
    ensureGhostTrainMaterials();
    var group = new THREE.Group();
    group.name = "Ghost Train batched cannon effects";
    var batch = {
      group: group,
      core: createGhostTrainCannonInstancedMesh(
        "Ghost Train cannonball cores",
        getSharedGeometry("ghost-train-cannonball-core", function () { return new THREE.IcosahedronGeometry(0.34, 1); }),
        mats.ghostTrainCannonball,
        GHOST_TRAIN_CANNONBALL_CAP,
        0
      ),
      glow: createGhostTrainCannonInstancedMesh(
        "Ghost Train cannonball glows",
        getSharedGeometry("ghost-train-cannonball-glow", function () { return new THREE.SphereGeometry(0.62, 10, 7); }),
        mats.ghostTrainSpectralGlow,
        GHOST_TRAIN_CANNONBALL_CAP,
        1
      ),
      trail: createGhostTrainCannonInstancedMesh(
        "Ghost Train cannonball trails",
        getSharedGeometry("ghost-train-cannonball-trail", function () { return new THREE.ConeGeometry(0.3, 1.7, 8); }),
        mats.ghostTrainRailGlow,
        GHOST_TRAIN_CANNONBALL_CAP,
        1
      ),
      trajectoryOuter: createGhostTrainCannonInstancedMesh(
        "Ghost Train cannon trajectory outer strips",
        getSharedGeometry("ghost-train-cannon-trajectory-unit", function () { return new THREE.BoxGeometry(1, 1, 1); }),
        mats.ghostTrainCannonWarningOuter,
        GHOST_TRAIN_CANNON_TRAJECTORY_CAP,
        -4
      ),
      trajectoryInner: null,
      projectileActive: [],
      trajectoryActive: [],
      projectileSlots: [],
      trajectorySlots: [],
      freeProjectiles: [],
      freeTrajectories: [],
      projectileCount: 0,
      trajectoryCount: 0,
      projectileInUse: 0,
      trajectoryInUse: 0,
      projectileAcquisitions: 0,
      trajectoryAcquisitions: 0,
      matrixWrites: 0,
      gpuPrewarmed: false,
      gpuPrewarmPending: false,
      gpuPrewarmPromise: null,
      gpuPrewarmGeneration: 0,
      gpuPrewarmAttempts: 0,
      gpuPrewarmFailure: "",
      salvoSoundVoices: 0,
      trailParticlesEmitted: 0,
      trailParticlesSkipped: 0,
      hiddenMatrix: new THREE.Matrix4().makeScale(0, 0, 0),
      projectileDummy: new THREE.Object3D(),
      trajectoryDummy: new THREE.Object3D(),
      projectileBaseMatrix: new THREE.Matrix4(),
      trailMatrix: new THREE.Matrix4(),
      trailLocalMatrix: new THREE.Matrix4(),
    };
    batch.trajectoryInner = createGhostTrainCannonInstancedMesh(
      "Ghost Train cannon trajectory inner strips",
      getSharedGeometry("ghost-train-cannon-trajectory-unit", function () { return new THREE.BoxGeometry(1, 1, 1); }),
      mats.ghostTrainCannonWarningInner,
      GHOST_TRAIN_CANNON_TRAJECTORY_CAP,
      -3
    );
    batch.meshes = [batch.core, batch.glow, batch.trail, batch.trajectoryOuter, batch.trajectoryInner];
    for (var meshIndex = 0; meshIndex < batch.meshes.length; meshIndex++) group.add(batch.meshes[meshIndex]);
    var trailLocal = new THREE.Object3D();
    trailLocal.position.z = -0.78;
    trailLocal.rotation.x = -Math.PI / 2;
    trailLocal.updateMatrix();
    batch.trailLocalMatrix.copy(trailLocal.matrix);
    for (var projectileSlot = GHOST_TRAIN_CANNONBALL_CAP - 1; projectileSlot >= 0; projectileSlot--) {
      batch.projectileActive[projectileSlot] = false;
      var projectileVisual = {
        batch: batch,
        slot: projectileSlot,
        inUse: false,
        visible: false,
        userData: {},
      };
      batch.projectileSlots[projectileSlot] = projectileVisual;
      batch.freeProjectiles.push(projectileVisual);
    }
    for (var trajectorySlot = GHOST_TRAIN_CANNON_TRAJECTORY_CAP - 1; trajectorySlot >= 0; trajectorySlot--) {
      batch.trajectoryActive[trajectorySlot] = false;
      var trajectoryVisual = {
        batch: batch,
        slot: trajectorySlot,
        inUse: false,
        visible: false,
        userData: {},
      };
      batch.trajectorySlots[trajectorySlot] = trajectoryVisual;
      batch.freeTrajectories.push(trajectoryVisual);
    }
    group.userData.ghostTrainCannonVisualBatch = batch;
    dynamicRoot.add(group);
    return batch;
  }

  function prewarmGhostTrainCannonVisualBatch(batch) {
    // CPU/GPU preparation is owned by the detached bundle pipeline. Never
    // compile the live scene from an attack transition or a network snapshot.
    return !!(batch && batch.gpuPrewarmed);
  }

  function createGhostTrainRearGunTracerBatch() {
    ensureGhostTrainMaterials();
    var group = new THREE.Group();
    group.name = "Ghost Train batched rear machine gun tracers";
    var batch = {
      group: group,
      core: createGhostTrainCannonInstancedMesh(
        "Ghost Train rear machine gun tracer cores",
        getSharedGeometry("ghost-train-rear-gun-tracer-unit", function () { return new THREE.BoxGeometry(1, 1, 1); }),
        mats.ghostTrainRearGunTracer,
        GHOST_TRAIN_REAR_GUN_TRACER_CAP,
        3
      ),
      glow: createGhostTrainCannonInstancedMesh(
        "Ghost Train rear machine gun tracer glows",
        getSharedGeometry("ghost-train-rear-gun-tracer-unit", function () { return new THREE.BoxGeometry(1, 1, 1); }),
        mats.ghostTrainRearGunTracerGlow,
        GHOST_TRAIN_REAR_GUN_TRACER_CAP,
        2
      ),
      active: [],
      pool: [],
      tracers: [],
      dummy: new THREE.Object3D(),
      forward: new THREE.Vector3(0, 0, 1),
      direction: new THREE.Vector3(),
      acquisitions: 0,
      matrixWrites: 0,
      authoritativeHits: 0,
      authoritativeMisses: 0,
    };
    group.add(batch.glow, batch.core);
    for (var tracerIndex = 0; tracerIndex < GHOST_TRAIN_REAR_GUN_TRACER_CAP; tracerIndex++) {
      var tracer = {};
      batch.tracers.push(tracer);
      batch.pool.push(tracer);
    }
    group.userData.ghostTrainRearGunTracerBatch = batch;
    dynamicRoot.add(group);
    return batch;
  }

  function disposeGhostTrainRearGunTracerBatch(batch) {
    if (!batch) return;
    batch.active.length = 0;
    batch.pool.length = 0;
    batch.core.count = 0;
    batch.glow.count = 0;
    if (typeof batch.core.dispose === "function") batch.core.dispose();
    if (typeof batch.glow.dispose === "function") batch.glow.dispose();
    removeObject3D(batch.group);
  }

  function createGhostTrainSteamWaveVisualBatch() {
    ensureGhostTrainMaterials();
    var group = new THREE.Group();
    group.name = "Ghost Train batched spectral steam waves";
    var puffGeometry = getSharedGeometry("ghost-train-steam-puff-plane", function () {
      return new THREE.PlaneGeometry(2, 2, 1, 1);
    });
    var puffAlpha = puffGeometry.getAttribute("instanceSteamAlpha");
    if (!puffAlpha || puffAlpha.count !== GHOST_TRAIN_STEAM_PUFF_CAP) {
      puffAlpha = new THREE.InstancedBufferAttribute(new Float32Array(GHOST_TRAIN_STEAM_PUFF_CAP), 1);
      if (typeof puffAlpha.setUsage === "function" && THREE.DynamicDrawUsage != null) puffAlpha.setUsage(THREE.DynamicDrawUsage);
      puffGeometry.setAttribute("instanceSteamAlpha", puffAlpha);
    }
    var batch = {
      group: group,
      core: createGhostTrainCannonInstancedMesh(
        "Ghost Train steam wave ground guides",
        getSharedGeometry("ghost-train-steam-wave-core", function () { return new THREE.RingGeometry(0.992, 1, 64, 1); }),
        mats.ghostTrainSteamWave,
        GHOST_TRAIN_STEAM_WAVE_CAP,
        1
      ),
      puffs: createGhostTrainCannonInstancedMesh(
        "Ghost Train rolling steam clouds",
        puffGeometry,
        mats.ghostTrainSteamPuff,
        GHOST_TRAIN_STEAM_PUFF_CAP,
        3
      ),
      puffAlpha: puffAlpha,
      dummy: new THREE.Object3D(),
      rotation: new THREE.Quaternion(),
      color: new THREE.Color(),
      acquisitions: 0,
      matrixWrites: 0,
      candidatePuffs: 0,
      culledPuffs: 0,
      peakVisiblePuffs: 0,
    };
    batch.color.setHex(0xffffff);
    batch.core.setColorAt(0, batch.color);
    batch.puffs.setColorAt(0, batch.color);
    batch.meshes = [batch.core, batch.puffs];
    for (var meshIndex = 0; meshIndex < batch.meshes.length; meshIndex++) group.add(batch.meshes[meshIndex]);
    group.userData.ghostTrainSteamWaveVisualBatch = batch;
    dynamicRoot.add(group);
    return batch;
  }

  function disposeGhostTrainSteamWaveVisualBatch(batch) {
    if (!batch) return;
    for (var meshIndex = 0; meshIndex < batch.meshes.length; meshIndex++) {
      batch.meshes[meshIndex].count = 0;
      if (typeof batch.meshes[meshIndex].dispose === "function") batch.meshes[meshIndex].dispose();
    }
    removeObject3D(batch.group);
  }

  function getGhostTrainRearGunHalfAngle(encounter) {
    return encounter && Math.floor(Number(encounter.activeTailIndex) || 0) === 0
      ? Math.PI
      : GHOST_TRAIN_REAR_GUN_HALF_ANGLE;
  }

  function getGhostTrainRearGunInterval(encounter) {
    return encounter && Math.floor(Number(encounter.phase) || 0) >= 4
      ? GHOST_TRAIN_REAR_GUN_INTERVAL / GHOST_TRAIN_FINAL_REAR_GUN_FIRE_RATE_MULTIPLIER
      : GHOST_TRAIN_REAR_GUN_INTERVAL;
  }

  function getGhostTrainRearGunTracerSpeed(encounter) {
    return encounter && Math.floor(Number(encounter.phase) || 0) >= 4
      ? GHOST_TRAIN_REAR_GUN_TRACER_SPEED * GHOST_TRAIN_FINAL_REAR_GUN_BULLET_SPEED_MULTIPLIER
      : GHOST_TRAIN_REAR_GUN_TRACER_SPEED;
  }

  function getGhostTrainRearGunMountZ(encounter) {
    return encounter && Math.floor(Number(encounter.activeTailIndex) || 0) === 0
      ? GHOST_TRAIN_REAR_GUN_LOCOMOTIVE_MOUNT_Z
      : GHOST_TRAIN_REAR_GUN_MOUNT_Z;
  }

  function attachGhostTrainRearMachineGun(encounter) {
    if (!encounter || !encounter.rearGunModel) return null;
    var segmentIndex = Math.floor(Number(encounter.activeTailIndex) || 0);
    var segment = segmentIndex >= 0 && encounter.segments ? encounter.segments[segmentIndex] : null;
    var model = encounter.rearGunModel;
    if (!segment || !segment.attached || !segment.group) {
      if (model.parent) model.parent.remove(model);
      model.visible = false;
      encounter.rearGunAttachedIndex = -1;
      return null;
    }
    if (model.parent !== segment.group) {
      if (model.parent) model.parent.remove(model);
      segment.group.add(model);
      model.rotation.set(0, 0, 0);
      model.scale.set(1, 1, 1);
    }
    model.position.set(0, 0, getGhostTrainRearGunMountZ(encounter) - GHOST_TRAIN_REAR_GUN_MOUNT_Z);
    model.visible = true;
    encounter.rearGunAttachedIndex = segmentIndex;
    return segment;
  }

  function getGhostTrainRearGunShot(encounter, aimAngle) {
    var segment = encounter && encounter.segments && encounter.segments[encounter.activeTailIndex];
    if (!segment || !segment.attached) return null;
    var facing = Number(segment.facingAngle) || 0;
    var forwardX = Math.sin(facing);
    var forwardZ = Math.cos(facing);
    var rightX = Math.cos(facing);
    var rightZ = -Math.sin(facing);
    var halfAngle = getGhostTrainRearGunHalfAngle(encounter);
    var aim = clamp(normalizeGhostTrainAngle(Number(aimAngle) || 0), -halfAngle, halfAngle);
    var localDirX = -Math.sin(aim);
    var localDirZ = -Math.cos(aim);
    var localMuzzleX = localDirX * GHOST_TRAIN_REAR_GUN_MUZZLE_DISTANCE;
    var localMuzzleZ = getGhostTrainRearGunMountZ(encounter) + localDirZ * GHOST_TRAIN_REAR_GUN_MUZZLE_DISTANCE;
    return {
      segment: segment,
      aim: aim,
      x: segment.x + rightX * localMuzzleX + forwardX * localMuzzleZ,
      y: GHOST_TRAIN_REAR_GUN_MUZZLE_HEIGHT,
      z: segment.z + rightZ * localMuzzleX + forwardZ * localMuzzleZ,
      dirX: rightX * localDirX + forwardX * localDirZ,
      dirZ: rightZ * localDirX + forwardZ * localDirZ,
    };
  }

  function acquireGhostTrainRearGunTracer(encounter, aimAngle, initialAge, authoritativeDamage) {
    var batch = encounter && encounter.rearGunTracerBatch;
    var shot = getGhostTrainRearGunShot(encounter, aimAngle);
    if (!batch || !shot) return null;
    var tracer = batch.pool.length ? batch.pool.pop() : batch.active.shift();
    if (!tracer) return null;
    tracer.x = shot.x;
    tracer.y = shot.y;
    tracer.z = shot.z;
    tracer.dirX = shot.dirX;
    tracer.dirZ = shot.dirZ;
    tracer.dirY = (0.92 - shot.y) / GHOST_TRAIN_REAR_GUN_RANGE;
    tracer.age = Math.max(0, Number(initialAge) || 0);
    tracer.speed = getGhostTrainRearGunTracerSpeed(encounter);
    tracer.life = GHOST_TRAIN_REAR_GUN_RANGE / tracer.speed + 0.08;
    tracer.authoritativeDamage = !!authoritativeDamage;
    batch.active.push(tracer);
    batch.acquisitions += 1;
    return tracer;
  }

  function resolveGhostTrainRearGunTracerHit(tracer, oldDistance, newDistance) {
    if (!tracer || !tracer.authoritativeDamage || newDistance <= oldDistance) return false;
    var startX = tracer.x + tracer.dirX * oldDistance;
    var startZ = tracer.z + tracer.dirZ * oldDistance;
    var endX = tracer.x + tracer.dirX * newDistance;
    var endZ = tracer.z + tracer.dirZ * newDistance;
    var entries = getGhostTrainPlayerEntries();
    var bestEntry = null;
    var bestTime = Infinity;
    for (var playerIndex = 0; playerIndex < entries.length; playerIndex++) {
      var entry = entries[playerIndex];
      var entity = entry && entry.entity;
      if (!entity) continue;
      var hitTime = getSegmentCircleEntryTime(
        startX,
        startZ,
        endX,
        endZ,
        entity.x,
        entity.z,
        GHOST_TRAIN_REAR_GUN_HIT_RADIUS + Math.max(0, Number(entity.radius) || 0)
      );
      if (hitTime == null || hitTime >= bestTime) continue;
      bestTime = hitTime;
      bestEntry = entry;
    }
    if (!bestEntry) return false;
    tracer.authoritativeDamage = false;
    damagePlayer(GHOST_TRAIN_REAR_GUN_DAMAGE, bestEntry.entity);
    return true;
  }

  function updateGhostTrainRearGunTracers(encounter, dt) {
    var batch = encounter && encounter.rearGunTracerBatch;
    if (!batch) return;
    for (var tracerIndex = batch.active.length - 1; tracerIndex >= 0; tracerIndex--) {
      var tracer = batch.active[tracerIndex];
      var tracerSpeed = Math.max(0.001, Number(tracer.speed) || getGhostTrainRearGunTracerSpeed(encounter));
      var oldDistance = Math.min(GHOST_TRAIN_REAR_GUN_RANGE, tracer.age * tracerSpeed);
      tracer.age += Math.max(0, dt || 0);
      var newDistance = Math.min(GHOST_TRAIN_REAR_GUN_RANGE, tracer.age * tracerSpeed);
      if (resolveGhostTrainRearGunTracerHit(tracer, oldDistance, newDistance)) {
        batch.authoritativeHits += 1;
        batch.active.splice(tracerIndex, 1);
        batch.pool.push(tracer);
        continue;
      }
      if (tracer.age < tracer.life) continue;
      if (tracer.authoritativeDamage) batch.authoritativeMisses += 1;
      tracer.authoritativeDamage = false;
      batch.active.splice(tracerIndex, 1);
      batch.pool.push(tracer);
    }
    if (!batch.active.length) {
      batch.core.count = 0;
      batch.glow.count = 0;
      return;
    }
    var dummy = batch.dummy;
    for (var activeIndex = 0; activeIndex < batch.active.length; activeIndex++) {
      var activeTracer = batch.active[activeIndex];
      var activeTracerSpeed = Math.max(0.001, Number(activeTracer.speed) || getGhostTrainRearGunTracerSpeed(encounter));
      var head = Math.min(GHOST_TRAIN_REAR_GUN_RANGE, activeTracer.age * activeTracerSpeed);
      var tail = Math.max(0, head - GHOST_TRAIN_REAR_GUN_TRACER_LENGTH);
      var length = Math.max(0.01, head - tail);
      var middle = (head + tail) * 0.5;
      dummy.position.set(
        activeTracer.x + activeTracer.dirX * middle,
        activeTracer.y + activeTracer.dirY * middle,
        activeTracer.z + activeTracer.dirZ * middle
      );
      batch.direction.set(activeTracer.dirX, activeTracer.dirY, activeTracer.dirZ).normalize();
      dummy.quaternion.setFromUnitVectors(batch.forward, batch.direction);
      dummy.scale.set(0.065, 0.065, length * Math.hypot(1, activeTracer.dirY));
      dummy.updateMatrix();
      batch.core.setMatrixAt(activeIndex, dummy.matrix);
      dummy.scale.set(0.19, 0.19, length * Math.hypot(1, activeTracer.dirY) * 1.08);
      dummy.updateMatrix();
      batch.glow.setMatrixAt(activeIndex, dummy.matrix);
      batch.matrixWrites += 2;
    }
    batch.core.count = batch.active.length;
    batch.glow.count = batch.active.length;
    batch.core.instanceMatrix.needsUpdate = true;
    batch.glow.instanceMatrix.needsUpdate = true;
  }

  function findGhostTrainRearGunTarget(encounter) {
    var segment = encounter && encounter.segments && encounter.segments[encounter.activeTailIndex];
    if (!segment || !segment.attached) return null;
    var facing = Number(segment.facingAngle) || 0;
    var forwardX = Math.sin(facing);
    var forwardZ = Math.cos(facing);
    var rightX = Math.cos(facing);
    var rightZ = -Math.sin(facing);
    var mountZ = getGhostTrainRearGunMountZ(encounter);
    var halfAngle = getGhostTrainRearGunHalfAngle(encounter);
    var originX = segment.x + forwardX * mountZ;
    var originZ = segment.z + forwardZ * mountZ;
    var entries = getGhostTrainPlayerEntries();
    var best = null;
    var bestDistanceSq = Infinity;
    for (var index = 0; index < entries.length; index++) {
      var entry = entries[index];
      var dx = entry.entity.x - originX;
      var dz = entry.entity.z - originZ;
      var distanceSq = dx * dx + dz * dz;
      var maximumRange = GHOST_TRAIN_REAR_GUN_RANGE + Math.max(0, Number(entry.entity.radius) || 0);
      if (distanceSq > maximumRange * maximumRange) continue;
      var localX = dx * rightX + dz * rightZ;
      var localZ = dx * forwardX + dz * forwardZ;
      var aim = normalizeGhostTrainAngle(Math.atan2(-localX, -localZ));
      if (Math.abs(aim) > halfAngle) continue;
      if (
        distanceSq < bestDistanceSq - 0.0001 ||
        (Math.abs(distanceSq - bestDistanceSq) <= 0.0001 && best && String(entry.id) < String(best.entry.id))
      ) {
        best = { entry: entry, aim: aim, distance: Math.sqrt(distanceSq) };
        bestDistanceSq = distanceSq;
      }
    }
    return best;
  }

  function updateGhostTrainRearGunVisual(encounter, dt) {
    var model = encounter && encounter.rearGunModel;
    var parts = model && model.userData.ghostTrainRearGunParts;
    if (!parts) return;
    var halfAngle = getGhostTrainRearGunHalfAngle(encounter);
    parts.pivot.rotation.y = clamp(
      Number(encounter.rearGunAim) || 0,
      -halfAngle,
      halfAngle
    );
    parts.weapon.position.z = Math.max(0, Number(encounter.rearGunMuzzleFlash) || 0) * 0.16;
    parts.drum.rotation.x += Math.max(0, dt || 0) * (encounter.rearGunActive ? 14 : 2.4);
    parts.drumGlow.rotation.z += Math.max(0, dt || 0) * (encounter.rearGunActive ? 9 : 1.6);
    var pulse = 1 + Math.sin(state.time * 9.5) * 0.055 + (encounter.rearGunActive ? 0.08 : 0);
    scaleFromBase(parts.receiver, pulse, pulse, pulse);
    var flash = Math.max(0, Number(encounter.rearGunMuzzleFlash) || 0);
    parts.muzzleFlash.visible = flash > 0.035;
    if (parts.muzzleFlash.visible) {
      var flashScale = 0.55 + flash * 0.82;
      scaleFromBase(parts.muzzleFlash, flashScale, flashScale, flashScale);
    }
    var showZone = !!(
      encounter.active && !encounter.defeated && encounter.materialized &&
      encounter.rearGunAttachedIndex === encounter.activeTailIndex
    );
    parts.zone.visible = showZone && encounter.activeTailIndex > 0;
    parts.fullZone.visible = showZone && encounter.activeTailIndex === 0;
    if (parts.zone.visible && parts.zone.material) {
      parts.zone.material.opacity = 0.065 + Math.max(0, Math.sin(state.time * 5.8)) * 0.035 + (encounter.rearGunActive ? 0.02 : 0);
    }
    if (parts.fullZone.visible && parts.fullZone.material) {
      parts.fullZone.material.opacity = 0.06 + Math.max(0, Math.sin(state.time * 5.8)) * 0.03 + (encounter.rearGunActive ? 0.018 : 0);
    }
  }

  function emitGhostTrainRearGunReplicaShots(encounter, count) {
    count = Math.min(4, Math.max(0, Math.floor(Number(count) || 0)));
    if (!encounter || !count || encounter.activeTailIndex < 0) return;
    var shotInterval = getGhostTrainRearGunInterval(encounter);
    for (var index = count - 1; index >= 0; index--) {
      acquireGhostTrainRearGunTracer(encounter, encounter.rearGunTargetAim, index * shotInterval, false);
    }
    encounter.rearGunMuzzleFlash = 1;
    var shot = getGhostTrainRearGunShot(encounter, encounter.rearGunTargetAim);
    if (shot && state.time - (encounter.rearGunLastSoundAt || -99) >= 0.16) {
      encounter.rearGunLastSoundAt = state.time;
      playGhostTrainRearMachineGunSound(shot.x, shot.z);
    }
  }

  function fireGhostTrainRearMachineGun(encounter, target) {
    if (!encounter || !target || !target.entry || encounter.activeTailIndex < 0) return false;
    encounter.rearGunSequence = Math.max(0, encounter.rearGunSequence || 0) + 1;
    encounter.rearGunMuzzleFlash = 1;
    acquireGhostTrainRearGunTracer(encounter, encounter.rearGunAim, 0, true);
    var shot = getGhostTrainRearGunShot(encounter, encounter.rearGunAim);
    if (shot && state.time - (encounter.rearGunLastSoundAt || -99) >= 0.16) {
      encounter.rearGunLastSoundAt = state.time;
      playGhostTrainRearMachineGunSound(shot.x, shot.z);
    }
    return true;
  }

  function updateGhostTrainRearMachineGun(encounter, dt, cosmeticOnly) {
    if (!encounter) return;
    attachGhostTrainRearMachineGun(encounter);
    encounter.rearGunMuzzleFlash = Math.max(0, (encounter.rearGunMuzzleFlash || 0) - Math.max(0, dt || 0) * 13.5);
    if (encounter.replica || cosmeticOnly) {
      var replicaBlend = 1 - Math.exp(-Math.max(0, dt || 0) * 18);
      encounter.rearGunAim = (Number(encounter.rearGunAim) || 0) + normalizeGhostTrainAngle(
        (Number(encounter.rearGunTargetAim) || 0) - (Number(encounter.rearGunAim) || 0)
      ) * replicaBlend;
    } else {
      var canAttack = !!(
        encounter.active && !encounter.defeated && encounter.materialized &&
        encounter.activeTailIndex >= 0 && !isGhostTrainTunnelAttackLocked(encounter)
      );
      var target = canAttack ? findGhostTrainRearGunTarget(encounter) : null;
      encounter.rearGunActive = !!target;
      encounter.rearGunTargetPlayerId = target ? target.entry.id || "solo" : "";
      encounter.rearGunTargetDistance = target ? target.distance : 0;
      encounter.rearGunTargetAim = target ? target.aim : 0;
      var hostBlend = 1 - Math.exp(-Math.max(0, dt || 0) * GHOST_TRAIN_REAR_GUN_TURN_SPEED);
      encounter.rearGunAim = (Number(encounter.rearGunAim) || 0) + normalizeGhostTrainAngle(
        encounter.rearGunTargetAim - (Number(encounter.rearGunAim) || 0)
      ) * hostBlend;
      if (target) {
        encounter.rearGunCooldown = (Number(encounter.rearGunCooldown) || 0) - Math.max(0, dt || 0);
        var aimError = Math.abs(normalizeGhostTrainAngle(target.aim - encounter.rearGunAim));
        var shotGuard = 0;
        while (encounter.rearGunCooldown <= 0 && aimError <= GHOST_TRAIN_REAR_GUN_FIRE_TOLERANCE && shotGuard < 3) {
          fireGhostTrainRearMachineGun(encounter, target);
          encounter.rearGunCooldown += getGhostTrainRearGunInterval(encounter);
          shotGuard += 1;
        }
      } else {
        encounter.rearGunCooldown = isGhostTrainTunnelAttackLocked(encounter)
          ? Math.max(Number(encounter.rearGunCooldown) || 0, getGhostTrainRearGunInterval(encounter))
          : 0;
      }
    }
    updateGhostTrainRearGunVisual(encounter, dt);
    updateGhostTrainRearGunTracers(encounter, dt);
  }

  function getGhostTrainSteamWaveRadius(age) {
    return clamp(
      GHOST_TRAIN_STEAM_WAVE_START_RADIUS + Math.max(0, Number(age) || 0) * GHOST_TRAIN_STEAM_WAVE_SPEED,
      GHOST_TRAIN_STEAM_WAVE_START_RADIUS,
      GHOST_TRAIN_STEAM_WAVE_MAX_RADIUS
    );
  }

  function createGhostTrainSteamWaveState() {
    return {
      hitPlayerIds: Object.create(null),
      puffNoise: new Float32Array(GHOST_TRAIN_STEAM_FRONT_PUFF_MAX * 5 + GHOST_TRAIN_STEAM_PLUME_PUFFS * 4),
    };
  }

  function clearGhostTrainSteamWaveHits(wave) {
    if (!wave) return;
    if (!wave.hitPlayerIds) {
      wave.hitPlayerIds = Object.create(null);
      return;
    }
    for (var playerId in wave.hitPlayerIds) delete wave.hitPlayerIds[playerId];
  }

  function prepareGhostTrainSteamPuffNoise(wave) {
    if (!wave) return;
    var requiredLength = GHOST_TRAIN_STEAM_FRONT_PUFF_MAX * 5 + GHOST_TRAIN_STEAM_PLUME_PUFFS * 4;
    if (!wave.puffNoise || wave.puffNoise.length !== requiredLength) wave.puffNoise = new Float32Array(requiredLength);
    var puffIndex;
    for (puffIndex = 0; puffIndex < GHOST_TRAIN_STEAM_FRONT_PUFF_MAX; puffIndex++) {
      var seed = wave.sequence * 37.719 + (puffIndex + 1) * 9.173;
      var noiseOffset = puffIndex * 5;
      wave.puffNoise[noiseOffset] = getGhostTrainSteamPuffNoise(seed);
      wave.puffNoise[noiseOffset + 1] = getGhostTrainSteamPuffNoise(seed + 19.19);
      wave.puffNoise[noiseOffset + 2] = getGhostTrainSteamPuffNoise(seed + 47.47);
      var rotationHalfAngle = (wave.particlePhase + puffIndex * 0.71 + (wave.puffNoise[noiseOffset] - 0.5) * 1.2) * 0.5;
      wave.puffNoise[noiseOffset + 3] = Math.sin(rotationHalfAngle);
      wave.puffNoise[noiseOffset + 4] = Math.cos(rotationHalfAngle);
    }
    var plumeOffset = GHOST_TRAIN_STEAM_FRONT_PUFF_MAX * 5;
    for (puffIndex = 0; puffIndex < GHOST_TRAIN_STEAM_PLUME_PUFFS; puffIndex++) {
      var plumeSeed = wave.sequence * 53.31 + (puffIndex + 1) * 17.17;
      var plumeNoiseOffset = plumeOffset + puffIndex * 4;
      wave.puffNoise[plumeNoiseOffset] = getGhostTrainSteamPuffNoise(plumeSeed);
      wave.puffNoise[plumeNoiseOffset + 1] = getGhostTrainSteamPuffNoise(plumeSeed + 31.7);
      var plumeRotationHalfAngle = (wave.particlePhase + puffIndex * 2.399963229728653) * 0.5;
      wave.puffNoise[plumeNoiseOffset + 2] = Math.sin(plumeRotationHalfAngle);
      wave.puffNoise[plumeNoiseOffset + 3] = Math.cos(plumeRotationHalfAngle);
    }
  }

  function releaseGhostTrainSteamWave(encounter, wave) {
    if (!encounter || !wave) return;
    clearGhostTrainSteamWaveHits(wave);
    wave.sequence = 0;
    wave.age = 0;
    wave.previousRadius = GHOST_TRAIN_STEAM_WAVE_START_RADIUS;
    wave.cosmeticOnly = false;
    encounter.steamWavePool.push(wave);
  }

  function findGhostTrainSteamWaveBySequence(encounter, sequence) {
    if (!encounter || !encounter.steamWaves) return null;
    for (var index = 0; index < encounter.steamWaves.length; index++) {
      if (encounter.steamWaves[index].sequence === sequence) return encounter.steamWaves[index];
    }
    return null;
  }

  function spawnGhostTrainSteamWave(encounter, cosmeticOnly, initialAge, sequence, originX, originZ) {
    if (!encounter || !encounter.segments || !encounter.segments[0]) return null;
    var resolvedSequence = Math.max(1, Math.floor(Number(sequence) || 0));
    if (!sequence) {
      encounter.steamWaveSequence = Math.max(0, encounter.steamWaveSequence || 0) + 1;
      resolvedSequence = encounter.steamWaveSequence;
    }
    var existing = findGhostTrainSteamWaveBySequence(encounter, resolvedSequence);
    if (existing) return existing;
    var wave = encounter.steamWavePool.length ? encounter.steamWavePool.pop() : encounter.steamWaves.shift();
    if (!wave) wave = createGhostTrainSteamWaveState();
    clearGhostTrainSteamWaveHits(wave);
    var engine = encounter.segments[0];
    wave.sequence = resolvedSequence;
    wave.x = Number.isFinite(Number(originX)) ? Number(originX) : engine.x;
    wave.z = Number.isFinite(Number(originZ)) ? Number(originZ) : engine.z;
    wave.stackX = wave.x + Math.sin(Number(engine.facingAngle) || 0) * GHOST_TRAIN_STACK_FORWARD_OFFSET;
    wave.stackZ = wave.z + Math.cos(Number(engine.facingAngle) || 0) * GHOST_TRAIN_STACK_FORWARD_OFFSET;
    wave.age = clamp(Number(initialAge) || 0, 0, GHOST_TRAIN_STEAM_WAVE_LIFE);
    wave.previousRadius = getGhostTrainSteamWaveRadius(wave.age);
    wave.cosmeticOnly = !!cosmeticOnly;
    wave.particlePhase = resolvedSequence * 2.399963229728653;
    prepareGhostTrainSteamPuffNoise(wave);
    encounter.steamWaves.push(wave);
    if (encounter.steamWaveVisualBatch) encounter.steamWaveVisualBatch.acquisitions += 1;

    if (wave.age <= 0.12) {
      var visibleGround = getCurrentVisibleGroundRect(ghostTrainSteamVisibleGroundScratch);
      if (!pointOutsideVisibleGround(wave.x, wave.z, 4.5, visibleGround)) {
        addLightFlash(wave.x, 1.15, wave.z, 0xc9fff3, 2.3, 6.2, 0.18);
      }
      if (state.time - (encounter.steamWaveLastSoundAt || -99) >= 0.22) {
        encounter.steamWaveLastSoundAt = state.time;
        playGhostTrainSteamWaveSound(wave.x, wave.z);
      }
    }
    return wave;
  }

  function getGhostTrainNewestSteamWave(encounter) {
    var newest = null;
    if (!encounter || !encounter.steamWaves) return null;
    for (var index = 0; index < encounter.steamWaves.length; index++) {
      var wave = encounter.steamWaves[index];
      if (!newest || wave.sequence > newest.sequence) newest = wave;
    }
    return newest;
  }

  function emitGhostTrainSteamWaveReplica(encounter, count, newestAge, newestSequence, newestX, newestZ) {
    count = Math.min(GHOST_TRAIN_STEAM_WAVE_CAP, Math.max(0, Math.floor(Number(count) || 0)));
    newestSequence = Math.max(0, Math.floor(Number(newestSequence) || 0));
    if (!encounter || !count || !newestSequence || !Number.isFinite(Number(newestAge))) return;
    var points = getGhostTrainRoutePoints(encounter);
    var speed = getGhostTrainSpeed(encounter);
    for (var offset = count - 1; offset >= 0; offset--) {
      var sequence = newestSequence - offset;
      var age = Number(newestAge) + offset * GHOST_TRAIN_STEAM_WAVE_INTERVAL;
      if (sequence <= 0 || age >= GHOST_TRAIN_STEAM_WAVE_LIFE) continue;
      var x = Number(newestX);
      var z = Number(newestZ);
      if (offset > 0 || !Number.isFinite(x) || !Number.isFinite(z)) {
        var sample = sampleGhostTrainTrack(points, encounter.engineDistance - speed * age, {});
        x = sample.x;
        z = sample.z;
      }
      spawnGhostTrainSteamWave(encounter, true, age, sequence, x, z);
    }
  }

  function getGhostTrainSteamPuffNoise(seed) {
    var value = Math.sin(seed * 12.9898 + 78.233) * 43758.5453123;
    return value - Math.floor(value);
  }

  function updateGhostTrainSteamWaveVisuals(encounter) {
    var batch = encounter && encounter.steamWaveVisualBatch;
    if (!batch) return;
    var count = Math.min(GHOST_TRAIN_STEAM_WAVE_CAP, encounter.steamWaves.length);
    batch.group.visible = count > 0;
    batch.core.count = count;
    batch.puffs.count = 0;
    batch.candidatePuffs = 0;
    batch.culledPuffs = 0;
    if (!count) return;
    var dummy = batch.dummy;
    var rotation = batch.rotation;
    var visibleGround = getCurrentVisibleGroundRect(ghostTrainSteamVisibleGroundScratch);
    dummy.rotation.set(-Math.PI / 2, 0, 0);
    var puffWriteIndex = 0;
    for (var index = 0; index < count; index++) {
      var wave = encounter.steamWaves[index];
      var radius = getGhostTrainSteamWaveRadius(wave.age);
      var lifeProgress = clamp(wave.age / GHOST_TRAIN_STEAM_WAVE_LIFE, 0, 1);
      var breathe = 1 + Math.sin(wave.age * 18 + wave.particlePhase) * 0.012;

      dummy.position.set(wave.x, 0.12, wave.z);
      dummy.scale.set(radius * breathe, radius * breathe, 1);
      dummy.updateMatrix();
      batch.core.setMatrixAt(index, dummy.matrix);
      batch.color.setRGB(0.88 - lifeProgress * 0.34, 1 - lifeProgress * 0.24, 0.95 - lifeProgress * 0.3);
      batch.core.setColorAt(index, batch.color);
      batch.matrixWrites += 1;

      var frontPuffCount = clamp(
        Math.round(24 + radius * 2.3),
        GHOST_TRAIN_STEAM_FRONT_PUFF_MIN,
        GHOST_TRAIN_STEAM_FRONT_PUFF_MAX
      );
      batch.candidatePuffs += frontPuffCount;
      var appear = clamp(wave.age / 0.13, 0, 1);
      var dissolve = clamp((1 - lifeProgress) / 0.24, 0, 1);
      for (var puffIndex = 0; puffIndex < frontPuffCount && puffWriteIndex < GHOST_TRAIN_STEAM_PUFF_CAP; puffIndex++) {
        var noiseOffset = puffIndex * 5;
        var noiseA = wave.puffNoise[noiseOffset];
        var noiseB = wave.puffNoise[noiseOffset + 1];
        var noiseC = wave.puffNoise[noiseOffset + 2];
        var roll = Math.sin(wave.age * 5.2 + noiseB * Math.PI * 2);
        var curl = Math.sin(wave.age * 4.6 + noiseC * 8);
        var puffAngle = puffIndex / frontPuffCount * Math.PI * 2 + wave.particlePhase;
        puffAngle += (noiseA - 0.5) * (Math.PI * 2 / frontPuffCount) * 0.7;
        puffAngle += roll * 0.065;
        var trailDepth = Math.min(3.2, 0.72 + radius * 0.145);
        var puffRadius = Math.max(
          0.42,
          radius + 0.3 - noiseA * trailDepth + (noiseB - 0.5) * 0.55 + curl * 0.24
        );
        var puffScale = (0.78 + noiseC * 0.72) * (0.96 + radius * 0.03) * (0.95 + roll * 0.045 + curl * 0.035);
        var puffX = wave.x + Math.cos(puffAngle) * puffRadius;
        var puffZ = wave.z + Math.sin(puffAngle) * puffRadius;
        if (pointOutsideVisibleGround(puffX, puffZ, puffScale * 2.2 + 0.8, visibleGround)) {
          batch.culledPuffs += 1;
          continue;
        }
        dummy.position.set(
          puffX,
          0.46 + noiseB * 0.88 + (roll + curl) * 0.07 + lifeProgress * 0.22,
          puffZ
        );
        dummy.quaternion.copy(camera.quaternion);
        rotation.set(0, 0, wave.puffNoise[noiseOffset + 3], wave.puffNoise[noiseOffset + 4]);
        dummy.quaternion.multiply(rotation);
        dummy.scale.set(
          puffScale * (1.04 + noiseA * 0.2),
          puffScale * (0.74 + noiseB * 0.38),
          1
        );
        dummy.updateMatrix();
        batch.puffs.setMatrixAt(puffWriteIndex, dummy.matrix);
        batch.color.setRGB(0.86 + noiseB * 0.12, 0.97 + noiseA * 0.03, 0.93 + noiseC * 0.07);
        batch.puffs.setColorAt(puffWriteIndex, batch.color);
        batch.puffAlpha.setX(puffWriteIndex, (0.31 + noiseA * 0.22) * appear * dissolve);
        puffWriteIndex += 1;
      }

      if (wave.age < GHOST_TRAIN_STEAM_PLUME_LIFE) {
        var plumeProgress = clamp(wave.age / GHOST_TRAIN_STEAM_PLUME_LIFE, 0, 1);
        var plumeEnvelope = Math.sin(plumeProgress * Math.PI);
        var plumeNoiseBase = GHOST_TRAIN_STEAM_FRONT_PUFF_MAX * 5;
        batch.candidatePuffs += GHOST_TRAIN_STEAM_PLUME_PUFFS;
        for (var plumeIndex = 0; plumeIndex < GHOST_TRAIN_STEAM_PLUME_PUFFS && puffWriteIndex < GHOST_TRAIN_STEAM_PUFF_CAP; plumeIndex++) {
          var plumeNoiseOffset = plumeNoiseBase + plumeIndex * 4;
          var plumeNoiseA = wave.puffNoise[plumeNoiseOffset];
          var plumeNoiseB = wave.puffNoise[plumeNoiseOffset + 1];
          var plumeAngle = wave.particlePhase + plumeIndex * 2.399963229728653 + plumeProgress * (plumeNoiseA - 0.5) * 1.4;
          var plumeRadius = 0.22 + plumeProgress * (1.35 + plumeNoiseA * 1.15);
          var plumeX = wave.stackX + Math.cos(plumeAngle) * plumeRadius;
          var plumeZ = wave.stackZ + Math.sin(plumeAngle) * plumeRadius;
          var plumeScale = (0.58 + plumeProgress * 1.35) * (0.82 + plumeNoiseA * 0.48);
          if (pointOutsideVisibleGround(plumeX, plumeZ, plumeScale * 2 + 6, visibleGround)) {
            batch.culledPuffs += 1;
            continue;
          }
          dummy.position.set(
            plumeX,
            GHOST_TRAIN_STACK_SMOKE_HEIGHT + 0.18 + plumeProgress * (1.7 + plumeNoiseB * 0.8) + plumeIndex * 0.05,
            plumeZ
          );
          dummy.quaternion.copy(camera.quaternion);
          rotation.set(0, 0, wave.puffNoise[plumeNoiseOffset + 2], wave.puffNoise[plumeNoiseOffset + 3]);
          dummy.quaternion.multiply(rotation);
          dummy.scale.set(plumeScale * (1.05 + plumeNoiseB * 0.2), plumeScale * (0.86 + plumeNoiseA * 0.24), 1);
          dummy.updateMatrix();
          batch.puffs.setMatrixAt(puffWriteIndex, dummy.matrix);
          batch.color.setRGB(0.94 + plumeNoiseA * 0.06, 0.99, 0.96 + plumeNoiseB * 0.04);
          batch.puffs.setColorAt(puffWriteIndex, batch.color);
          batch.puffAlpha.setX(puffWriteIndex, plumeEnvelope * (0.64 + plumeNoiseB * 0.22));
          puffWriteIndex += 1;
        }
      }
    }
    batch.puffs.count = puffWriteIndex;
    batch.peakVisiblePuffs = Math.max(batch.peakVisiblePuffs, puffWriteIndex);
    batch.matrixWrites += puffWriteIndex;
    for (var meshIndex = 0; meshIndex < batch.meshes.length; meshIndex++) {
      batch.meshes[meshIndex].instanceMatrix.needsUpdate = true;
      if (batch.meshes[meshIndex].instanceColor) batch.meshes[meshIndex].instanceColor.needsUpdate = true;
    }
    batch.puffAlpha.needsUpdate = true;
  }

  function updateGhostTrainSteamWaveAttack(encounter, dt, cosmeticOnly) {
    if (!encounter || !encounter.steamWaves || !encounter.steamWavePool) return;
    dt = Math.max(0, Number(dt) || 0);
    var canEmit = !!(
      !cosmeticOnly && !encounter.replica && encounter.active && !encounter.defeated &&
      encounter.materialized && encounter.activeTailIndex === 0 && !isGhostTrainTunnelAttackLocked(encounter)
    );
    if (canEmit) {
      encounter.steamWaveCooldown = (Number(encounter.steamWaveCooldown) || 0) - dt;
      var emitGuard = 0;
      while (encounter.steamWaveCooldown <= 0 && emitGuard < 2) {
        spawnGhostTrainSteamWave(encounter, false, 0);
        encounter.steamWaveCooldown += GHOST_TRAIN_STEAM_WAVE_INTERVAL;
        emitGuard += 1;
      }
    } else if (
      !encounter.materialized || encounter.activeTailIndex !== 0 || encounter.defeated ||
      isGhostTrainTunnelAttackLocked(encounter)
    ) {
      encounter.steamWaveCooldown = GHOST_TRAIN_STEAM_WAVE_FIRST_DELAY;
    }

    var entries = encounter.steamWaves.length && !cosmeticOnly && !encounter.replica
      ? getGhostTrainPlayerEntries()
      : null;
    for (var waveIndex = encounter.steamWaves.length - 1; waveIndex >= 0; waveIndex--) {
      var wave = encounter.steamWaves[waveIndex];
      var previousRadius = Math.max(GHOST_TRAIN_STEAM_WAVE_START_RADIUS, Number(wave.previousRadius) || GHOST_TRAIN_STEAM_WAVE_START_RADIUS);
      wave.age += dt;
      if (wave.age >= GHOST_TRAIN_STEAM_WAVE_LIFE) {
        encounter.steamWaves.splice(waveIndex, 1);
        releaseGhostTrainSteamWave(encounter, wave);
        continue;
      }
      var radius = getGhostTrainSteamWaveRadius(wave.age);
      if (!cosmeticOnly && !wave.cosmeticOnly) {
        var innerEdge = Math.max(0, previousRadius - GHOST_TRAIN_STEAM_WAVE_HIT_WIDTH);
        var outerEdge = radius + GHOST_TRAIN_STEAM_WAVE_HIT_WIDTH;
        for (var entryIndex = 0; entries && entryIndex < entries.length; entryIndex++) {
          var entry = entries[entryIndex];
          var playerKey = String(entry.id || "solo");
          if (wave.hitPlayerIds[playerKey]) continue;
          var playerRadius = Math.max(0, Number(entry.entity.radius) || 0);
          var distance = Math.hypot(entry.entity.x - wave.x, entry.entity.z - wave.z);
          if (distance + playerRadius < innerEdge || distance - playerRadius > outerEdge) continue;
          wave.hitPlayerIds[playerKey] = true;
          damagePlayer(GHOST_TRAIN_STEAM_WAVE_DAMAGE, entry.entity);
          encounter.steamWaveHitCount = Math.max(0, encounter.steamWaveHitCount || 0) + 1;
          encounter.steamWaveDamageApplied = Math.max(0, encounter.steamWaveDamageApplied || 0) + GHOST_TRAIN_STEAM_WAVE_DAMAGE;
          encounter.steamWaveLastHitPlayerId = playerKey;
        }
      }
      wave.previousRadius = radius;
    }
    updateGhostTrainSteamWaveVisuals(encounter);
  }

  function setGhostTrainCannonProjectileCount(batch, count) {
    batch.projectileCount = Math.max(0, count || 0);
    batch.core.count = batch.projectileCount;
    batch.glow.count = batch.projectileCount;
    batch.trail.count = batch.projectileCount;
  }

  function setGhostTrainCannonTrajectoryCount(batch, count) {
    batch.trajectoryCount = Math.max(0, count || 0);
    batch.trajectoryOuter.count = batch.trajectoryCount;
    batch.trajectoryInner.count = batch.trajectoryCount;
  }

  function markGhostTrainCannonProjectileMatricesDirty(batch) {
    batch.core.instanceMatrix.needsUpdate = true;
    batch.glow.instanceMatrix.needsUpdate = true;
    batch.trail.instanceMatrix.needsUpdate = true;
  }

  function markGhostTrainCannonTrajectoryMatricesDirty(batch) {
    batch.trajectoryOuter.instanceMatrix.needsUpdate = true;
    batch.trajectoryInner.instanceMatrix.needsUpdate = true;
  }

  function acquireGhostTrainCannonballVisual(x, z, angle) {
    var encounter = state.ghostTrain;
    var batch = encounter && encounter.cannonVisualBatch;
    if (!batch || !batch.freeProjectiles.length) return null;
    var visual = batch.freeProjectiles.pop();
    visual.inUse = true;
    visual.visible = true;
    batch.projectileActive[visual.slot] = true;
    batch.projectileInUse += 1;
    batch.projectileAcquisitions += 1;
    setGhostTrainCannonProjectileCount(batch, Math.max(batch.projectileCount, visual.slot + 1));
    updateGhostTrainCannonballVisual(visual, x, 1.72, z, angle, 0, 1);
    return visual;
  }

  function updateGhostTrainCannonballVisual(visual, x, y, z, angle, spin, glowScale) {
    if (!visual || !visual.inUse) return;
    var batch = visual.batch;
    var dummy = batch.projectileDummy;
    dummy.position.set(x, y, z);
    dummy.rotation.set(0, angle || 0, spin || 0);
    dummy.scale.set(1, 1, 1);
    dummy.updateMatrix();
    batch.projectileBaseMatrix.copy(dummy.matrix);
    batch.core.setMatrixAt(visual.slot, batch.projectileBaseMatrix);
    dummy.scale.setScalar(glowScale == null ? 1 : glowScale);
    dummy.updateMatrix();
    batch.glow.setMatrixAt(visual.slot, dummy.matrix);
    batch.trailMatrix.multiplyMatrices(batch.projectileBaseMatrix, batch.trailLocalMatrix);
    batch.trail.setMatrixAt(visual.slot, batch.trailMatrix);
    batch.matrixWrites += 3;
    markGhostTrainCannonProjectileMatricesDirty(batch);
  }

  function releaseGhostTrainCannonballVisual(visual) {
    if (!visual || !visual.inUse) return;
    var batch = visual.batch;
    var slot = visual.slot;
    visual.inUse = false;
    visual.visible = false;
    batch.projectileActive[slot] = false;
    batch.core.setMatrixAt(slot, batch.hiddenMatrix);
    batch.glow.setMatrixAt(slot, batch.hiddenMatrix);
    batch.trail.setMatrixAt(slot, batch.hiddenMatrix);
    batch.projectileInUse = Math.max(0, batch.projectileInUse - 1);
    batch.freeProjectiles.push(visual);
    if (slot + 1 === batch.projectileCount) {
      var nextCount = slot;
      while (nextCount > 0 && !batch.projectileActive[nextCount - 1]) nextCount -= 1;
      setGhostTrainCannonProjectileCount(batch, nextCount);
    }
    markGhostTrainCannonProjectileMatricesDirty(batch);
  }

  function createGhostTrainCannonballVisual(x, z, angle) {
    return acquireGhostTrainCannonballVisual(x, z, angle);
  }

  function getGhostTrainCannonTrajectoryDistance(originX, originZ, dirX, dirZ, speed, life) {
    var distance = Math.max(0.1, speed * life);
    var limitX = ARENA_W / 2 + 12;
    var limitZ = ARENA_D / 2 + 12;
    if (dirX > 0.00001) distance = Math.min(distance, (limitX - originX) / dirX);
    else if (dirX < -0.00001) distance = Math.min(distance, (-limitX - originX) / dirX);
    if (dirZ > 0.00001) distance = Math.min(distance, (limitZ - originZ) / dirZ);
    else if (dirZ < -0.00001) distance = Math.min(distance, (-limitZ - originZ) / dirZ);
    return Math.max(0.1, distance);
  }

  function findNearestGhostTrainCannonTarget(originX, originZ) {
    var entries = getGhostTrainPlayerEntries();
    var nearest = null;
    var nearestDistanceSq = Infinity;
    for (var i = 0; i < entries.length; i++) {
      var dx = entries[i].entity.x - originX;
      var dz = entries[i].entity.z - originZ;
      var distanceSq = dx * dx + dz * dz;
      if (
        distanceSq < nearestDistanceSq - 0.0001 ||
        (Math.abs(distanceSq - nearestDistanceSq) <= 0.0001 && nearest && String(entries[i].id) < String(nearest.id))
      ) {
        nearest = entries[i];
        nearestDistanceSq = distanceSq;
      }
    }
    return nearest ? { entry: nearest, distance: Math.sqrt(nearestDistanceSq) } : null;
  }

  function getGhostTrainCannonAimLimit(encounter) {
    var attack = String(encounter && (encounter.attackKind || encounter.action) || "broadside");
    return GHOST_TRAIN_CANNON_AIM_LIMITS[attack] || GHOST_TRAIN_CANNON_AIM_LIMITS.broadside;
  }

  function findGhostTrainCannonMount(segment, side, mountOffset) {
    var parts = segment && segment.group && segment.group.userData.ghostTrainParts || {};
    var cannons = parts.cannons || [];
    side = Number(side) < 0 ? -1 : 1;
    for (var i = 0; i < cannons.length; i++) {
      if (cannons[i].side === side && Math.abs((cannons[i].offsetZ || 0) - mountOffset) < 0.05) return cannons[i];
    }
    return null;
  }

  function aimGhostTrainCannon(segment, side, mountOffset, aimAngle, holdSeconds, snap) {
    var cannon = findGhostTrainCannonMount(segment, side, mountOffset);
    if (!cannon) return false;
    cannon.targetAimAngle = clamp(Number(aimAngle) || 0, -1.3, 1.3);
    cannon.aimHoldUntil = Math.max(cannon.aimHoldUntil || 0, state.time + Math.max(0.05, Number(holdSeconds) || 0.05));
    if (snap) {
      cannon.aimAngle = cannon.targetAimAngle;
      cannon.pivot.rotation.y = cannon.aimAngle;
    }
    return true;
  }

  function releaseGhostTrainCannonAim(encounter) {
    if (!encounter || !encounter.segments) return;
    for (var segmentIndex = 1; segmentIndex < encounter.segments.length; segmentIndex++) {
      var segment = encounter.segments[segmentIndex];
      var parts = segment && segment.group && segment.group.userData.ghostTrainParts || {};
      var cannons = parts.cannons || [];
      for (var cannonIndex = 0; cannonIndex < cannons.length; cannonIndex++) {
        cannons[cannonIndex].targetAimAngle = 0;
        cannons[cannonIndex].aimHoldUntil = 0;
      }
    }
  }

  function primeGhostTrainCannonAim(encounter, holdSeconds) {
    if (!encounter || !encounter.segments) return;
    for (var segmentIndex = 1; segmentIndex <= encounter.activeTailIndex; segmentIndex++) {
      var segment = encounter.segments[segmentIndex];
      if (!segment || !segment.attached) continue;
      var parts = segment.group && segment.group.userData.ghostTrainParts || {};
      var cannons = parts.cannons || [];
      for (var cannonIndex = 0; cannonIndex < cannons.length; cannonIndex++) {
        var cannon = cannons[cannonIndex];
        var shot = getGhostTrainCannonShot(encounter, segment, cannon.side, cannon.offsetZ);
        if (shot) aimGhostTrainCannon(segment, cannon.side, cannon.offsetZ, shot.aimDelta, holdSeconds, false);
      }
    }
  }

  function getGhostTrainCannonShot(encounter, segment, side, mountOffset) {
    if (!encounter || !segment || !segment.attached || segment.index <= 0) return null;
    side = Number(side) < 0 ? -1 : 1;
    mountOffset = Number(mountOffset);
    if (!Number.isFinite(mountOffset)) mountOffset = -GHOST_TRAIN_CANNON_MOUNT_OFFSET;
    mountOffset = clamp(mountOffset, -GHOST_TRAIN_CANNON_MOUNT_OFFSET, GHOST_TRAIN_CANNON_MOUNT_OFFSET);
    var angle = segment.facingAngle || 0;
    var broadsideDirX = Math.cos(angle) * side;
    var broadsideDirZ = -Math.sin(angle) * side;
    var forwardX = Math.sin(angle);
    var forwardZ = Math.cos(angle);
    var pivotX = segment.x + broadsideDirX * 1.5 + forwardX * mountOffset;
    var pivotZ = segment.z + broadsideDirZ * 1.5 + forwardZ * mountOffset;
    var broadsideAngle = Math.atan2(broadsideDirX, broadsideDirZ);
    var aimLimit = getGhostTrainCannonAimLimit(encounter);
    var aimDelta = 0;
    var dirX = broadsideDirX;
    var dirZ = broadsideDirZ;
    var originX = pivotX + dirX * 1.54;
    var originZ = pivotZ + dirZ * 1.54;
    var nearestTarget = findNearestGhostTrainCannonTarget(originX, originZ);
    var target = nearestTarget && nearestTarget.entry.entity;
    var speed = GHOST_TRAIN_CANNON_SPEED + encounter.phase * 1.4;
    if (target) {
      var wantedAngle = Math.atan2(target.x - originX, target.z - originZ);
      aimDelta = clamp(normalizeGhostTrainAngle(wantedAngle - broadsideAngle), -aimLimit, aimLimit);
      var firedAngle = broadsideAngle + aimDelta;
      dirX = Math.sin(firedAngle);
      dirZ = Math.cos(firedAngle);
      originX = pivotX + dirX * 1.54;
      originZ = pivotZ + dirZ * 1.54;
      nearestTarget = findNearestGhostTrainCannonTarget(originX, originZ) || nearestTarget;
      target = nearestTarget && nearestTarget.entry.entity;
      if (target) {
        wantedAngle = Math.atan2(target.x - originX, target.z - originZ);
        aimDelta = clamp(normalizeGhostTrainAngle(wantedAngle - broadsideAngle), -aimLimit, aimLimit);
        firedAngle = broadsideAngle + aimDelta;
        dirX = Math.sin(firedAngle);
        dirZ = Math.cos(firedAngle);
        originX = pivotX + dirX * 1.54;
        originZ = pivotZ + dirZ * 1.54;
      }
    }
    var targetDistance = target ? Math.hypot(target.x - originX, target.z - originZ) : 0;
    var distance = getGhostTrainCannonTrajectoryDistance(originX, originZ, dirX, dirZ, speed, GHOST_TRAIN_CANNON_LIFE);
    return {
      originX: originX,
      originZ: originZ,
      dirX: dirX,
      dirZ: dirZ,
      angle: Math.atan2(dirX, dirZ),
      broadsideAngle: broadsideAngle,
      aimDelta: aimDelta,
      aimLimit: aimLimit,
      mountOffset: mountOffset,
      speed: speed,
      distance: distance,
      endX: originX + dirX * distance,
      endZ: originZ + dirZ * distance,
      targetPlayerId: nearestTarget ? String(nearestTarget.entry.id || "") : "",
      targetX: target ? target.x : null,
      targetZ: target ? target.z : null,
      targetDistance: targetDistance,
    };
  }

  function createGhostTrainCannonTrajectoryVisual(shot, segmentIndex, step) {
    if (!shot) return null;
    var encounter = state.ghostTrain;
    var batch = encounter && encounter.cannonVisualBatch;
    if (!batch || !batch.freeTrajectories.length) return null;
    var trajectory = batch.freeTrajectories.pop();
    trajectory.inUse = true;
    trajectory.visible = true;
    trajectory.userData.segmentIndex = segmentIndex;
    trajectory.userData.step = step;
    trajectory.userData.fired = false;
    batch.trajectoryActive[trajectory.slot] = true;
    batch.trajectoryInUse += 1;
    batch.trajectoryAcquisitions += 1;
    setGhostTrainCannonTrajectoryCount(batch, Math.max(batch.trajectoryCount, trajectory.slot + 1));
    updateGhostTrainCannonTrajectoryVisual(trajectory, shot.originX, shot.originZ, shot.endX, shot.endZ, false);
    return trajectory;
  }

  function updateGhostTrainCannonTrajectoryVisual(trajectory, startX, startZ, endX, endZ, fired) {
    if (!trajectory || !trajectory.inUse) return;
    var dx = endX - startX;
    var dz = endZ - startZ;
    var length = Math.hypot(dx, dz);
    trajectory.visible = length > 0.04;
    var warningPulse = fired ? 1 : 0.94 + Math.sin(state.time * 22 + (trajectory.userData.step || 0)) * 0.08;
    trajectory.userData.startX = startX;
    trajectory.userData.startZ = startZ;
    trajectory.userData.endX = endX;
    trajectory.userData.endZ = endZ;
    trajectory.userData.length = length;
    trajectory.userData.fired = !!fired;
    var batch = trajectory.batch;
    if (!trajectory.visible) {
      batch.trajectoryOuter.setMatrixAt(trajectory.slot, batch.hiddenMatrix);
      batch.trajectoryInner.setMatrixAt(trajectory.slot, batch.hiddenMatrix);
      markGhostTrainCannonTrajectoryMatricesDirty(batch);
      return;
    }
    var angle = Math.atan2(dx, dz);
    var dummy = batch.trajectoryDummy;
    dummy.position.set((startX + endX) * 0.5, 0.16, (startZ + endZ) * 0.5);
    dummy.rotation.set(0, angle, 0);
    dummy.scale.set(warningPulse * 1.16, 0.035, Math.max(0.001, length));
    dummy.updateMatrix();
    batch.trajectoryOuter.setMatrixAt(trajectory.slot, dummy.matrix);
    dummy.position.y = 0.195;
    dummy.scale.set(warningPulse * 0.58, 0.045, Math.max(0.001, length));
    dummy.updateMatrix();
    batch.trajectoryInner.setMatrixAt(trajectory.slot, dummy.matrix);
    batch.matrixWrites += 2;
    markGhostTrainCannonTrajectoryMatricesDirty(batch);
  }

  function releaseGhostTrainCannonTrajectoryVisual(trajectory) {
    if (!trajectory || !trajectory.inUse) return;
    var batch = trajectory.batch;
    var slot = trajectory.slot;
    trajectory.inUse = false;
    trajectory.visible = false;
    trajectory.userData.segmentIndex = -1;
    trajectory.userData.step = -1;
    trajectory.userData.fired = false;
    trajectory.userData.length = 0;
    batch.trajectoryActive[slot] = false;
    batch.trajectoryOuter.setMatrixAt(slot, batch.hiddenMatrix);
    batch.trajectoryInner.setMatrixAt(slot, batch.hiddenMatrix);
    batch.trajectoryInUse = Math.max(0, batch.trajectoryInUse - 1);
    batch.freeTrajectories.push(trajectory);
    if (slot + 1 === batch.trajectoryCount) {
      var nextCount = slot;
      while (nextCount > 0 && !batch.trajectoryActive[nextCount - 1]) nextCount -= 1;
      setGhostTrainCannonTrajectoryCount(batch, nextCount);
    }
    markGhostTrainCannonTrajectoryMatricesDirty(batch);
  }

  function disposeGhostTrainCannonVisualBatch(batch) {
    if (!batch) return;
    setGhostTrainCannonProjectileCount(batch, 0);
    setGhostTrainCannonTrajectoryCount(batch, 0);
    for (var i = 0; i < batch.meshes.length; i++) {
      if (batch.meshes[i] && typeof batch.meshes[i].dispose === "function") batch.meshes[i].dispose();
    }
    removeObject3D(batch.group);
  }

  function clearGhostTrainCannonHitMap(map) {
    if (!map) return Object.create(null);
    for (var key in map) {
      if (Object.prototype.hasOwnProperty.call(map, key)) delete map[key];
    }
    return map;
  }

  function createGhostTrainCannonballState() {
    ghostTrainCannonballStateCreated += 1;
    return {
      _pooled: false,
      hitPlayerIds: Object.create(null),
      hitEnemyIds: Object.create(null),
    };
  }

  function prewarmGhostTrainCannonballStatePool() {
    while (ghostTrainCannonballStatePool.length < GHOST_TRAIN_CANNONBALL_CAP) {
      var ball = createGhostTrainCannonballState();
      ball._pooled = true;
      ghostTrainCannonballStatePool.push(ball);
    }
  }

  function acquireGhostTrainCannonballState() {
    if (ghostTrainCannonballStatePool.length) return ghostTrainCannonballStatePool.pop();
    return createGhostTrainCannonballState();
  }

  function releaseGhostTrainCannonballState(ball) {
    if (!ball || ball._pooled) return;
    if (ball.mesh) releaseGhostTrainCannonballVisual(ball.mesh);
    if (ball.trajectory) releaseGhostTrainCannonTrajectoryVisual(ball.trajectory);
    ball.mesh = null;
    ball.trajectory = null;
    ball.hitPlayerIds = clearGhostTrainCannonHitMap(ball.hitPlayerIds);
    ball.hitEnemyIds = clearGhostTrainCannonHitMap(ball.hitEnemyIds);
    ball._pooled = true;
    ghostTrainCannonballStatePool.push(ball);
  }

  function updateGhostTrainCannonTrajectoryForBall(ball) {
    if (!ball || !ball.trajectory) return;
    updateGhostTrainCannonTrajectoryVisual(ball.trajectory, ball.x, ball.z, ball.trajectoryEndX, ball.trajectoryEndZ, true);
  }

  function hitEnemyWithGhostTrainCannonball(enemy) {
    var ball = ghostTrainCannonCollisionBall;
    if (!ball || !enemy || enemy.active === false || enemy.isGhostTrainSegment || enemy.isBellRinger) return;
    var enemyKey = String(enemy.networkId || enemy.spatialOrder || state.enemies.indexOf(enemy));
    if (ball.hitEnemyIds[enemyKey]) return;
    var hitTime = getSegmentCircleEntryTime(ball.oldX, ball.oldZ, ball.x, ball.z, enemy.x, enemy.z, ball.radius + enemy.radius);
    if (hitTime == null) return;
    ball.hitEnemyIds[enemyKey] = true;
    ball.hitCount += 1;
    damageEnemy(enemy, Math.min(ball.damage, Math.max(1, enemy.maxHp * 0.7)), enemy.x, enemy.z, { type: "ghostTrainCannon" });
  }

  function fireGhostTrainCannon(encounter, segment, side, cosmeticOnly, preparedShot, preparedTrajectory, mountOffset, deferSound) {
    if (!encounter || !segment || !segment.attached || segment.index <= 0) return null;
    var shot = preparedShot || getGhostTrainCannonShot(encounter, segment, side, mountOffset);
    if (!shot) return null;
    aimGhostTrainCannon(segment, side, shot.mountOffset, shot.aimDelta, 0.42, true);
    var trajectory = preparedTrajectory || createGhostTrainCannonTrajectoryVisual(shot, segment.index, -1);
    if (trajectory) {
      trajectory.userData.segmentIndex = segment.index;
      trajectory.userData.fired = true;
      updateGhostTrainCannonTrajectoryVisual(trajectory, shot.originX, shot.originZ, shot.endX, shot.endZ, true);
    }
    var mesh = createGhostTrainCannonballVisual(shot.originX, shot.originZ, shot.angle);
    var ball = acquireGhostTrainCannonballState();
    ball._pooled = false;
    ball.id = ++encounter.cannonSequence;
    ball.x = shot.originX;
    ball.z = shot.originZ;
    ball.oldX = shot.originX;
    ball.oldZ = shot.originZ;
    ball.y = 1.72;
    ball.dirX = shot.dirX;
    ball.dirZ = shot.dirZ;
    ball.side = side < 0 ? -1 : 1;
    ball.angle = shot.angle;
    ball.spin = 0;
    ball.broadsideAngle = shot.broadsideAngle;
    ball.aimDelta = shot.aimDelta;
    ball.aimLimit = shot.aimLimit;
    ball.speed = shot.speed;
    ball.life = GHOST_TRAIN_CANNON_LIFE;
    ball.radius = GHOST_TRAIN_CANNON_RADIUS;
    ball.damage = GHOST_TRAIN_CANNON_DAMAGE;
    ball.piercing = true;
    ball.cosmeticOnly = !!cosmeticOnly;
    ball.hitPlayerIds = clearGhostTrainCannonHitMap(ball.hitPlayerIds);
    ball.hitEnemyIds = clearGhostTrainCannonHitMap(ball.hitEnemyIds);
    ball.hitCount = 0;
    ball.trailTimer = 0;
    ball.mesh = mesh;
    ball.trajectory = trajectory;
    ball.trajectoryEndX = shot.endX;
    ball.trajectoryEndZ = shot.endZ;
    ball.mountOffset = shot.mountOffset;
    ball.targetPlayerId = shot.targetPlayerId || "";
    ball.targetX = shot.targetX;
    ball.targetZ = shot.targetZ;
    ball.targetDistance = shot.targetDistance || 0;
    while (state.ghostTrainCannonballs.length >= GHOST_TRAIN_CANNONBALL_CAP) {
      var retiredBall = state.ghostTrainCannonballs.shift();
      releaseGhostTrainCannonballState(retiredBall);
    }
    state.ghostTrainCannonballs.push(ball);
    var parts = segment.group && segment.group.userData.ghostTrainParts || {};
    var cannons = parts.cannons || [];
    for (var i = 0; i < cannons.length; i++) {
      if (cannons[i].side === side && Math.abs((cannons[i].offsetZ || 0) - shot.mountOffset) < 0.05) cannons[i].recoil = 1;
    }
    addLightFlash(shot.originX, 1.72, shot.originZ, 0x5dffd5, 2.8, 6, 0.13);
    if (!deferSound) playGhostTrainCannonSound(shot.originX, shot.originZ);
    return ball;
  }

  function getGhostTrainCannonStepDescriptor(encounter, step, side) {
    var wagonCount = Math.max(0, encounter && encounter.activeTailIndex || 0);
    if (!encounter || !wagonCount || step < 0) return null;
    var segmentIndex = 1 + step % wagonCount;
    var segment = encounter.segments[segmentIndex];
    if (!segment || !segment.attached) return null;
    side = Number(side) < 0 ? -1 : 1;
    var mountIndex = Math.floor(step / wagonCount) % 2;
    var mountOffset = mountIndex ? GHOST_TRAIN_CANNON_MOUNT_OFFSET : -GHOST_TRAIN_CANNON_MOUNT_OFFSET;
    return { segmentIndex: segmentIndex, segment: segment, side: side, mountIndex: mountIndex, mountOffset: mountOffset };
  }

  function findGhostTrainCannonTelegraphIndex(encounter, step, side) {
    var telegraphs = encounter && encounter.cannonTelegraphs || [];
    var wantedSide = Number(side) < 0 ? -1 : 1;
    for (var i = 0; i < telegraphs.length; i++) {
      if (telegraphs[i].step === step && telegraphs[i].side === wantedSide) return i;
    }
    return -1;
  }

  function updateGhostTrainCannonSchedule(encounter, cosmeticOnly) {
    var cannonAttack = encounter && (encounter.action === "broadside" || encounter.action === "crossfire" || encounter.action === "ram");
    if (
      !encounter || !encounter.materialized || !encounter.vulnerable || encounter.activeTailIndex <= 0 ||
      !cannonAttack || isGhostTrainTunnelAttackLocked(encounter)
    ) {
      clearGhostTrainCannonTelegraphs(encounter);
      return;
    }
    if (!encounter.cannonTelegraphs) encounter.cannonTelegraphs = [];
    var elapsed = Math.max(0, encounter.actionDuration - encounter.actionTimer);
    for (var pendingIndex = encounter.cannonTelegraphs.length - 1; pendingIndex >= 0; pendingIndex--) {
      var pending = encounter.cannonTelegraphs[pendingIndex];
      var pendingDescriptor = getGhostTrainCannonStepDescriptor(encounter, pending.step, pending.side);
      var pendingShot = pendingDescriptor && getGhostTrainCannonShot(encounter, pendingDescriptor.segment, pendingDescriptor.side, pendingDescriptor.mountOffset);
      if (!pendingDescriptor || !pendingShot) {
        if (pending.trajectory) releaseGhostTrainCannonTrajectoryVisual(pending.trajectory);
        encounter.cannonTelegraphs.splice(pendingIndex, 1);
        continue;
      }
      pending.segmentIndex = pendingDescriptor.segmentIndex;
      pending.side = pendingDescriptor.side;
      pending.mountIndex = pendingDescriptor.mountIndex;
      pending.mountOffset = pendingDescriptor.mountOffset;
      pending.shot = pendingShot;
      pending.targetPlayerId = pendingShot.targetPlayerId || "";
      pending.targetX = pendingShot.targetX;
      pending.targetZ = pendingShot.targetZ;
      aimGhostTrainCannon(
        pendingDescriptor.segment,
        pendingDescriptor.side,
        pendingDescriptor.mountOffset,
        pendingShot.aimDelta,
        Math.max(0.12, pending.shotAt - elapsed + 0.34),
        false
      );
      updateGhostTrainCannonTrajectoryVisual(pending.trajectory, pendingShot.originX, pendingShot.originZ, pendingShot.endX, pendingShot.endZ, false);
    }
    var cannonInterval = getGhostTrainCannonInterval(encounter);
    var dueStep = elapsed < GHOST_TRAIN_CANNON_FIRST_SHOT_TIME
      ? -1
      : Math.floor((elapsed - GHOST_TRAIN_CANNON_FIRST_SHOT_TIME) / cannonInterval);
    var guard = 0;
    while (encounter.lastCannonStep < dueStep && guard < 8) {
      var firingStep = encounter.lastCannonStep + 1;
      var salvoSoundX = 0;
      var salvoSoundZ = 0;
      var salvoSoundCount = 0;
      for (var firingSideIndex = 0; firingSideIndex < GHOST_TRAIN_CANNON_SIDES.length; firingSideIndex++) {
        var firingSide = GHOST_TRAIN_CANNON_SIDES[firingSideIndex];
        var firingDescriptor = getGhostTrainCannonStepDescriptor(encounter, firingStep, firingSide);
        var telegraphIndex = findGhostTrainCannonTelegraphIndex(encounter, firingStep, firingSide);
        var telegraph = telegraphIndex >= 0 ? encounter.cannonTelegraphs.splice(telegraphIndex, 1)[0] : null;
        if (firingDescriptor) {
          var shot = getGhostTrainCannonShot(encounter, firingDescriptor.segment, firingDescriptor.side, firingDescriptor.mountOffset);
          var trajectory = telegraph && telegraph.trajectory;
          if (!trajectory && shot) trajectory = createGhostTrainCannonTrajectoryVisual(shot, firingDescriptor.segmentIndex, firingStep);
          var fired = fireGhostTrainCannon(encounter, firingDescriptor.segment, firingDescriptor.side, cosmeticOnly, shot, trajectory, firingDescriptor.mountOffset, true);
          if (fired) {
            salvoSoundX += fired.x;
            salvoSoundZ += fired.z;
            salvoSoundCount += 1;
          }
          if (!fired && trajectory) releaseGhostTrainCannonTrajectoryVisual(trajectory);
        } else if (telegraph && telegraph.trajectory) {
          releaseGhostTrainCannonTrajectoryVisual(telegraph.trajectory);
        }
      }
      if (salvoSoundCount > 0) {
        playGhostTrainCannonSound(salvoSoundX / salvoSoundCount, salvoSoundZ / salvoSoundCount, 1.18);
        encounter.cannonSalvoSoundCount = Math.max(0, encounter.cannonSalvoSoundCount || 0) + 1;
        if (encounter.cannonVisualBatch) encounter.cannonVisualBatch.salvoSoundVoices += 1;
      }
      encounter.lastCannonStep = firingStep;
      guard += 1;
    }
    var warningStep = encounter.lastCannonStep + 1;
    var shotTime = GHOST_TRAIN_CANNON_FIRST_SHOT_TIME + warningStep * cannonInterval;
    var warningTime = shotTime - getGhostTrainCannonWarningLead(encounter);
    if (shotTime <= encounter.actionDuration + 0.0001 && elapsed >= warningTime && elapsed < shotTime) {
      for (var warningSideIndex = 0; warningSideIndex < GHOST_TRAIN_CANNON_SIDES.length; warningSideIndex++) {
        var warningSide = GHOST_TRAIN_CANNON_SIDES[warningSideIndex];
        if (findGhostTrainCannonTelegraphIndex(encounter, warningStep, warningSide) >= 0) continue;
        var warningDescriptor = getGhostTrainCannonStepDescriptor(encounter, warningStep, warningSide);
        var warningShot = warningDescriptor && getGhostTrainCannonShot(encounter, warningDescriptor.segment, warningDescriptor.side, warningDescriptor.mountOffset);
        if (warningDescriptor && warningShot) {
          aimGhostTrainCannon(
            warningDescriptor.segment,
            warningDescriptor.side,
            warningDescriptor.mountOffset,
            warningShot.aimDelta,
            Math.max(0.12, shotTime - elapsed + 0.34),
            false
          );
          encounter.cannonTelegraphs.push({
            step: warningStep,
            segmentIndex: warningDescriptor.segmentIndex,
            side: warningDescriptor.side,
            mountIndex: warningDescriptor.mountIndex,
            mountOffset: warningDescriptor.mountOffset,
            shotAt: shotTime,
            shot: warningShot,
            targetPlayerId: warningShot.targetPlayerId || "",
            targetX: warningShot.targetX,
            targetZ: warningShot.targetZ,
            trajectory: createGhostTrainCannonTrajectoryVisual(warningShot, warningDescriptor.segmentIndex, warningStep),
          });
        }
      }
    }
  }

  function updateGhostTrainCannonballs(dt, cosmeticOnly) {
    var playerEntries = cosmeticOnly ? null : getGhostTrainPlayerEntries();
    var trailParticleBudget = GHOST_TRAIN_CANNON_TRAIL_PARTICLE_BUDGET;
    var cannonBatch = state.ghostTrain && state.ghostTrain.cannonVisualBatch;
    var visibleGround = state.ghostTrainCannonballs.length
      ? getCurrentVisibleGroundRect(ghostTrainCannonVisibleGroundScratch)
      : null;
    for (var i = state.ghostTrainCannonballs.length - 1; i >= 0; i--) {
      var ball = state.ghostTrainCannonballs[i];
      ball.oldX = ball.x;
      ball.oldZ = ball.z;
      ball.life -= dt;
      ball.x += ball.dirX * ball.speed * dt;
      ball.z += ball.dirZ * ball.speed * dt;
      if (ball.mesh) {
        ball.spin = (ball.spin || 0) + dt * 7;
        updateGhostTrainCannonballVisual(
          ball.mesh,
          ball.x,
          ball.y,
          ball.z,
          ball.angle,
          ball.spin,
          0.88 + Math.sin(state.time * 18 + ball.id) * 0.14
        );
      }
      updateGhostTrainCannonTrajectoryForBall(ball);
      ball.trailTimer -= dt;
      if (ball.trailTimer <= 0) {
        ball.trailTimer = 0.06;
        var trailVisible = !visibleGround || !pointOutsideVisibleGround(ball.x, ball.z, 1.5, visibleGround);
        if (trailVisible && trailParticleBudget > 0) {
          spawnParticle(ball.x - ball.dirX * 0.45, ball.y, ball.z - ball.dirZ * 0.45, -ball.dirX * 0.5, 0.35, -ball.dirZ * 0.5, 0.18, 0.07, mats.ghostTrainSpectralGlow);
          trailParticleBudget -= 1;
          if (cannonBatch) cannonBatch.trailParticlesEmitted += 1;
        } else if (trailVisible && cannonBatch) {
          cannonBatch.trailParticlesSkipped += 1;
        }
      }
      if (!cosmeticOnly && !ball.cosmeticOnly) {
        for (var p = 0; p < playerEntries.length; p++) {
          var entry = playerEntries[p];
          var playerKey = entry.id || "solo";
          if (ball.hitPlayerIds[playerKey]) continue;
          var hitTime = getSegmentCircleEntryTime(ball.oldX, ball.oldZ, ball.x, ball.z, entry.entity.x, entry.entity.z, ball.radius + entry.entity.radius);
          if (hitTime == null) continue;
          ball.hitPlayerIds[playerKey] = true;
          ball.hitCount += 1;
          var hitX = ball.oldX + (ball.x - ball.oldX) * hitTime;
          var hitZ = ball.oldZ + (ball.z - ball.oldZ) * hitTime;
          damagePlayer(ball.damage, entry.entity);
          addShockwave(hitX, hitZ, 1.7, 0.25, 0x5dffd5);
        }
        var midX = (ball.oldX + ball.x) * 0.5;
        var midZ = (ball.oldZ + ball.z) * 0.5;
        var queryRadius = Math.hypot(ball.x - ball.oldX, ball.z - ball.oldZ) * 0.5 + ball.radius + 1.4;
        ghostTrainCannonCollisionBall = ball;
        forEachEnemyNearCircle(midX, midZ, queryRadius, hitEnemyWithGhostTrainCannonball, true, true);
        ghostTrainCannonCollisionBall = null;
      }
      var expired = ball.life <= 0 || Math.abs(ball.x) > ARENA_W / 2 + 12 || Math.abs(ball.z) > ARENA_D / 2 + 12;
      if (!expired) continue;
      state.ghostTrainCannonballs.splice(i, 1);
      releaseGhostTrainCannonballState(ball);
    }
  }

  function ghostTrainSegmentSweepsEntity(segment, entity, extraRadius) {
    if (!segment || !entity) return false;
    var radius = segment.radius + entity.radius + (extraRadius || 0);
    return getSegmentCircleEntryTime(segment.oldX, segment.oldZ, segment.x, segment.z, entity.x, entity.z, radius) != null;
  }

  function updateGhostTrainBodyCollisions(encounter) {
    if (
      !encounter || !encounter.materialized || !encounter.vulnerable || encounter.replica ||
      isGhostTrainTunnelAttackLocked(encounter)
    ) return;
    if (encounter.action !== "broadside" && encounter.action !== "crossfire" && encounter.action !== "ram") return;
    var entries = getBellRingerPlayerEntries();
    for (var p = 0; p < entries.length; p++) {
      var entry = entries[p];
      var key = entry.id || "solo";
      if (encounter.trainHitIds[key]) continue;
      for (var s = 0; s < encounter.segments.length; s++) {
        var segment = encounter.segments[s];
        if (!segment.attached || !ghostTrainSegmentSweepsEntity(segment, entry.entity, 0.12)) continue;
        encounter.trainHitIds[key] = true;
        damagePlayer(GHOST_TRAIN_RAM_DAMAGE, entry.entity);
        knockBellRingerPlayer(entry, segment.x, segment.z, 2.8);
        addShockwave(entry.entity.x, entry.entity.z, 2.4, 0.34, 0x32e8bc);
        break;
      }
    }
    var crushBudget = 8;
    for (var segmentIndex = 0; segmentIndex < encounter.segments.length && crushBudget > 0; segmentIndex++) {
      var trainSegment = encounter.segments[segmentIndex];
      if (!trainSegment.attached) continue;
      var midX = (trainSegment.oldX + trainSegment.x) * 0.5;
      var midZ = (trainSegment.oldZ + trainSegment.z) * 0.5;
      var queryRadius = Math.hypot(trainSegment.x - trainSegment.oldX, trainSegment.z - trainSegment.oldZ) * 0.5 + trainSegment.radius + 1.2;
      forEachEnemyNearCircle(midX, midZ, queryRadius, function (enemy) {
        if (crushBudget <= 0 || !enemy || enemy.active === false || enemy.isGhostTrainSegment || enemy.isBellRinger) return;
        if (enemy.ghostTrainCrushSequence === encounter.actionSequence) return;
        if (!ghostTrainSegmentSweepsEntity(trainSegment, enemy, 0.08)) return;
        enemy.ghostTrainCrushSequence = encounter.actionSequence;
        crushBudget -= 1;
        damageEnemy(enemy, Math.max(enemy.hp, enemy.maxHp), enemy.x, enemy.z, { type: "ghostTrainRam" });
      }, true, true);
    }
  }

  function createGhostTrainDetachWarning(segment) {
    var ring = new THREE.Mesh(getSharedGeometry("ghost-train-detach-warning", function () {
      return new THREE.RingGeometry(GHOST_TRAIN_DETACH_EXPLOSION_RADIUS - 0.22, GHOST_TRAIN_DETACH_EXPLOSION_RADIUS, 48);
    }), mats.ghostTrainWarning);
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(segment.x, 0.16, segment.z);
    ring.renderOrder = 4;
    ring.castShadow = false;
    ring.receiveShadow = false;
    ring.userData.disposeGeometry = false;
    ring.userData.disposeMaterial = false;
    dynamicRoot.add(ring);
    return ring;
  }

  function recomputeGhostTrainHealth(encounter) {
    var hp = 0;
    for (var i = 0; i < encounter.segments.length; i++) hp += Math.max(0, encounter.segments[i].hp || 0);
    encounter.boss.hp = hp;
    return hp;
  }

  function retireGhostTrainSegmentVisual(segment) {
    if (!segment || !segment.group) return;
    parkGhostTrainBundleGroup(segment.group);
    segment.visualDestroyed = true;
  }

  function getGhostTrainDamageTakenMultiplier(encounter, segment) {
    if (
      encounter && segment &&
      encounter.activeTailIndex === 0 &&
      segment.index === 0
    ) return 1 - GHOST_TRAIN_FINAL_DAMAGE_RESISTANCE;
    return 1;
  }

  function detachGhostTrainSegment(encounter, segment) {
    if (!encounter || !segment || !segment.attached || segment.index <= 0) return false;
    encounter.vulnerable = false;
    encounter.materialized = false;
    segment.hp = 0;
    segment.attached = false;
    segment.detaching = true;
    segment.active = false;
    segment.vulnerableTarget = false;
    setGhostTrainSegmentForm(segment, true, false, 0);
    encounter.detachSequence += 1;
    var detached = {
      sequence: encounter.detachSequence,
      segment: segment,
      segmentIndex: segment.index,
      pathDistance: segment.pathDistance,
      speed: getGhostTrainSpeed(encounter) * 0.52,
      timer: GHOST_TRAIN_DETACH_TIME,
      duration: GHOST_TRAIN_DETACH_TIME,
      warningRing: createGhostTrainDetachWarning(segment),
      exploded: false,
    };
    encounter.detachedWagons.push(detached);
    encounter.activeTailIndex = Math.max(0, segment.index - 1);
    attachGhostTrainRearMachineGun(encounter);
    encounter.phase = GHOST_TRAIN_WAGON_COUNT - encounter.activeTailIndex;
    encounter.boss.speed = getGhostTrainSpeed(encounter);
    recomputeGhostTrainHealth(encounter);
    beginGhostTrainAction(encounter, "detach", 1.05);
    encounter.routeSequence += 1;
    addShockwave(segment.x, segment.z, 4.9, 0.58, 0x62ffdc);
    addLightFlash(segment.x, 2.4, segment.z, 0x49e8bd, 4.6, 11, 0.34);
    playGhostTrainWhistle(segment.x, segment.z, false);
    return true;
  }

  function explodeGhostTrainDetachedWagon(encounter, detached, cosmeticOnly) {
    if (!detached || detached.exploded) return;
    detached.exploded = true;
    encounter.explosionSequence += 1;
    var segment = detached.segment;
    var x = segment.x;
    var z = segment.z;
    addShockwave(x, z, GHOST_TRAIN_DETACH_EXPLOSION_RADIUS + 2.4, 0.78, 0x50ffd3);
    addShockwave(x, z, 3.9, 0.48, 0xd7fff2);
    addLightFlash(x, 3.6, z, 0x39ffc9, 7.2, 18, 0.56);
    reserveParticleSlots(54);
    for (var i = 0; i < 54; i++) {
      var angle = rand(0, Math.PI * 2);
      var speed = rand(2, 8.5);
      spawnParticle(x, rand(0.25, 3.6), z, Math.cos(angle) * speed, rand(1.4, 7.8), Math.sin(angle) * speed, rand(0.42, 0.92), rand(0.08, 0.24), i % 4 ? mats.ghostTrainSpectralGlow : mats.ghostTrainRust, true);
    }
    playGhostTrainExplosionSound(x, z);
    if (!cosmeticOnly) {
      var entries = getBellRingerPlayerEntries();
      for (var p = 0; p < entries.length; p++) {
        var entity = entries[p].entity;
        var distance = Math.hypot(entity.x - x, entity.z - z);
        if (distance <= GHOST_TRAIN_DETACH_EXPLOSION_RADIUS + entity.radius) {
          damagePlayer(Math.max(18, Math.round(GHOST_TRAIN_DETACH_EXPLOSION_DAMAGE * (1 - distance / (GHOST_TRAIN_DETACH_EXPLOSION_RADIUS * 1.25)))), entity);
          knockBellRingerPlayer(entries[p], x, z, 3.6);
        }
      }
      var killBudget = 18;
      forEachEnemyNearCircle(x, z, GHOST_TRAIN_DETACH_EXPLOSION_RADIUS + 1.5, function (enemy) {
        if (killBudget <= 0 || !enemy || enemy.active === false || enemy.isGhostTrainSegment || enemy.isBellRinger) return;
        if (Math.hypot(enemy.x - x, enemy.z - z) > GHOST_TRAIN_DETACH_EXPLOSION_RADIUS + enemy.radius * 0.25) return;
        killBudget -= 1;
        damageEnemy(enemy, Math.max(enemy.hp, enemy.maxHp), enemy.x, enemy.z, { type: "ghostTrainWagonExplosion" });
      }, true, true);
    }
    if (detached.warningRing) removeObject3D(detached.warningRing);
    detached.warningRing = null;
    retireGhostTrainSegmentVisual(segment);
  }

  function updateGhostTrainDetachedWagons(encounter, dt, cosmeticOnly) {
    var points = getGhostTrainRoutePoints(encounter);
    if (!points || points.length < 2) return;
    var scratch = encounter.detachedSampleScratch || (encounter.detachedSampleScratch = {});
    for (var i = encounter.detachedWagons.length - 1; i >= 0; i--) {
      var detached = encounter.detachedWagons[i];
      var segment = detached.segment;
      if (detached.exploded || !segment || !segment.group) {
        encounter.detachedWagons.splice(i, 1);
        continue;
      }
      segment.oldX = segment.x;
      segment.oldZ = segment.z;
      if (encounter.replica && detached.networkHasTarget) {
        updateGhostTrainReplicaDetachedWagonTransform(encounter, detached, dt);
      } else {
        detached.pathDistance = Math.min(points[points.length - 1].d, detached.pathDistance + detached.speed * dt);
        detached.speed = Math.max(0, detached.speed - dt * 2.4);
        sampleGhostTrainTrack(points, detached.pathDistance, scratch);
        segment.pathDistance = scratch.d;
        segment.x = scratch.x;
        segment.z = scratch.z;
        segment.facingAngle = scratch.angle;
      }
      segment.group.position.x = segment.x;
      segment.group.position.z = segment.z;
      segment.group.rotation.y = segment.facingAngle;
      updateGhostTrainSegmentAnimation(segment, dt, Math.hypot(segment.x - segment.oldX, segment.z - segment.oldZ));
      detached.timer = Math.max(0, detached.timer - dt);
      if (detached.warningRing) {
        detached.warningRing.position.x = segment.x;
        detached.warningRing.position.z = segment.z;
        var warningProgress = 1 - detached.timer / detached.duration;
        var pulse = 0.86 + warningProgress * 0.18 + Math.sin(state.time * (7 + warningProgress * 12)) * 0.07;
        detached.warningRing.scale.setScalar(pulse);
        detached.warningRing.rotation.z += dt * (0.4 + warningProgress * 1.8);
      }
      if (detached.timer <= 0) {
        explodeGhostTrainDetachedWagon(encounter, detached, cosmeticOnly);
        encounter.detachedWagons.splice(i, 1);
      }
    }
  }

  function damageGhostTrainSegment(segment, damage, x, z, source) {
    var encounter = state.ghostTrain;
    if (!encounter || !encounter.active || encounter.defeated || !segment || !segment.attached) return 0;
    if (!encounter.materialized || !encounter.vulnerable || segment.index !== encounter.activeTailIndex) {
      addHitSpark(Number.isFinite(x) ? x : segment.x, Number.isFinite(z) ? z : segment.z);
      addShockwave(Number.isFinite(x) ? x : segment.x, Number.isFinite(z) ? z : segment.z, 1.35, 0.2, 0x4fe0ba);
      return 0;
    }
    damage = Math.max(0, Number(damage) || 0);
    damage *= getGhostTrainDamageTakenMultiplier(encounter, segment);
    if (damage <= 0) return 0;
    var previous = segment.hp;
    segment.hp = Math.max(0, segment.hp - damage);
    var applied = previous - segment.hp;
    segment.hitPulse = 1;
    segment.recentCombatAt = state.time;
    recomputeGhostTrainHealth(encounter);
    if (applied > 0) {
      playZombieHitSound(Number.isFinite(x) ? x : segment.x, Number.isFinite(z) ? z : segment.z, Math.min(5, applied), source);
      addHitSpark(Number.isFinite(x) ? x : segment.x, Number.isFinite(z) ? z : segment.z);
      reserveParticleSlots(9);
      for (var i = 0; i < 9; i++) {
        spawnParticle(Number.isFinite(x) ? x : segment.x, rand(0.8, 3.1), Number.isFinite(z) ? z : segment.z, rand(-3.4, 3.4), rand(1, 4.8), rand(-3.4, 3.4), rand(0.24, 0.5), rand(0.06, 0.16), i % 3 ? mats.ghostTrainSpectralGlow : mats.ghostTrainBrass, true);
      }
    }
    if (segment.hp <= 0) {
      // Close the vulnerability gate before exposing the next car. This prevents
      // a piercing projectile or an AoE callback from spilling into another bar.
      encounter.vulnerable = false;
      encounter.materialized = false;
      segment.vulnerableTarget = false;
      if (segment.index === 0) defeatGhostTrain(source);
      else detachGhostTrainSegment(encounter, segment);
    }
    updateGhostTrainHud();
    return applied;
  }

  function getGhostTrainDeathTimeLeft(encounter) {
    if (!encounter || !encounter.defeated) return 0;
    if (encounter.replica) return clamp(Number(encounter.deathTimer) || 0, 0, GHOST_TRAIN_POST_DEATH_DELAY);
    return clamp(GHOST_TRAIN_POST_DEATH_DELAY - Math.max(0, state.time - encounter.defeatedAt), 0, GHOST_TRAIN_POST_DEATH_DELAY);
  }

  function defeatGhostTrain(source) {
    var encounter = state.ghostTrain;
    if (!encounter || encounter.defeated) return false;
    clearGhostTrainCannonTelegraphs(encounter);
    encounter.active = false;
    encounter.defeated = true;
    stopBossWaveSpawningAfterDefeat();
    encounter.materialized = false;
    encounter.vulnerable = false;
    encounter.rearGunActive = false;
    encounter.rearGunTargetPlayerId = "";
    encounter.defeatedAt = state.time;
    encounter.deathTimer = GHOST_TRAIN_POST_DEATH_DELAY;
    encounter.deathSequence = Math.max(0, encounter.deathSequence || 0) + 1;
    encounter.deathVisualProgress = 0;
    encounter.action = "defeated";
    encounter.actionTimer = 0;
    encounter.actionDuration = 0;
    var boss = encounter.boss;
    boss.hp = 0;
    boss.active = false;
    boss.action = "defeated";
    boss.actionTimer = 0;
    boss.actionDuration = 0;
    boss.deathTimer = GHOST_TRAIN_POST_DEATH_DELAY;
    state.score += 5000;
    addShockwave(boss.x, boss.z, 11.5, 1.1, 0x56ffd8);
    addLightFlash(boss.x, 4.8, boss.z, 0x74ffe0, 9, 22, 0.72);
    playGhostTrainWhistle(boss.x, boss.z, true);
    updateGhostTrainDeathVisual(encounter, 0);
    updateGhostTrainHud();
    return true;
  }

  function updateGhostTrainDeathVisual(encounter, dt) {
    if (!encounter || !encounter.defeated) return;
    if (encounter.replica) encounter.deathTimer = Math.max(0, encounter.deathTimer - dt);
    else encounter.deathTimer = getGhostTrainDeathTimeLeft(encounter);
    var elapsed = GHOST_TRAIN_POST_DEATH_DELAY - encounter.deathTimer;
    var progress = clamp(elapsed / GHOST_TRAIN_DEATH_ANIMATION_DURATION, 0, 1);
    encounter.deathVisualProgress = Math.max(encounter.deathVisualProgress || 0, progress);
    var engine = encounter.segments[0];
    if (engine && engine.group) {
      engine.group.rotation.z = Math.sin(elapsed * 13) * (1 - progress) * 0.035 + progress * 0.48;
      engine.group.position.y = -Math.max(0, progress - 0.55) * 3.4;
      setGhostTrainSegmentForm(engine, true, false, progress);
    }
    if (!encounter.deathBurstOne && progress >= 0.28) {
      encounter.deathBurstOne = true;
      addShockwave(encounter.boss.x, encounter.boss.z, 8.2, 0.7, 0x26d9ad);
      addLightFlash(encounter.boss.x, 2.4, encounter.boss.z, 0x39ffc8, 5, 14, 0.4);
      reserveParticleSlots(42);
      for (var p = 0; p < 42; p++) {
        var angle = rand(0, Math.PI * 2);
        var speed = rand(1.8, 7.4);
        spawnParticle(encounter.boss.x, rand(0.2, 3.8), encounter.boss.z, Math.cos(angle) * speed, rand(1.2, 7), Math.sin(angle) * speed, rand(0.42, 0.9), rand(0.08, 0.22), p % 3 ? mats.ghostTrainSpectralGlow : mats.ghostTrainRust, true);
      }
      playGhostTrainExplosionSound(encounter.boss.x, encounter.boss.z);
    }
    if (!encounter.deathBurstTwo && progress >= 0.68) {
      encounter.deathBurstTwo = true;
      addShockwave(encounter.boss.x, encounter.boss.z, 13.5, 1.0, 0xb9fff0);
      addLightFlash(encounter.boss.x, 3.4, encounter.boss.z, 0xb9fff0, 7.5, 19, 0.56);
      playGhostTrainExplosionSound(encounter.boss.x, encounter.boss.z);
    }
    updateGhostTrainSteamWaveAttack(encounter, dt, true);
    updateGhostTrainRearGunVisual(encounter, dt);
    updateGhostTrainRearGunTracers(encounter, dt);
    updateGhostTrainTrackVisual(encounter);
  }

  function updateGhostTrainSmoke(encounter, dt) {
    if (!encounter || !encounter.segments[0] || !encounter.segments[0].group) return;
    encounter.smokeTimer -= dt;
    if (encounter.smokeTimer > 0) return;
    encounter.smokeTimer = encounter.phase >= 4 ? 0.075 : encounter.materialized ? 0.13 : 0.2;
    var engine = encounter.segments[0];
    var forwardX = Math.sin(engine.facingAngle);
    var forwardZ = Math.cos(engine.facingAngle);
    var stackX = engine.x + forwardX * GHOST_TRAIN_STACK_FORWARD_OFFSET;
    var stackZ = engine.z + forwardZ * GHOST_TRAIN_STACK_FORWARD_OFFSET;
    spawnParticle(stackX, GHOST_TRAIN_STACK_SMOKE_HEIGHT, stackZ, rand(-0.35, 0.35) - forwardX * 0.8, rand(1.2, 2.6), rand(-0.35, 0.35) - forwardZ * 0.8, rand(0.55, 0.95), rand(0.16, 0.3), encounter.materialized ? mats.ghostTrainRust : mats.ghostTrainSpectralGlow);
  }

  function updateGhostTrainEncounter(dt) {
    var encounter = state.ghostTrain;
    if (!encounter || encounter.replica) return;
    if (encounter.defeated) {
      updateGhostTrainDeathVisual(encounter, dt);
      updateGhostTrainCannonballs(dt, false);
      return;
    }
    if (!encounter.active || !encounter.boss) return;
    encounter.tunnelAttackLockTimer = Math.max(
      0,
      (Number(encounter.tunnelAttackLockTimer) || 0) - Math.max(0, dt || 0)
    );
    var speed = getGhostTrainSpeed(encounter);
    var materializeCooldownRemaining = getGhostTrainMaterializeCooldownRemaining(encounter);
    encounter.boss.speed = speed;
    encounter.plannerRefreshTimer = Math.max(0, (encounter.plannerRefreshTimer || 0) - dt);
    if (encounter.action === "spectral") {
      encounter.spectralTargetAge = Math.max(0, encounter.spectralTargetAge || 0) + dt;
      if (
        encounter.aiEnabled &&
        !encounter.tunnelActive &&
        !encounter.attackApproachActive &&
        materializeCooldownRemaining <= (encounter.phase >= 4 ? 0.0001 : GHOST_TRAIN_ATTACK_APPROACH_LEAD_TIME)
      ) {
        var existingRailOpportunity = findGhostTrainExistingRailAttackOpportunity(encounter);
        if (existingRailOpportunity) beginGhostTrainExistingRailAttackApproach(encounter, existingRailOpportunity);
        else if (encounter.actionTimer <= GHOST_TRAIN_ATTACK_APPROACH_LEAD_TIME) beginGhostTrainAttackApproach(encounter);
      }
      if (encounter.attackApproachActive && !encounter.tunnelActive) {
        encounter.attackApproachAge = Math.max(0, encounter.attackApproachAge || 0) + dt;
        if (encounter.aiEnabled && encounter.attackApproachAge >= GHOST_TRAIN_ATTACK_APPROACH_REPLAN_TIME) {
          var currentApproach = getGhostTrainAttackApproachMetrics(encounter);
          if (!currentApproach.ready) {
            var approachEntries = getGhostTrainPlayerEntries();
            var approachTarget = findGhostTrainPlayerEntry(approachEntries, encounter.targetPlayerId);
            if (!approachTarget && approachEntries.length) approachTarget = chooseGhostTrainTarget(encounter);
            if (approachTarget) {
              encounter.orbitDirection = -(encounter.orbitDirection || 1);
              if (configureGhostTrainAttackApproach(encounter, approachTarget)) updateGhostTrainAttackApproachTarget(encounter);
            }
          }
        }
      }
      if (!encounter.tunnelActive && encounter.plannerRefreshTimer <= 0) {
        encounter.plannerRefreshTimer = GHOST_TRAIN_SPECTRAL_TARGET_REFRESH;
        updateGhostTrainSpectralPatrol(encounter);
      }
    }
    if (isGhostTrainFinalMaterialApproach(encounter)) {
      speed = getGhostTrainSpeed(encounter);
      encounter.boss.speed = speed;
    }
    var preview = getGhostTrainPreviewDistance(encounter);
    ensureGhostTrainTrackAhead(encounter, encounter.engineDistance + preview + speed * dt + 8);
    var lastTrackDistance = encounter.trackPoints.length ? encounter.trackPoints[encounter.trackPoints.length - 1].d : encounter.engineDistance;
    var motionMultiplier = encounter.tunnelActive
      ? encounter.tunnelTeleported ? GHOST_TRAIN_TUNNEL_EXIT_MOTION : GHOST_TRAIN_TUNNEL_ENTRY_MOTION
      : encounter.action === "materialize" ? 0.88 : encounter.action === "detach" ? 1.06 : 1;
    if (!encounter.tunnelActive && encounter.action === "materialize") {
      motionMultiplier = Math.min(
        motionMultiplier,
        GHOST_TRAIN_MATERIALIZE_MAX_TRAVEL / Math.max(0.001, speed * Math.max(0.001, encounter.actionDuration))
      );
    }
    if (!encounter.freezeMotion) {
      var tunnelEntering = encounter.tunnelActive && !encounter.tunnelTeleported;
      var nextEngineDistance;
      if (tunnelEntering) {
        var entryElapsedAfterStep = Math.max(
          0,
          GHOST_TRAIN_TUNNEL_DURATION - Math.max(0, encounter.actionTimer || 0) + dt
        );
        var entryProgressAfterStep = clamp(
          (entryElapsedAfterStep - GHOST_TRAIN_TUNNEL_ENTRY_OPEN_DELAY) /
            Math.max(0.001, GHOST_TRAIN_TUNNEL_ENTRY_DURATION - GHOST_TRAIN_TUNNEL_ENTRY_OPEN_DELAY),
          0,
          1
        );
        var entryStartDistance = Number(encounter.tunnelEntryStartDistance);
        var entryEndDistance = Number(encounter.tunnelEntryEndDistance);
        if (!Number.isFinite(entryStartDistance)) entryStartDistance = encounter.engineDistance;
        if (!Number.isFinite(entryEndDistance)) entryEndDistance = entryStartDistance + getGhostTrainTunnelEntryTravel(encounter);
        if (
          entryProgressAfterStep >= 1 &&
          encounter.engineDistance >= entryEndDistance - 0.001
        ) {
          nextEngineDistance = Math.min(
            lastTrackDistance,
            encounter.engineDistance + (entryEndDistance - entryStartDistance) /
              Math.max(0.001, GHOST_TRAIN_TUNNEL_ENTRY_DURATION - GHOST_TRAIN_TUNNEL_ENTRY_OPEN_DELAY) * dt
          );
        } else {
          nextEngineDistance = Math.min(
            lastTrackDistance,
            entryStartDistance + (entryEndDistance - entryStartDistance) * entryProgressAfterStep
          );
        }
      } else {
        nextEngineDistance = Math.min(lastTrackDistance, encounter.engineDistance + speed * motionMultiplier * dt);
      }
      if (encounter.tunnelActive && encounter.tunnelTeleported && encounter.tunnelExitEndDistance > 0) {
        nextEngineDistance = Math.min(nextEngineDistance, encounter.tunnelExitEndDistance);
      }
      encounter.engineDistance = nextEngineDistance;
    }
    updateGhostTrainAttachedTransforms(encounter, dt);
    updateGhostTrainTunnelSegmentVisibility(encounter);
    if (
      encounter.tunnelActive && !encounter.tunnelTeleported &&
      GHOST_TRAIN_TUNNEL_DURATION - Math.max(0, encounter.actionTimer || 0) + dt >= GHOST_TRAIN_TUNNEL_ENTRY_DURATION &&
      performGhostTrainTunnelTeleport(encounter)
    ) {
      // The old route is rebased only while every attached segment is behind
      // the opaque entry plane. Commit the exit transforms before the same
      // displayed frame, so no world-space jump or heading reversal is visible.
      updateGhostTrainAttachedTransforms(encounter, 0);
      updateGhostTrainTunnelSegmentVisibility(encounter);
    }
    updateGhostTrainTunnelVisual(encounter, dt);
    markGhostTrainPassedTrack(encounter);
    updateGhostTrainDetachedWagons(encounter, dt, false);

    var materialVisual = encounter.materialized;
    if (encounter.action === "materialize") {
      materialVisual = 1 - encounter.actionTimer / Math.max(0.001, encounter.actionDuration) >= GHOST_TRAIN_MATERIALIZE_SOLID_PROGRESS;
      encounter.materialized = materialVisual;
      encounter.vulnerable = materialVisual;
    } else if (encounter.action === "dematerialize") {
      materialVisual = encounter.actionTimer / Math.max(0.001, encounter.actionDuration) >= 0.42;
      encounter.materialized = materialVisual;
      encounter.vulnerable = materialVisual;
    }
    if (encounter.phase >= 4) {
      materialVisual = true;
      encounter.materialized = true;
      encounter.vulnerable = true;
    }
    for (var i = 0; i < encounter.segments.length; i++) {
      var segment = encounter.segments[i];
      if (!segment.attached) continue;
      setGhostTrainSegmentForm(segment, materialVisual, encounter.vulnerable && i === encounter.activeTailIndex, segment.hitPulse || 0);
    }
    updateGhostTrainSteamWaveAttack(encounter, dt, false);
    updateGhostTrainRearMachineGun(encounter, dt, false);
    updateGhostTrainTrackVisual(encounter);
    updateGhostTrainSmoke(encounter, dt);
    updateGhostTrainCannonSchedule(encounter, false);
    updateGhostTrainCannonballs(dt, false);
    updateGhostTrainBodyCollisions(encounter);

    if (!encounter.aiEnabled) {
      updateGhostTrainHud();
      return;
    }
    var nextGhostTrainActionTimer = Math.max(0, encounter.actionTimer - dt);
    if (encounter.tunnelActive && !encounter.tunnelTeleported) {
      var tunnelEntryHoldTimer = Math.max(0, GHOST_TRAIN_TUNNEL_DURATION - GHOST_TRAIN_TUNNEL_ENTRY_DURATION);
      if (!isGhostTrainTunnelEntryFullyOccluded(encounter)) {
        nextGhostTrainActionTimer = Math.max(nextGhostTrainActionTimer, tunnelEntryHoldTimer);
      }
    }
    encounter.actionTimer = nextGhostTrainActionTimer;
    encounter.boss.actionTimer = encounter.actionTimer;
    if (encounter.tunnelActive && encounter.action === "spectral" && encounter.actionTimer <= 0) {
      finishGhostTrainTunnelTransit(encounter);
      if (encounter.phase >= 4 && encounter.attackApproachActive && !activateGhostTrainFinalMaterialApproach(encounter)) {
        encounter.attackApproachActive = false;
        encounter.attackApproachAge = 0;
        encounter.finalMaterialApproachPending = true;
      }
    }
    if (
      encounter.action === "spectral" &&
      !encounter.tunnelActive &&
      encounter.attackApproachActive
    ) {
      var missedApproachMetrics = getGhostTrainAttackApproachMetrics(encounter);
      if (shouldGhostTrainTunnelAfterMissedApproach(encounter, missedApproachMetrics)) {
        var missedReason = missedApproachMetrics.forwardDistance <= GHOST_TRAIN_TUNNEL_MISSED_APPROACH_FORWARD
          ? "passed-target"
          : "timed-out";
        encounter.missedApproachCount = Math.max(0, encounter.missedApproachCount || 0) + 1;
        encounter.lastMissedApproach = {
          targetPlayerId: missedApproachMetrics.targetPlayerId || "",
          distance: missedApproachMetrics.distance,
          forwardDistance: missedApproachMetrics.forwardDistance,
          lateralDistance: missedApproachMetrics.lateralDistance,
          age: Math.max(0, encounter.attackApproachAge || 0),
          reason: missedReason,
          time: state.time,
        };
        if (beginGhostTrainTunnelTransit(encounter)) {
          updateGhostTrainHud();
          return;
        }
      }
    }
    var earlyApproachMetrics = null;
    if (
      encounter.action === "spectral" &&
      !encounter.tunnelActive &&
      encounter.actionTimer > 0 &&
      (
        encounter.actionTimer <= GHOST_TRAIN_EARLY_MATERIALIZE_WINDOW ||
        encounter.attackApproachUsesExistingRail
      )
    ) {
      earlyApproachMetrics = getGhostTrainAttackApproachMetrics(encounter);
      if (
        earlyApproachMetrics.ready &&
        (isGhostTrainFinalMaterialApproach(encounter) || materializeCooldownRemaining <= 0.0001)
      ) {
        encounter.actionTimer = 0;
        encounter.boss.actionTimer = 0;
      }
    }
    if (encounter.actionTimer > 0) {
      updateGhostTrainHud();
      return;
    }
    if (encounter.action === "spectral") {
      var finalMaterialApproach = isGhostTrainFinalMaterialApproach(encounter);
      if (materializeCooldownRemaining > 0.0001 && !finalMaterialApproach) {
        updateGhostTrainHud();
        return;
      }
      var approachMetrics = earlyApproachMetrics || getGhostTrainAttackApproachMetrics(encounter);
      if (!approachMetrics.ready) {
        updateGhostTrainHud();
        return;
      }
      encounter.lastMaterializeEntry = {
        targetPlayerId: approachMetrics.targetPlayerId,
        segmentIndex: approachMetrics.segmentIndex,
        distance: approachMetrics.distance,
        forwardDistance: approachMetrics.forwardDistance,
        lateralDistance: approachMetrics.lateralDistance,
        engagementDistance: approachMetrics.effectiveEngagementDistance,
        existingRail: !!encounter.attackApproachUsesExistingRail,
        visible: approachMetrics.visible,
        withinReturnFireRange: approachMetrics.withinReturnFireRange,
        time: state.time,
      };
      if (finalMaterialApproach) {
        var finalAttack = encounter.attackKind || chooseGhostTrainAttack(encounter);
        beginGhostTrainAction(encounter, finalAttack, getGhostTrainAttackDuration(encounter));
      } else {
        beginGhostTrainAction(encounter, "materialize", GHOST_TRAIN_MATERIALIZE_TIME);
      }
    } else if (encounter.action === "materialize") {
      var attack = encounter.attackKind || chooseGhostTrainAttack(encounter);
      beginGhostTrainAction(encounter, attack, getGhostTrainAttackDuration(encounter));
    } else if (encounter.action === "broadside" || encounter.action === "crossfire" || encounter.action === "ram") {
      beginGhostTrainAction(encounter, "dematerialize", GHOST_TRAIN_DEMATERIALIZE_TIME);
    } else if (encounter.action === "dematerialize" || encounter.action === "detach") {
      if (!beginGhostTrainTunnelTransit(encounter)) {
        beginGhostTrainAction(encounter, "spectral", GHOST_TRAIN_SPECTRAL_TIMES[encounter.phase] || 3);
      }
    }
    updateGhostTrainHud();
  }

  function ensureBellRingerMaterials() {
    if (mats.bellRingerCoat) return;
    mats.bellRingerCoat = material(0x17171a, 0.88, 0.03);
    mats.bellRingerCoatAlt = material(0x292329, 0.84, 0.04);
    mats.bellRingerTrim = material(0x6c202a, 0.78, 0.04);
    mats.bellRingerSkin = material(0x71934a, 0.91, 0.01);
    mats.bellRingerSkinDark = material(0x496b35, 0.92, 0.01);
    mats.bellRingerBell = material(0x8a5b2b, 0.46, 0.38, 0x4d270d, 0.05);
    mats.bellRingerBellEdge = material(0xb6813d, 0.38, 0.42, 0x6b390f, 0.08);
    mats.bellRingerWood = material(0x3c2418, 0.9, 0.02);
    mats.bellRingerWoodLight = material(0x674128, 0.84, 0.03);
    mats.bellRingerIron = material(0x242326, 0.43, 0.62);
    mats.bellRingerEye = material(0xf5d46c, 0.42, 0.12, 0xffb52e, 0.82);
    mats.bellRingerBone = material(0xd9c9a2, 0.9, 0.01);
    mats.bellChurchWall = material(0xd1bc91, 0.94, 0.01);
    mats.bellChurchWallDark = material(0x9a835f, 0.94, 0.01);
    mats.bellChurchRoof = material(0x47242d, 0.84, 0.04);
    mats.bellChurchDoor = material(0x4a2a1b, 0.86, 0.03);
    mats.bellChurchGlass = material(0x7e9da3, 0.42, 0.16, 0x7bc2d4, 0.1);
    mats.bellSpectral = new THREE.MeshBasicMaterial({
      color: 0xe7c8ff,
      transparent: true,
      opacity: 0.9,
      depthWrite: false,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending,
    });
    mats.bellSpectralGlow = new THREE.MeshBasicMaterial({
      color: 0xb985ff,
      transparent: true,
      opacity: 0.25,
      depthWrite: false,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending,
    });
    mats.bellWarningGround = new THREE.MeshBasicMaterial({
      color: 0x8e2133,
      transparent: true,
      opacity: 0.42,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
  }

  function makeBellRingerVisualMesh(parent, geometryKey, geometryFactory, mat, x, y, z, castShadow) {
    var mesh = addEnemyAccessoryMesh(parent, geometryKey, geometryFactory, mat, x, y, z, castShadow);
    mesh.userData.noDebris = true;
    return mesh;
  }

