    for (var i = 0; i < 44; i++) {
      var angle = boss.facingAngle + (i / 44) * Math.PI * 2;
      spawnParticle(boss.x + Math.sin(angle) * rand(2.2, 6.2), rand(0.12, 0.8), boss.z + Math.cos(angle) * rand(2.2, 6.2), Math.sin(angle) * rand(1, 4), rand(0.6, 2.4), Math.cos(angle) * rand(1, 4), rand(0.24, 0.46), rand(0.08, 0.18), i % 4 ? mats.sandDark : mats.bellRingerBellEdge, true);
    }
