        tautness = 0.99;
        targetX = 0.75 + (0.22 - 0.75) * directWeaponStrike;
        targetY = 1.05 + (-2.25 - 1.05) * directWeaponStrike;
        targetZ = -4.2 + (4.72 + 4.2) * directWeaponStrike;
