        tautness = 0.99 + (0.24 - 0.99) * directWeaponReturn;
        targetX = 0.22 + (idleX - 0.22) * directWeaponReturn;
        targetY = -2.25 + (idleY + 2.25) * directWeaponReturn;
        targetZ = 4.72 + (idleZ - 4.72) * directWeaponReturn;
