    var castHead = new THREE.Group();
    castHead.name = "oil-baron-debt-cast-head";
    var castHeadCore = new THREE.Mesh(
      getSharedGeometry("oil-baron-debt-cast-head-core", function () { return new THREE.OctahedronGeometry(0.24, 0); }),
      mats.oilBaronGold
    );
    castHeadCore.scale.z = 1.45;
    castHeadCore.userData.disposeGeometry = false;
    castHeadCore.userData.disposeMaterial = false;
    castHead.add(castHeadCore);
    var castHeadRing = new THREE.Mesh(
      getSharedGeometry("oil-baron-debt-cast-head-ring", function () { return new THREE.TorusGeometry(0.29, 0.055, 6, 14); }),
      mats.oilBaronBlack
    );
    castHeadRing.userData.disposeGeometry = false;
    castHeadRing.userData.disposeMaterial = false;
    castHead.add(castHeadRing);
    group.add(castHead);
    addHealthBar(group, 0.62, 1.15);
    group.userData.links = links;
    group.userData.cuff = cuff;
    group.userData.cuffDark = cuffDark;
    group.userData.cuffGold = cuffGold;
    group.userData.lockBody = lockBody;
    group.userData.lockFace = lockFace;
    group.userData.sourceCoupler = sourceCoupler;
    group.userData.castHead = castHead;
    group.userData.castHeadCore = castHeadCore;
    group.userData.castHeadRing = castHeadRing;
    effectRoot.add(group);
