    boss.actionTimer = 0;
    boss.actionDuration = 0;
    boss.recoverFrom = "";
    boss.starVisualY = 0;
    boss.starImpactSquash = 0;
    boss.starOilBlend = Math.max(0, Number(boss.permanentOilBlend) || 0);
    boss.starJumpProgress = 0;
    boss.attackCooldown = Math.max(boss.attackCooldown || 0, 1.8);
    encounter.starCooldown = encounter.starLoopPreview ? 0.8 : getOilBaronStarRepeatInterval(encounter);
