      var point = boss.starLandingPoints[timeline.jumpIndex] || { x: boss.x, z: boss.z };
      var previousPoint = timeline.jumpIndex > 0
        ? boss.starLandingPoints[timeline.jumpIndex - 1]
        : { x: boss.starStartX, z: boss.starStartZ };
      var travel = bellRingerSmoother(timeline.airProgress);
      boss.x = previousPoint.x + (point.x - previousPoint.x) * travel;
      boss.z = previousPoint.z + (point.z - previousPoint.z) * travel;
      boss.starTargetX = point.x;
      boss.starTargetZ = point.z;
      boss.facingAngle = Math.atan2(point.x - previousPoint.x, point.z - previousPoint.z);
      if (timeline.jumpProgress >= OIL_BARON_STAR_IMPACT_PROGRESS) resolveOilBaronStarImpact(encounter, timeline.jumpIndex);
      for (var passedJump = 0; passedJump < timeline.jumpIndex; passedJump++) resolveOilBaronStarImpact(encounter, passedJump);
