    var detailMaterial = material(0x151515, 0.24, 0.56, 0x0d0d0d, 0.28);
    detailMaterial.name = "oil-double-black-detail";
    var muzzleFlashMaterial = material(0x181818, 0.22, 0.38, 0x686868, 0.95);
    muzzleFlashMaterial.name = "oil-double-achromatic-muzzle-flash";
