    var desiredX = Number.isFinite(Number(options.x)) ? Number(options.x) : boss.x + Math.sin(angle) * 5.4;
    var desiredZ = Number.isFinite(Number(options.z)) ? Number(options.z) : boss.z + Math.cos(angle) * 5.4;
