      radius: 1.72,
      hp: Math.min(maxHp, Math.max(0, Number.isFinite(Number(options.hp)) ? Number(options.hp) : maxHp)),
      maxHp: maxHp,
      damage: OIL_BARON_DOUBLE_CANE_DAMAGE,
      speed: OIL_BARON_BASE_SPEED * 1.04,
      score: 0,
      xp: 0,
      group: group,
      facingAngle: Number.isFinite(Number(options.a)) ? Number(options.a) : angle,
