      recoverFrom: "",
      offerPoseBlend: 0,
      attackCooldown: 1.8 + slot * 1.45,
      debtCooldown: 4.4 + slot * 1.8,
      targetPlayerId: String(options.targetPlayerId || ""),
      caneDirX: Number(options.caneX) || 0,
      caneDirZ: Number.isFinite(Number(options.caneZ)) ? Number(options.caneZ) : 1,
      caneResolved: false,
      debtResolved: false,
      monocleResolved: false,
      summonResolved: false,
      starStartX: spawnPoint.x,
      starStartZ: spawnPoint.z,
