      if (!isOilBaronDerrickInWireScope(derrick, defeated, viewerRect, respawnViewerRect)) continue;
      var recentCombatAt = Number(derrick.recentCombatAt);
      if (!Number.isFinite(recentCombatAt)) recentCombatAt = -999;
