    actor.networkPreviousTargetZ = hardSnap ? targetZ : previousTargetZ;
    actor.networkPreviousSampleTime = hardSnap ? sampleTime : previousSampleTime;
    actor.targetX = targetX;
    actor.targetZ = targetZ;
    actor.networkTargetSampleTime = sampleTime;
    actor.networkTargetLocalTime = state.time;
    actor.networkVelocityX = velocityX;
    actor.networkVelocityZ = velocityZ;
    actor.networkTargetAngle = Number(angle) || 0;
    actor.networkHasTarget = true;
