        rearMachineGun: { present: false, attachedSegmentIndex: -1, active: false, targetPlayerId: "", fireSequence: 0, zoneVisible: false, tracerInUse: 0, drawCalls: 0 },
        steamWaveAttack: { finalPhaseOnly: true, materialOnly: true, active: false, activeCount: 0, damage: GHOST_TRAIN_STEAM_WAVE_DAMAGE, sequence: 0, batched: true, drawCalls: 0 },
        approach: { active: false, ready: false, visible: false, withinReturnFireRange: false, targetPlayerId: "", segmentIndex: -1, emergencyDistance: GHOST_TRAIN_ATTACK_ENTRY_EMERGENCY_DISTANCE },
        track: { points: 0, visibleSections: 0, ahead: 0, spectralTurnRadius: getGhostTrainSpectralTurnRadius(null), updates: 0, rebuilds: 0, skippedRebuilds: 0 },
        hud: { visible: false, name: bossHudName ? bossHudName.textContent : "", hpRatio: 0 },
