          chainVisible: !!(church.chain && church.chain.visible),
          chainAttached: !!(church.chain && church.chain.parent),
          chainEnabled: !!(church.active && boss.active !== false),
          chainMatrixRebuilds: church.chain ? Math.max(0, church.chain.userData.matrixRebuildCount || 0) : 0,
