    addEnemyAccessoryBox(bookRig, 0.54 * s, 0.12 * s, 0.66 * s, mats.preacherCloth, 0, 0, 0);
    addEnemyAccessoryBox(bookRig, 0.46 * s, 0.04 * s, 0.56 * s, mats.preacherPaper, 0, 0.08 * s, 0, false);
