      var marshalFeared = (e.marshalFearTimer || 0) > 0;
      var spitterBusy = !marshalStunned && !marshalFeared && updateAcidSpitterAttack(e, p, dist, nx, nz, stepDt);
      var preacherBusy = updateGravePreacherRitual(e, stepDt, marshalStunned || marshalFeared);
