    var expansion = Math.max(0, Number(pad) || 0) + index.maxRadius;
    var minCellX = Math.floor((rect.minX - expansion) / HAZARD_SPATIAL_CELL_SIZE);
    var maxCellX = Math.floor((rect.maxX + expansion) / HAZARD_SPATIAL_CELL_SIZE);
    var minCellZ = Math.floor((rect.minZ - expansion) / HAZARD_SPATIAL_CELL_SIZE);
    var maxCellZ = Math.floor((rect.maxZ + expansion) / HAZARD_SPATIAL_CELL_SIZE);
