    var hasFireResults = !!(flags & MULTIPLAYER_PLAYER_FLAG_FIRE_RESULTS);
    var hasPendingUpgrades = !!(flags & MULTIPLAYER_PLAYER_FLAG_PENDING_UPGRADES);
    var hasUpgradeOffer = !!(flags & MULTIPLAYER_PLAYER_FLAG_UPGRADE_OFFER);
    var hasProgression = !!(flags & MULTIPLAYER_PLAYER_FLAG_PROGRESSION);
    if (!hasFireResults && packed[20] != null) return null;
    if (!hasProgression && packed[25] != null) return null;
    if (!hasPendingUpgrades && packed[26] != null) return null;
    if (!hasUpgradeOffer && packed[27] != null) return null;

