    if (op.mask & MULTIPLAYER_ENEMY_UPDATE_HP) bytes.push(enemy.hp & 255);
    if (op.mask & MULTIPLAYER_ENEMY_UPDATE_FX) bytes.push(enemy.fx & 15);
