      index: 0,
      chunks: chunks,
      preparedChunks: Object.create(null),
      chunkSampleTimes: Object.create(null),
      revision: replication.revision,
      sampleTime: Number(Math.max(0, state.time || 0).toFixed(3)),
      viewRevision: Math.max(1, replication.viewRevision || 1),
      viewTargetPlayerId: String(replication.viewTargetPlayerId || player && player.id || ""),
