  function getMultiplayerFirePatchType(patch) {
    if (!patch) return "fire";
    if (patch.splinter) return "splinter";
    if (patch.backdraft) return "backdraft";
    if (patch.thermite) return "thermite";
    if (patch.trail) return "trail";
    return "fire";
  }

  function isMultiplayerFirePatchTrailType(type) {
    return type === "trail" || type === "splinter" || type === "backdraft";
  }

  function createGuestMultiplayerFirePatchReplica(entry) {
    var x = Number(entry.x) || 0;
    var z = Number(entry.z) || 0;
    var radius = Math.max(0.2, Number(entry.radius) || FIRE_PATCH_BASE_RADIUS);
    var type = String(entry.type || "fire");
    var trail = isMultiplayerFirePatchTrailType(type);
    var life = Math.max(0, Number(entry.life) || 0);
    var replica = {
      networkId: entry.id,
      networkReplica: true,
      ownerPlayerId: String(entry.ownerId || ""),
      x: x,
      z: z,
      radius: radius,
      life: life,
      startLife: Math.max(0.001, life),
      type: type,
      armed: entry.armed !== false,
      trail: trail,
      visualSkippedDt: 0,
      visual: null,
      mesh: null,
      glow: null,
      surface: null,
      core: null,
      hotCore: null,
      smoke: null,
      ring: null,
      innerRing: null,
      flames: null,
      cinders: null,
      fireGpuStartAt: state.time,
      fireGpuEndAt: state.time + life,
    };
    insertHazardSpatialEntry(guestFirePatchSpatialIndex, replica, replica.radius);
    return replica;
  }

  function assignGuestFirePatchVisuals(visibleGround) {
    var ground = visibleGround || getCurrentVisibleGroundRect();
    var visible = queryLocallyRelevantFirePatches(guestFirePatchSpatialIndex, ground, []).filter(function (replica) {
      return replica && replica.life > 0 && isFirePatchLocallyVisible(replica, ground);
    });
    return assignDetailedFirePatchVisuals(visible, true);
  }

  function applyMultiplayerFirePatchSnapshot(entries, reconcileMissing) {
    entries = entries || [];
    var seen = Object.create(null);
    for (var i = 0; i < entries.length; i++) {
      var entry = entries[i];
      if (!entry || entry.id == null) continue;
      var key = String(entry.id);
      seen[key] = true;
      var type = String(entry.type || "fire");
      var trail = isMultiplayerFirePatchTrailType(type);
      var radius = Math.max(0.2, Number(entry.radius) || FIRE_PATCH_BASE_RADIUS);
      var replica = multiplayerState.guestFirePatchMap[key];
      if (!replica || replica.trail !== trail || Math.abs(replica.radius - radius) > 0.001) {
        if (replica) {
          removeHazardSpatialEntry(guestFirePatchSpatialIndex, replica);
          detachFirePatchVisual(replica);
        }
        replica = createGuestMultiplayerFirePatchReplica(entry);
        multiplayerState.guestFirePatchMap[key] = replica;
      }
      removeHazardSpatialEntry(guestFirePatchSpatialIndex, replica);
      replica.ownerPlayerId = String(entry.ownerId || "");
      replica.x = Number(entry.x) || 0;
      replica.z = Number(entry.z) || 0;
      replica.life = Math.max(0, Number(entry.life) || 0);
      replica.startLife = Math.max(replica.startLife || 0.001, replica.life, 0.001);
      replica.fireGpuEndAt = state.time + replica.life;
      replica.fireGpuStartAt = replica.fireGpuEndAt - replica.startLife;
      replica.type = type;
      replica.armed = entry.armed !== false;
      insertHazardSpatialEntry(guestFirePatchSpatialIndex, replica, replica.radius);
      if (replica.visual) fireGpuDetailedDirty = true;
    }
    if (reconcileMissing !== false) {
      Object.keys(multiplayerState.guestFirePatchMap).forEach(function (key) {
        if (seen[key]) return;
        var replica = multiplayerState.guestFirePatchMap[key];
        if (replica) {
          removeHazardSpatialEntry(guestFirePatchSpatialIndex, replica);
          detachFirePatchVisual(replica);
        }
        delete multiplayerState.guestFirePatchMap[key];
      });
    }
    var fallbackGround = getCurrentVisibleGroundRect();
    var fallbackCandidates = queryLocallyRelevantFirePatches(guestFirePatchSpatialIndex, fallbackGround, []);
    syncFireFallbackVisuals(fallbackCandidates, fallbackGround);
  }

