  function applyMultiplayerAcidPuddleSnapshot(entries, reconcileMissing) {
    entries = (entries || []).slice(-MAX_ACID_PUDDLES);
    var seen = Object.create(null);
    for (var i = 0; i < entries.length; i++) {
      var entry = entries[i];
      if (!entry || entry.id == null) continue;
      var key = String(entry.id);
      seen[key] = true;
      var puddle = multiplayerState.guestAcidPuddleMap[key];
      if (!puddle) {
        puddle = createGuestMultiplayerAcidPuddleReplica(entry);
        multiplayerState.guestAcidPuddleMap[key] = puddle;
      }
      puddle.x = Number(entry.x) || 0;
      puddle.z = Number(entry.z) || 0;
      puddle.radius = Math.max(0.2, Number(entry.radius) || ACID_PUDDLE_RADIUS);
      puddle.life = Math.max(0, Number(entry.life) || 0);
      puddle.startLife = Math.max(0.001, Number(entry.startLife) || puddle.startLife || ACID_PUDDLE_LIFE);
      puddle.mesh.position.set(puddle.x, 0, puddle.z);
      puddle.mesh.visible = true;
    }
    if (reconcileMissing !== false) {
      Object.keys(multiplayerState.guestAcidPuddleMap).forEach(function (key) {
        if (seen[key]) return;
        var puddle = multiplayerState.guestAcidPuddleMap[key];
        if (puddle && puddle.visual) releaseAcidPuddleVisual(puddle.visual);
        delete multiplayerState.guestAcidPuddleMap[key];
      });
    }
    // Sparse hazard upserts intentionally do not reconcile missing IDs until
    // the next full frame. Still enforce the host's hard visual/gameplay cap:
    // a delayed remove followed by newer upserts must never grow the guest
    // replica map beyond the fixed instancing capacity.
    var replicaKeys = Object.keys(multiplayerState.guestAcidPuddleMap);
    if (replicaKeys.length > MAX_ACID_PUDDLES) {
      replicaKeys.sort(function (firstKey, secondKey) {
        var firstSeen = seen[firstKey] ? 1 : 0;
        var secondSeen = seen[secondKey] ? 1 : 0;
        if (firstSeen !== secondSeen) return firstSeen - secondSeen;
        var firstPuddle = multiplayerState.guestAcidPuddleMap[firstKey];
        var secondPuddle = multiplayerState.guestAcidPuddleMap[secondKey];
        return (Number(firstPuddle && firstPuddle.networkId) || 0) - (Number(secondPuddle && secondPuddle.networkId) || 0);
      });
      var excess = replicaKeys.length - MAX_ACID_PUDDLES;
      for (var excessIndex = 0; excessIndex < excess; excessIndex++) {
        var staleKey = replicaKeys[excessIndex];
        var stalePuddle = multiplayerState.guestAcidPuddleMap[staleKey];
        if (stalePuddle && stalePuddle.visual) releaseAcidPuddleVisual(stalePuddle.visual);
        delete multiplayerState.guestAcidPuddleMap[staleKey];
      }
    }
  }

  function applyMultiplayerHallowedGroundSnapshot(entries) {
    entries = (entries || []).slice(-(COACH_GUN_MAX_HALLOWED_GROUNDS * MULTIPLAYER_MAX_PLAYERS));
    var seen = Object.create(null);
    for (var i = 0; i < entries.length; i++) {
      var entry = entries[i];
      if (!entry || entry.id == null) continue;
      var key = String(entry.id);
      seen[key] = true;
      var ground = multiplayerState.guestHallowedGroundMap[key];
      if (!ground) {
        var radius = Math.max(0.2, Number(entry.radius) || 3.8);
        var visual = acquireMarshalHallowedVisual(Number(entry.x) || 0, Number(entry.z) || 0, radius);
        ground = {
          networkId: entry.id,
          networkReplica: true,
          ownerPlayerId: String(entry.ownerId || ""),
          x: Number(entry.x) || 0,
          z: Number(entry.z) || 0,
          radius: radius,
          life: Math.max(0, Number(entry.life) || 0),
          startLife: Math.max(0.001, Number(entry.startLife) || 5),
          visual: visual,
        };
        multiplayerState.guestHallowedGroundMap[key] = ground;
        addShockwave(ground.x, ground.z, ground.radius, 0.5, 0xffe2a0);
      }
      ground.ownerPlayerId = String(entry.ownerId || "");
      ground.x = Number(entry.x) || 0;
      ground.z = Number(entry.z) || 0;
      ground.radius = Math.max(0.2, Number(entry.radius) || ground.radius || 3.8);
      ground.life = Math.max(0, Number(entry.life) || 0);
      ground.startLife = Math.max(0.001, Number(entry.startLife) || ground.startLife || 5);
      ground.visual.group.position.set(ground.x, 0, ground.z);
      ground.visual.group.scale.setScalar(ground.radius);
    }
    Object.keys(multiplayerState.guestHallowedGroundMap).forEach(function (key) {
      if (seen[key]) return;
      var ground = multiplayerState.guestHallowedGroundMap[key];
      if (ground && ground.visual) releaseMarshalHallowedVisual(ground.visual);
      delete multiplayerState.guestHallowedGroundMap[key];
    });
  }

  function spawnGuestPaleDeputyVolley(deputy, angle, distance) {
    if (!deputy) return;
    var range = clamp(Number(distance) || PALE_DEPUTY_ATTACK_RANGE, 0.8, PALE_DEPUTY_ATTACK_RANGE);
    var count = Math.min(COACH_GUN_STANDARD_TRACER_COUNT, PALE_DEPUTY_PELLET_COUNT);
    var forwardX = Math.sin(angle);
    var forwardZ = Math.cos(angle);
    for (var i = 0; i < count; i++) {
      var offset = count <= 1 ? 0 : (i / (count - 1) - 0.5) * PALE_DEPUTY_SPREAD;
      var rayAngle = angle + offset;
      spawnPaleDeputyTracer(
        deputy.x + forwardX * 0.48,
        1.25,
        deputy.z + forwardZ * 0.48,
        Math.sin(rayAngle),
        Math.cos(rayAngle),
        range
      );
    }
    playPaleDeputyShotSound(
      { x: deputy.x + forwardX * 0.48, y: 1.25, z: deputy.z + forwardZ * 0.48 },
      { x: forwardX, z: forwardZ }
    );
    deputy.shotPulse = 1;
    addLightFlash(deputy.x + forwardX * 0.72, 1.25, deputy.z + forwardZ * 0.72, 0x9adfff, 1.8, 4.8, 0.1);
  }

  function applyMultiplayerPaleDeputySnapshot(entries, snapshotTime) {
    entries = (entries || []).slice(-(PALE_DEPUTY_MAX_COUNT * MULTIPLAYER_MAX_PLAYERS));
    var seen = Object.create(null);
    var sampleTime = Number(snapshotTime);
    if (!Number.isFinite(sampleTime)) sampleTime = state.time;
    for (var i = 0; i < entries.length; i++) {
      var entry = entries[i];
      if (!entry || entry.id == null) continue;
      var key = String(entry.id);
      seen[key] = true;
      var deputy = multiplayerState.guestPaleDeputyMap[key];
      var created = false;
      if (!deputy) {
        deputy = acquirePaleDeputyEntity(Number(entry.x) || 0, Number(entry.z) || 0);
        deputy.networkId = entry.id;
        deputy.networkReplica = true;
        deputy.ownerPlayerId = String(entry.ownerId || "");
        deputy.lastNetworkShotSequence = Math.max(0, Math.floor(Number(entry.shot) || 0));
        multiplayerState.guestPaleDeputyMap[key] = deputy;
        spawnPaleDeputyRiseEffect(deputy.x, deputy.z, 1);
        created = true;
      }
      deputy.ownerPlayerId = String(entry.ownerId || "");
      var targetX = Number(entry.x) || 0;
      var targetZ = Number(entry.z) || 0;
      var previousTargetX = Number.isFinite(deputy.networkTargetX) ? deputy.networkTargetX : deputy.x;
      var previousTargetZ = Number.isFinite(deputy.networkTargetZ) ? deputy.networkTargetZ : deputy.z;
      var previousSampleTime = Number.isFinite(deputy.networkTargetSampleTime)
        ? deputy.networkTargetSampleTime
        : sampleTime - MULTIPLAYER_XP_SNAPSHOT_INTERVAL;
      var sampleDelta = sampleTime - previousSampleTime;
      if (!(sampleDelta > 0.0001)) sampleDelta = MULTIPLAYER_XP_SNAPSHOT_INTERVAL;
      var targetDelta = Math.hypot(targetX - previousTargetX, targetZ - previousTargetZ);
      var impliedSpeed = targetDelta / Math.max(1 / 240, sampleDelta);
      var teleported = !created && targetDelta > PALE_DEPUTY_NETWORK_TELEPORT_DISTANCE && (
        targetDelta > MULTIPLAYER_INTERPOLATION_TELEPORT_DISTANCE || impliedSpeed > 22
      );
      var velocityX = created || teleported ? 0 : (targetX - previousTargetX) / sampleDelta;
      var velocityZ = created || teleported ? 0 : (targetZ - previousTargetZ) / sampleDelta;
      var velocityLength = Math.hypot(velocityX, velocityZ);
      if (velocityLength > 22) {
        velocityX = velocityX / velocityLength * 22;
        velocityZ = velocityZ / velocityLength * 22;
      }
      if (!created && !teleported && deputy.networkHasTarget) {
        velocityX = (deputy.networkVelocityX || 0) * MULTIPLAYER_ENEMY_VELOCITY_BLEND + velocityX * (1 - MULTIPLAYER_ENEMY_VELOCITY_BLEND);
        velocityZ = (deputy.networkVelocityZ || 0) * MULTIPLAYER_ENEMY_VELOCITY_BLEND + velocityZ * (1 - MULTIPLAYER_ENEMY_VELOCITY_BLEND);
      }
      deputy.networkPreviousTargetX = created || teleported ? targetX : previousTargetX;
      deputy.networkPreviousTargetZ = created || teleported ? targetZ : previousTargetZ;
      deputy.networkPreviousSampleTime = created || teleported ? sampleTime : previousSampleTime;
      deputy.networkTargetX = targetX;
      deputy.networkTargetZ = targetZ;
      deputy.networkTargetSampleTime = sampleTime;
      deputy.networkTargetLocalTime = state.time;
      deputy.networkVelocityX = velocityX;
      deputy.networkVelocityZ = velocityZ;
      deputy.networkHasTarget = true;
      deputy.networkTargetAngle = Number(entry.angle) || 0;
      deputy.networkTargetMoveAmount = clamp(Number(entry.move) || 0, 0, 1);
      deputy.life = Math.max(0, Number(entry.life) || 0);
      if (created || teleported || !Number.isFinite(deputy.networkRenderSampleTime)) {
        initializeMultiplayerReplicaRenderClock(deputy, sampleTime);
      }
      if (teleported) {
        spawnPaleDeputyRiseEffect(deputy.x, deputy.z, 0.38);
        deputy.x = targetX;
        deputy.z = targetZ;
        deputy.group.position.set(targetX, 0, targetZ);
        deputy.networkTeleportCount = Math.max(0, deputy.networkTeleportCount || 0) + 1;
        spawnPaleDeputyRiseEffect(targetX, targetZ, 0.54);
      }
      var shotSequence = Math.max(0, Math.floor(Number(entry.shot) || 0));
      if (!created && shotSequence > (deputy.lastNetworkShotSequence || 0)) {
        spawnGuestPaleDeputyVolley(deputy, Number(entry.shotAngle) || deputy.networkTargetAngle, Number(entry.shotDistance) || PALE_DEPUTY_ATTACK_RANGE);
      }
      deputy.lastNetworkShotSequence = shotSequence;
    }
    Object.keys(multiplayerState.guestPaleDeputyMap).forEach(function (key) {
      if (seen[key]) return;
      var deputy = multiplayerState.guestPaleDeputyMap[key];
      if (deputy) {
        spawnPaleDeputyRiseEffect(deputy.x, deputy.z, 0.55);
        releasePaleDeputyEntity(deputy);
      }
      delete multiplayerState.guestPaleDeputyMap[key];
    });
  }

  function updateGuestAcidPuddleVisual(puddle, index, dt) {
    if (!puddle || !puddle.visual) return;
    puddle.life = Math.max(0, puddle.life - dt);
    var fade = clamp(puddle.life / Math.max(0.001, puddle.startLife), 0, 1);
    var pulse = 1 + Math.sin(state.time * 7 + index) * 0.035;
    if (puddle.surface) {
      puddle.surface.material.opacity = 0.4 * Math.min(1, fade * 1.55);
      puddle.surface.rotation.z += dt * 0.08;
      scaleFromBase(puddle.surface, pulse, 1 - (pulse - 1) * 0.55, 1);
    }
    if (puddle.darkPatch) {
      puddle.darkPatch.material.opacity = 0.24 * Math.min(1, fade * 1.35);
      puddle.darkPatch.rotation.z -= dt * 0.16;
      scaleFromBase(puddle.darkPatch, 1 + Math.sin(state.time * 5.3 + index) * 0.08, 1 + Math.cos(state.time * 4.1 + index) * 0.06, 1);
    }
    if (puddle.ring) {
      var ringPulse = 1 + ((state.time * 0.72 + index * 0.21) % 1) * 0.32;
      puddle.ring.material.opacity = 0.36 * fade * (2 - ringPulse);
      scaleFromBase(puddle.ring, ringPulse, ringPulse * 0.86, 1);
    }
    if (puddle.foam) {
      puddle.foam.material.opacity = 0.45 * Math.min(1, fade * 1.8) * (0.78 + Math.sin(state.time * 8 + index) * 0.22);
      puddle.foam.rotation.z += dt * 0.42;
    }
    var bubbles = puddle.bubbles || [];
    for (var b = 0; b < bubbles.length; b++) {
      var bubble = bubbles[b];
      var phase = bubble.userData.bubblePhase || 0;
      var bubblePulse = 0.7 + Math.max(0, Math.sin(state.time * 5.8 + phase)) * 0.75;
      bubble.position.y = (Number(puddle.visual && puddle.visual.surfaceY) || ACID_PUDDLE_BASE_SURFACE_Y) + 0.03 + Math.max(0, Math.sin(state.time * 5.8 + phase)) * 0.09;
      scaleFromBase(bubble, bubblePulse, 0.28 + bubblePulse * 0.18, bubblePulse);
    }
  }

  function getPointSegmentDistanceSquared(px, pz, x1, z1, x2, z2) {
    var dx = x2 - x1;
    var dz = z2 - z1;
    var lengthSquared = dx * dx + dz * dz;
    if (lengthSquared <= 0.000001) {
      var pointDx = px - x1;
      var pointDz = pz - z1;
      return pointDx * pointDx + pointDz * pointDz;
    }
    var t = clamp(((px - x1) * dx + (pz - z1) * dz) / lengthSquared, 0, 1);
    var closestX = x1 + dx * t;
    var closestZ = z1 + dz * t;
    var distanceX = px - closestX;
    var distanceZ = pz - closestZ;
    return distanceX * distanceX + distanceZ * distanceZ;
  }

  function findGuestBulletVisualHit(bullet, oldX, oldZ) {
    if (!bullet) return null;
    var rect = guestBulletSweepRectScratch;
    rect.minX = Math.min(oldX, bullet.x);
    rect.maxX = Math.max(oldX, bullet.x);
    rect.minZ = Math.min(oldZ, bullet.z);
    rect.maxZ = Math.max(oldZ, bullet.z);
    var candidates = guestEnemyVisualSpatialIndex.occupants
      ? queryHazardSpatialRect(guestEnemyVisualSpatialIndex, rect, 1.25, guestBulletEnemySpatialScratch)
      : [];
    var bulletRadius = Math.max(0.08, Number(bullet.visualWidth) || 0.1);
    var best = null;
    var bestTime = Infinity;
    for (var i = 0; i < candidates.length; i++) {
      var enemy = candidates[i];
      if (!enemy || enemy.active === false || !enemy.networkReplica || enemy.hp <= 0) continue;
      if (bullet.piercing || bullet.type === "launcherFireShard") continue;
      var radius = (enemy.radius || 0.75) + bulletRadius;
      var enemyTime = getSegmentCircleEntryTime(oldX, oldZ, bullet.x, bullet.z, enemy.x, enemy.z, radius);
      if (enemyTime != null && enemyTime < bestTime) {
        bestTime = enemyTime;
        best = { kind: "enemy", id: enemy.networkId || 0, target: enemy, time: enemyTime };
      }
    }
    var bellBoss = getActiveBossDamageTarget();
    if (bellBoss && !bullet.piercing && bullet.type !== "launcherFireShard") {
      var bossTime = getSegmentCircleEntryTime(oldX, oldZ, bullet.x, bullet.z, bellBoss.x, bellBoss.z, bellBoss.radius + bulletRadius);
      if (bossTime != null && bossTime < bestTime) {
        bestTime = bossTime;
        best = { kind: "enemy", id: bellBoss.networkId || bellBoss.id || "bell-ringer", target: bellBoss, time: bossTime };
      }
    }
    if (!bullet.piercing && bullet.type !== "launcherFireShard") {
      forEachActiveOilBaronDouble(function (oilDouble) {
        var hitTime = getSegmentCircleEntryTime(oldX, oldZ, bullet.x, bullet.z, oilDouble.x, oilDouble.z, oilDouble.radius + bulletRadius);
        if (hitTime != null && hitTime < bestTime) {
          bestTime = hitTime;
          best = { kind: "enemy", id: oilDouble.networkId || oilDouble.id, target: oilDouble, time: hitTime };
        }
      });
      forEachActiveOilBaronDebtChain(function (proxy) {
        var hitTime = getSegmentCircleEntryTime(oldX, oldZ, bullet.x, bullet.z, proxy.x, proxy.z, proxy.radius + bulletRadius);
        if (hitTime != null && hitTime < bestTime) {
          bestTime = hitTime;
          best = { kind: "enemy", id: proxy.networkId || proxy.id, target: proxy, time: hitTime };
        }
      }, true);
    }
    for (var playerIndex = 0; playerIndex < multiplayerState.playerOrder.length; playerIndex++) {
      var player = getMultiplayerPlayer(multiplayerState.playerOrder[playerIndex]);
      if (
        !player || player.id === bullet.ownerPlayerId || !player.alive || player.surrendered ||
        !player.entity || player.entity.invuln > 0
      ) continue;
      var playerRadius = (player.entity.radius || 0.5) + bulletRadius;
      var playerTime = getSegmentCircleEntryTime(oldX, oldZ, bullet.x, bullet.z, player.entity.x, player.entity.z, playerRadius);
      if (playerTime != null && playerTime < bestTime) {
        bestTime = playerTime;
        best = { kind: "player", id: player.id, target: player.entity, time: playerTime };
      }
    }
    var obstacle = findBlockingObstacle(oldX, oldZ, bullet.x, bullet.z, bulletRadius * 0.7, null, -0.000001);
    if (obstacle && obstacle.t < bestTime) {
      best = { kind: "world", id: "", target: null, time: obstacle.t };
    }
    return best;
  }

  function holdGuestBulletAtVisualContact(bullet, now) {
    if (!bullet || !bullet.networkVisualContactAt) return false;
    var record = getGuestPredictedShotRecord(
      bullet.ownerPlayerId || "",
      bullet.type || "revolver",
      bullet.clientFireSequence
    );
    var awaitingLocalAuthority = bullet.ownerPlayerId === multiplayerState.localPlayerId && (
      isLocalFireActionPending(bullet.ownerPlayerId, bullet.clientFireSequence) || !!record || !!bullet.networkLocallyPredicted
    );
    var holdMs = awaitingLocalAuthority
      ? MULTIPLAYER_GUEST_VISUAL_CONTACT_AUTHORITY_TIMEOUT_MS
      : MULTIPLAYER_GUEST_VISUAL_CONTACT_HOLD_MS;
    if (now - bullet.networkVisualContactAt < holdMs) {
      if (bullet.mesh) {
        bullet.mesh.visible = false;
        syncStandardProjectileVisual(bullet.visual);
      }
      return true;
    }
    if (awaitingLocalAuthority) {
      bullet.networkVisualContactExpired = true;
      return true;
    }
    bullet.networkVisualContactAt = 0;
    bullet.networkVisualContactKind = "";
    bullet.networkVisualContactEnemyId = 0;
    bullet.networkVisualContactPlayerId = "";
    bullet.networkVisualContactX = 0;
    bullet.networkVisualContactZ = 0;
    if (bullet.mesh) {
      bullet.mesh.visible = true;
      syncStandardProjectileVisual(bullet.visual);
    }
    return false;
  }

  function beginGuestBulletVisualContact(bullet, oldX, oldZ, now) {
    var contact = findGuestBulletVisualHit(bullet, oldX, oldZ);
    if (!contact) {
      if (bullet.mesh && !bullet.networkVisualContactAt) {
        bullet.mesh.visible = true;
        syncStandardProjectileVisual(bullet.visual);
      }
      return false;
    }
    bullet.networkVisualContactAt = now;
    bullet.networkVisualContactKind = contact.kind;
    bullet.networkVisualContactEnemyId = contact.kind === "enemy" ? contact.id : 0;
    bullet.networkVisualContactPlayerId = contact.kind === "player" ? contact.id : "";
    bullet.networkVisualContactX = oldX + (bullet.x - oldX) * clamp(contact.time, 0, 1);
    bullet.networkVisualContactZ = oldZ + (bullet.z - oldZ) * clamp(contact.time, 0, 1);
    if (bullet.mesh) {
      bullet.mesh.visible = false;
      syncStandardProjectileVisual(bullet.visual);
    }
    return true;
  }

  function getGuestBulletElapsedSinceNetworkSample(bullet, now, maximum) {
    if (!bullet) return 0;
    var receivedElapsed = Math.max(0, now - (bullet.networkTargetAt || now)) / 1000;
    var sampleLead = clamp(
      Number(bullet.networkSampleLead) || 0,
      0,
      MULTIPLAYER_PROJECTILE_SAMPLE_LEAD_MAX
    );
    return Math.min(Math.max(0, Number(maximum) || 0.18), sampleLead + receivedElapsed);
  }

  function getGuestProjectileForwardCorrection(bullet, forwardError, alpha, baseStep, locallyPredicted) {
    var correction = forwardError * alpha;
    if (!bullet || bullet.type !== "launcher") {
      return clamp(correction, -baseStep * 0.82, baseStep * 2.5);
    }
    // A launcher round is straight, constant-speed ballistics.  Large per-frame
    // corrections are visually much more obvious on its slow, chunky model than
    // on a rifle tracer, so keep authority convergence continuous and bounded.
    var backLimit = locallyPredicted
      ? MULTIPLAYER_LOCAL_LAUNCHER_FORWARD_CORRECTION_BACK
      : MULTIPLAYER_REMOTE_LAUNCHER_FORWARD_CORRECTION_BACK;
    var aheadLimit = locallyPredicted
      ? MULTIPLAYER_LOCAL_LAUNCHER_FORWARD_CORRECTION_AHEAD
      : MULTIPLAYER_REMOTE_LAUNCHER_FORWARD_CORRECTION_AHEAD;
    var deadzone = locallyPredicted ? 0.14 : 0.06;
    if (Math.abs(forwardError) <= deadzone) return 0;
    correction = (Math.abs(forwardError) - deadzone) * Math.sign(forwardError) * alpha;
    return clamp(correction, -baseStep * backLimit, baseStep * aheadLimit);
  }

  function updateGuestLauncherProjectileVisual(bullet, dt, now) {
    if (!bullet || bullet.type !== "launcher" || !bullet.mesh) return;
    var frameDelta = Math.max(0, Number(dt) || 0);
    var maxLife = Math.max(
      0.05,
      Number(bullet.networkArcMaxLife) || Number(bullet.maxLife) || WEAPONS.launcher.life
    );
    var age = Math.max(0, Number(bullet.age) || 0) + frameDelta;
    if (Number.isFinite(Number(bullet.networkArcSampleAge))) {
      var authoritativeAge = Math.max(0, Number(bullet.networkArcSampleAge)) +
        getGuestBulletElapsedSinceNetworkSample(bullet, now, 0.32);
      var ageError = authoritativeAge - age;
      var ageAlpha = 1 - Math.exp(-(bullet.networkLocallyPredicted ? 4.5 : 7.5) * frameDelta);
      age += clamp(ageError * ageAlpha, -frameDelta * 0.18, frameDelta * 0.42);
    }
    bullet.maxLife = maxLife;
    bullet.age = clamp(age, 0, maxLife);
    var progress = clamp(bullet.age / maxLife, 0, 1);
    bullet.y = 0.68 + Math.sin(progress * Math.PI) * 1.15;
    bullet.mesh.rotation.x += frameDelta * 7.5;
    bullet.mesh.rotation.z += frameDelta * 5.2;
  }

  function updateMultiplayerGuestCombatReplicas(dt) {
    var visibleGround = getCurrentVisibleGroundRect();
    var now = performance.now();
    Object.keys(multiplayerState.guestAcidProjectileMap).forEach(function (key) {
      var spit = multiplayerState.guestAcidProjectileMap[key];
      if (!spit || !spit.mesh) return;
      spit.life = Math.max(0, spit.life - dt);
      spit.age += dt;
      var elapsed = Math.min(0.1, Math.max(0, now - (spit.networkTargetAt || now)) / 1000);
      var desiredX = spit.networkTargetX + spit.dirX * spit.speed * elapsed;
      var desiredZ = spit.networkTargetZ + spit.dirZ * spit.speed * elapsed;
      var alpha = 1 - Math.exp(-20 * dt);
      spit.x += (desiredX - spit.x) * alpha;
      spit.y += ((spit.networkTargetY || spit.y) - spit.y) * alpha;
      spit.z += (desiredZ - spit.z) * alpha;
      var progress = clamp(1 - spit.life / Math.max(0.001, spit.maxLife), 0, 1);
      spit.mesh.position.set(spit.x, spit.y, spit.z);
      var projectileVisible = !pointOutsideVisibleGround(spit.x, spit.z, 1.2, visibleGround);
      spit.mesh.visible = projectileVisible;
      if (projectileVisible) animateAcidProjectileMesh(spit, progress, dt);
      spit.dripTimer -= dt;
      if (projectileVisible && spit.dripTimer <= 0) {
        spit.dripTimer = 0.045;
        spawnSlimeParticle(
          spit.x - spit.dirX * rand(0.05, 0.32),
          spit.y + rand(-0.08, 0.08),
          spit.z - spit.dirZ * rand(0.05, 0.32),
          -spit.dirX * rand(0.4, 1.4) + rand(-0.35, 0.35),
          rand(-0.25, 0.55),
          -spit.dirZ * rand(0.4, 1.4) + rand(-0.35, 0.35),
          rand(0.2, 0.38),
          rand(0.045, 0.095),
          rng() < 0.42 ? mats.acidSpitHot : mats.acidSpitCore
        );
      }
    });
    var acidPuddleIndex = 0;
    Object.keys(multiplayerState.guestAcidPuddleMap).forEach(function (key) {
      var puddle = multiplayerState.guestAcidPuddleMap[key];
      if (!puddle || !puddle.mesh) return;
      var visible = !pointOutsideVisibleGround(puddle.x, puddle.z, puddle.radius + FIRE_VISUAL_CULL_PAD, visibleGround);
      puddle.mesh.visible = visible;
      if (visible) updateGuestAcidPuddleVisual(puddle, acidPuddleIndex, dt);
      acidPuddleIndex += 1;
    });
    Object.keys(multiplayerState.guestHallowedGroundMap).forEach(function (key) {
      var ground = multiplayerState.guestHallowedGroundMap[key];
      if (!ground || !ground.visual) return;
      ground.life = Math.max(0, ground.life - dt);
      var fade = clamp(ground.life / Math.max(0.001, ground.startLife), 0, 1);
      ground.visual.group.rotation.y += dt * 0.24;
      ground.visual.material.opacity = 0.12 + Math.sin(state.time * 4.2 + Number(key)) * 0.04 + fade * 0.16;
      ground.visual.inner.rotation.z -= dt * 0.6;
      ground.visual.group.visible = ground.life > 0 && !pointOutsideVisibleGround(ground.x, ground.z, ground.radius + 1, visibleGround);
    });
    Object.keys(multiplayerState.guestPaleDeputyMap).forEach(function (key) {
      var deputy = multiplayerState.guestPaleDeputyMap[key];
      if (!deputy || !deputy.group) return;
      var oldX = deputy.x;
      var oldZ = deputy.z;
      var desiredX = Number.isFinite(deputy.networkTargetX) ? deputy.networkTargetX : deputy.x;
      var desiredZ = Number.isFinite(deputy.networkTargetZ) ? deputy.networkTargetZ : deputy.z;
      var latestSampleTime = Number.isFinite(deputy.networkTargetSampleTime) ? deputy.networkTargetSampleTime : 0;
      var previousSampleTime = Number.isFinite(deputy.networkPreviousSampleTime)
        ? deputy.networkPreviousSampleTime
        : latestSampleTime;
      var renderSampleTime = advanceMultiplayerReplicaRenderClock(deputy, latestSampleTime, dt);
      if (previousSampleTime < latestSampleTime && renderSampleTime <= latestSampleTime) {
        var sampleAlpha = clamp(
          (renderSampleTime - previousSampleTime) / Math.max(1 / 240, latestSampleTime - previousSampleTime),
          0,
          1
        );
        desiredX = (Number.isFinite(deputy.networkPreviousTargetX) ? deputy.networkPreviousTargetX : desiredX) +
          (desiredX - (Number.isFinite(deputy.networkPreviousTargetX) ? deputy.networkPreviousTargetX : desiredX)) * sampleAlpha;
        desiredZ = (Number.isFinite(deputy.networkPreviousTargetZ) ? deputy.networkPreviousTargetZ : desiredZ) +
          (desiredZ - (Number.isFinite(deputy.networkPreviousTargetZ) ? deputy.networkPreviousTargetZ : desiredZ)) * sampleAlpha;
      } else if (renderSampleTime > latestSampleTime) {
        var extrapolation = Math.min(MULTIPLAYER_ENEMY_EXTRAPOLATION_TIME, renderSampleTime - latestSampleTime);
        desiredX += (deputy.networkVelocityX || 0) * extrapolation;
        desiredZ += (deputy.networkVelocityZ || 0) * extrapolation;
      }
      var positionError = Math.hypot(desiredX - deputy.x, desiredZ - deputy.z);
      var alpha = 1 - Math.exp(-MULTIPLAYER_REMOTE_INTERPOLATION * 1.35 * dt);
      if (positionError > MULTIPLAYER_INTERPOLATION_TELEPORT_DISTANCE) {
        deputy.x = desiredX;
        deputy.z = desiredZ;
      } else {
        deputy.x += (desiredX - deputy.x) * alpha;
        deputy.z += (desiredZ - deputy.z) * alpha;
      }
      var angleDelta = Math.atan2(Math.sin((deputy.networkTargetAngle || 0) - deputy.group.rotation.y), Math.cos((deputy.networkTargetAngle || 0) - deputy.group.rotation.y));
      deputy.group.rotation.y += angleDelta * alpha;
      var moved = Math.hypot(deputy.x - oldX, deputy.z - oldZ);
      var replicatedSpeed = Math.max(BASE_PLAYER_SPEED, Math.hypot(deputy.networkVelocityX || 0, deputy.networkVelocityZ || 0));
      deputy.moveAmount += (Math.max(clamp(moved / Math.max(0.001, replicatedSpeed * dt), 0, 1), deputy.networkTargetMoveAmount || 0) - deputy.moveAmount) * Math.min(1, dt * 11);
      deputy.walkPhase += dt * (7.2 + BASE_PLAYER_SPEED * 0.48) * deputy.moveAmount;
      deputy.shotPulse = Math.max(0, deputy.shotPulse - dt * 6.5);
      deputy.group.position.set(deputy.x, 0, deputy.z);
      deputy.group.visible = deputy.life > 0 && !pointOutsideVisibleGround(deputy.x, deputy.z, PALE_DEPUTY_RADIUS + ENEMY_VISUAL_CULL_PAD, visibleGround);
      if (deputy.group.visible) animatePaleDeputy(deputy, dt);
    });
    Object.keys(multiplayerState.guestBulletMap).forEach(function (key) {
      var bullet = multiplayerState.guestBulletMap[key];
      if (!bullet || !bullet.mesh || !Number.isFinite(bullet.networkTargetX) || !Number.isFinite(bullet.networkTargetZ)) return;
      var minimumVisible = (bullet.networkMinimumVisibleUntil || 0) > now;
      var visualContactHeld = holdGuestBulletAtVisualContact(bullet, now);
      if (bullet.networkVisualContactExpired) {
        removeGuestMultiplayerBullet(key, bullet);
        return;
      }
      if (bullet.networkPredicted) {
        var predictedMoveDt = Math.min(Math.max(0, bullet.life || 0), dt);
        bullet.life = Math.max(0, (bullet.life || 0) - predictedMoveDt);
        var fireStillPending = isLocalFireActionPending(bullet.ownerPlayerId, bullet.clientFireSequence);
        var predictedRecord = getGuestPredictedShotRecord(bullet.ownerPlayerId || "", bullet.type || "revolver", bullet.clientFireSequence);
        var acceptedPrediction = !!(predictedRecord && predictedRecord.result === "accepted");
        if (!minimumVisible && predictedMoveDt <= 0) {
          removeGuestMultiplayerBullet(key, bullet);
          return;
        }
        var predictedOldX = bullet.x;
        var predictedOldZ = bullet.z;
        bullet.x += (bullet.dirX || 0) * (bullet.speed || 0) * predictedMoveDt;
        bullet.z += (bullet.dirZ || 0) * (bullet.speed || 0) * predictedMoveDt;
        if (!visualContactHeld) beginGuestBulletVisualContact(bullet, predictedOldX, predictedOldZ, now);
        updateGuestLauncherProjectileVisual(bullet, predictedMoveDt, now);
        bullet.mesh.position.set(bullet.x, bullet.y, bullet.z);
        syncStandardProjectileVisual(bullet.visual);
        if (!minimumVisible && (
          bullet.life <= 0 ||
          (!fireStillPending && !acceptedPrediction && now - (bullet.predictedAt || now) > 400)
        )) removeGuestMultiplayerBullet(key, bullet);
        return;
      }
      if (bullet.networkLocallyPredicted) {
        if (
          !minimumVisible && (
            (Number.isFinite(bullet.networkExpiresAt) && state.time >= bullet.networkExpiresAt) ||
            now - (bullet.networkTargetAt || now) > MULTIPLAYER_GUEST_BULLET_STALE_MS
          )
        ) {
          removeGuestMultiplayerBullet(key, bullet);
          return;
        }
        var localOldX = bullet.x;
        var localOldZ = bullet.z;
        var localElapsed = getGuestBulletElapsedSinceNetworkSample(bullet, now, 0.28);
        var authoritativeX = bullet.networkTargetX + (bullet.dirX || 0) * (bullet.speed || 0) * localElapsed;
        var authoritativeZ = bullet.networkTargetZ + (bullet.dirZ || 0) * (bullet.speed || 0) * localElapsed;
        var correctionX = authoritativeX - bullet.x;
        var correctionZ = authoritativeZ - bullet.z;
        var directionX = bullet.dirX || 0;
        var directionZ = bullet.dirZ || 0;
        var directionLength = Math.max(0.001, Math.hypot(directionX, directionZ));
        directionX /= directionLength;
        directionZ /= directionLength;
        var forwardError = correctionX * directionX + correctionZ * directionZ;
        var lateralX = correctionX - directionX * forwardError;
        var lateralZ = correctionZ - directionZ * forwardError;
        var localAlpha = 1 - Math.exp(-20 * dt);
        var baseLocalStep = (bullet.speed || 0) * dt;
        var localStep = Math.max(0, baseLocalStep + getGuestProjectileForwardCorrection(
          bullet,
          forwardError,
          localAlpha,
          baseLocalStep,
          true
        ));
        bullet.x += directionX * localStep + lateralX * localAlpha;
        if (bullet.type !== "launcher") bullet.y += ((bullet.networkTargetY || bullet.y) - bullet.y) * localAlpha;
        bullet.z += directionZ * localStep + lateralZ * localAlpha;
        if (!visualContactHeld) beginGuestBulletVisualContact(bullet, localOldX, localOldZ, now);
        updateGuestLauncherProjectileVisual(bullet, dt, now);
        bullet.mesh.position.set(bullet.x, bullet.y, bullet.z);
        syncStandardProjectileVisual(bullet.visual);
        return;
      }
      if (
        !minimumVisible && (
          (Number.isFinite(bullet.networkExpiresAt) && state.time >= bullet.networkExpiresAt) ||
          now - (bullet.networkTargetAt || now) > MULTIPLAYER_GUEST_BULLET_STALE_MS
        )
      ) {
        removeGuestMultiplayerBullet(key, bullet);
        return;
      }
      var remoteOldX = bullet.x;
      var remoteOldZ = bullet.z;
      var elapsed = getGuestBulletElapsedSinceNetworkSample(bullet, now, 0.28);
      var desiredX = bullet.networkTargetX + (bullet.dirX || 0) * (bullet.speed || 0) * elapsed;
      var desiredZ = bullet.networkTargetZ + (bullet.dirZ || 0) * (bullet.speed || 0) * elapsed;
      var alpha = 1 - Math.exp(-20 * dt);
      var remoteDirectionX = bullet.dirX || 0;
      var remoteDirectionZ = bullet.dirZ || 0;
      var remoteDirectionLength = Math.max(0.001, Math.hypot(remoteDirectionX, remoteDirectionZ));
      remoteDirectionX /= remoteDirectionLength;
      remoteDirectionZ /= remoteDirectionLength;
      var remoteCorrectionX = desiredX - bullet.x;
      var remoteCorrectionZ = desiredZ - bullet.z;
      var remoteForwardError = remoteCorrectionX * remoteDirectionX + remoteCorrectionZ * remoteDirectionZ;
      var remoteLateralX = remoteCorrectionX - remoteDirectionX * remoteForwardError;
      var remoteLateralZ = remoteCorrectionZ - remoteDirectionZ * remoteForwardError;
      var remoteBaseStep = (bullet.speed || 0) * dt;
      var remoteStep = Math.max(0, remoteBaseStep + getGuestProjectileForwardCorrection(
        bullet,
        remoteForwardError,
        alpha,
        remoteBaseStep,
        false
      ));
      bullet.x += remoteDirectionX * remoteStep + remoteLateralX * alpha;
      if (bullet.type !== "launcher") bullet.y += ((bullet.networkTargetY || bullet.y) - bullet.y) * alpha;
      bullet.z += remoteDirectionZ * remoteStep + remoteLateralZ * alpha;
      if (!visualContactHeld) beginGuestBulletVisualContact(bullet, remoteOldX, remoteOldZ, now);
      updateGuestLauncherProjectileVisual(bullet, dt, now);
      bullet.mesh.position.set(bullet.x, bullet.y, bullet.z);
      syncStandardProjectileVisual(bullet.visual);
    });
    var fireIndex = 0;
    var fireReplicaKeys = Object.keys(multiplayerState.guestFirePatchMap);
    fireReplicaKeys.forEach(function (key) {
      var replica = multiplayerState.guestFirePatchMap[key];
      replica.life = Math.max(0, replica.life - dt);
      if (replica.life <= 0) {
        removeHazardSpatialEntry(guestFirePatchSpatialIndex, replica);
        detachFirePatchVisual(replica);
        delete multiplayerState.guestFirePatchMap[key];
      }
    });
    var visibleFireReplicas = queryLocallyRelevantFirePatches(guestFirePatchSpatialIndex, visibleGround, []);
    visibleFireReplicas = visibleFireReplicas.filter(function (replica) {
      return replica && replica.life > 0 && isFirePatchLocallyVisible(replica, visibleGround);
    });
    fireVisualAssignmentTimer -= dt;
    if (fireVisualAssignmentTimer <= 0) {
      fireVisualAssignmentTimer = 0.12;
      visibleFireReplicas = assignDetailedFirePatchVisuals(visibleFireReplicas, true);
    }
    syncFireGpuDetailedVisuals();
    updateFireGpuAnimationTime();
    syncFireFallbackVisuals(visibleFireReplicas, visibleGround);
    Object.keys(multiplayerState.guestRifleTrapMap).forEach(function (key) {
      var replica = multiplayerState.guestRifleTrapMap[key];
      replica.age = state.time;
      var visible = !pointOutsideVisibleGround(replica.x, replica.z, replica.radius + TRAP_VISUAL_CULL_PAD, visibleGround);
      setRifleTrapVisualPresence(replica, visible);
      if (!visible) return;
      updateRifleTrapVisual(replica, replica.armed ? 1 : 0.45);
    });
  }

  function releaseAllGuestMultiplayerCombatReplicas() {
    var bulletMap = multiplayerState.guestBulletMap || {};
    Object.keys(bulletMap).forEach(function (key) {
      removeGuestMultiplayerBullet(key, bulletMap[key]);
    });
    var xpMap = multiplayerState.guestXpOrbMap || {};
    Object.keys(xpMap).forEach(function (key) {
      var orb = xpMap[key];
      var index = state.xpOrbs.indexOf(orb);
      if (index !== -1) removeXpOrb(index);
    });
    var fireMap = multiplayerState.guestFirePatchMap || {};
    Object.keys(fireMap).forEach(function (key) {
      var replica = fireMap[key];
      if (replica) {
        removeHazardSpatialEntry(guestFirePatchSpatialIndex, replica);
        detachFirePatchVisual(replica);
      }
    });
    clearHazardSpatialIndex(guestFirePatchSpatialIndex);
    syncFireFallbackVisuals([], getCurrentVisibleGroundRect());
    var trapMap = multiplayerState.guestRifleTrapMap || {};
    Object.keys(trapMap).forEach(function (key) {
      var replica = trapMap[key];
      if (replica && replica.visual) releaseRifleTrapVisual(replica.visual);
    });
    var acidProjectileMap = multiplayerState.guestAcidProjectileMap || {};
    Object.keys(acidProjectileMap).forEach(function (key) {
      var spit = acidProjectileMap[key];
      if (spit && spit.mesh) releaseAcidProjectileVisual(spit.mesh);
    });
    var acidPuddleMap = multiplayerState.guestAcidPuddleMap || {};
    Object.keys(acidPuddleMap).forEach(function (key) {
      var puddle = acidPuddleMap[key];
      if (puddle && puddle.visual) releaseAcidPuddleVisual(puddle.visual);
    });
    var hallowedGroundMap = multiplayerState.guestHallowedGroundMap || {};
    Object.keys(hallowedGroundMap).forEach(function (key) {
      var ground = hallowedGroundMap[key];
      if (ground && ground.visual) releaseMarshalHallowedVisual(ground.visual);
    });
    var paleDeputyMap = multiplayerState.guestPaleDeputyMap || {};
    Object.keys(paleDeputyMap).forEach(function (key) {
      var deputy = paleDeputyMap[key];
      if (deputy) releasePaleDeputyEntity(deputy);
    });
    multiplayerState.guestFirePatchMap = Object.create(null);
    multiplayerState.guestBulletMap = Object.create(null);
    multiplayerState.guestRifleTrapMap = Object.create(null);
    multiplayerState.guestXpOrbMap = Object.create(null);
    multiplayerState.guestAcidProjectileMap = Object.create(null);
    multiplayerState.guestAcidPuddleMap = Object.create(null);
    multiplayerState.guestHallowedGroundMap = Object.create(null);
    multiplayerState.guestPaleDeputyMap = Object.create(null);
  }

  function applyMultiplayerCombatEventSnapshot(entries) {
    if (!isMultiplayerGuestMatch() || !Array.isArray(entries) || !entries.length) return;
    var ordered = entries.slice().sort(function (a, b) {
      return (Number(a && a.sequence) || 0) - (Number(b && b.sequence) || 0);
    });
    for (var eventIndex = 0; eventIndex < ordered.length; eventIndex++) {
      var event = ordered[eventIndex];
      if (!event) return;
      var sequence = Math.floor(Number(event.sequence));
      if (!Number.isFinite(sequence) || sequence <= multiplayerState.lastCombatEventSequence) continue;
      if (sequence > multiplayerState.lastCombatEventSequence + 1) break;
      var result = applyMultiplayerCombatEventVisual(event);
      if (!result) break;
      multiplayerState.lastCombatEventSequence = sequence;
      multiplayerState.guestCombatEventLog.push({
        sequence: sequence,
        type: String(event.type || ""),
        ownerId: String(event.ownerId || ""),
        sound: result.sound || null,
        visuals: Math.max(0, Math.floor(Number(result.visuals) || 0)),
      });
      if (multiplayerState.guestCombatEventLog.length > MULTIPLAYER_COMBAT_EVENT_HISTORY * 2) {
        multiplayerState.guestCombatEventLog.splice(0, multiplayerState.guestCombatEventLog.length - MULTIPLAYER_COMBAT_EVENT_HISTORY * 2);
      }
    }
  }

  function applyMultiplayerCombatEventVisual(event) {
    if (event.type === "playerDied" || event.type === "playerEliminated" || event.type === "playerLeft") {
      appendMultiplayerMatchHistoryEvent(event);
      return { sound: null, visuals: 0 };
    }
    if (event.type === "projectileSpawn") return applyGuestProjectileSpawnEvent(event);
    if (event.type === "projectileImpact") return applyGuestProjectileImpactEvent(event);
    if (event.type === "projectileDespawn") return applyGuestProjectileDespawnEvent(event);
    if (event.type === "projectileDespawnBatch") return applyGuestProjectileDespawnBatchEvent(event);
    if (event.type === "firePatchSpawn") {
      if (event.entry) applyMultiplayerFirePatchSnapshot([event.entry], false);
      return { sound: null, visuals: event.entry ? 1 : 0 };
    }
    if (event.type === "rifleTrapSpawn") {
      if (event.entry) applyMultiplayerRifleTrapSnapshot([event.entry], false);
      return { sound: null, visuals: event.entry ? 1 : 0 };
    }
    if (event.type === "acidPuddleSpawn") {
      if (event.entry) applyMultiplayerAcidPuddleSnapshot([event.entry], false);
      return { sound: null, visuals: event.entry ? 1 : 0 };
    }
    if (event.type === "hazardRemove") return applyGuestHazardRemoveEvent(event);
    if (event.type === "coachGunVolley") return applyGuestCoachGunVolleyEvent(event);
    if (event.type === "launcherExplosion") return applyGuestLauncherExplosionEvent(event);
    if (event.type === "rifleTrapTrigger") return applyGuestRifleTrapTriggerEvent(event);
    if (event.type === "rifleLightning") return applyGuestRifleLightningEvent(event);
    if (event.type === "bellRingerBellDrop") return applyGuestBellRingerBellDropEvent(event);
    if (event.type === "oilBaronStarImpact") return applyGuestOilBaronStarImpactEvent(event);
    if (event.type === "oilBaronMonocleLaunch") return applyGuestOilBaronMonocleLaunchEvent(event);
    if (event.type === "oilBaronMonocleImpact") return applyGuestOilBaronMonocleImpactEvent(event);
    if (event.type === "xpOrb") {
      spawnMultiplayerXpVisual(Number(event.x) || 0, Number(event.z) || 0, event.value, event.ownerId);
      return { sound: null, visuals: 1 };
    }
    return null;
  }

  function applyGuestOilBaronStarImpactEvent(event) {
    var x = Number(event && event.x);
    var z = Number(event && event.z);
    var jumpIndex = clamp(Math.floor(Number(event && event.jumpIndex) || 0), 0, OIL_BARON_STAR_JUMP_COUNT - 1);
    if (!Number.isFinite(x) || !Number.isFinite(z)) return { sound: null, visuals: 0 };
    var encounter = state.oilBaron;
    if (!encounter || !encounter.replica || encounter.defeated) return { sound: null, visuals: 0 };
    var sourceId = String(event && event.sourceId || "oil-baron");
    var sourceDouble = sourceId !== "oil-baron" ? findOilBaronDoubleByNetworkId(sourceId) : null;
    emitOilBaronStarBounceAudio(sourceDouble && sourceDouble.actorContext || encounter, x, z, jumpIndex, false);
    addShockwave(x, z, OIL_BARON_STAR_LANDING_RADIUS + 1.4, 0.52, 0x050607);
    addShockwave(x, z, OIL_BARON_STAR_LANDING_RADIUS, 0.38, 0xffa83b);
    addLightFlash(x, 1.4, z, 0xff9c31, 5.6, 13, 0.25);
    return { sound: "oilBaronBounce", visuals: 3 };
  }

  function applyGuestOilBaronMonocleLaunchEvent(event) {
    var encounter = state.oilBaron;
    var x = Number(event && event.x);
    var y = Number(event && event.y);
    var z = Number(event && event.z);
    if (!encounter || !encounter.replica || encounter.defeated || !Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(z)) {
      return { sound: null, visuals: 0 };
    }
    emitOilBaronMonocleLaunch({
      id: String(event && event.projectileId || ""),
      x: x,
      y: y,
      z: z,
      dirX: Number(event && event.dirX) || 0,
      dirZ: Number.isFinite(Number(event && event.dirZ)) ? Number(event.dirZ) : 1,
    }, false);
    return { sound: "oilBaronMonocleLaunch", visuals: 1 };
  }

  function applyGuestOilBaronMonocleImpactEvent(event) {
    var encounter = state.oilBaron;
    var x = Number(event && event.x);
    var y = Number(event && event.y);
    var z = Number(event && event.z);
    if (!encounter || !encounter.replica || !Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(z)) {
      return { sound: null, visuals: 0 };
    }
    emitOilBaronMonocleImpact({
      id: String(event && event.projectileId || ""),
      x: x,
      y: y,
      z: z,
    }, event && event.hitPlayer ? {} : null, false);
    return { sound: "oilBaronMonocleImpact", visuals: 3 };
  }

  function applyGuestBellRingerBellDropEvent(event) {
    var encounter = state.bellRinger;
    if (!encounter || !encounter.replica || !encounter.active) return { sound: null, visuals: 0 };
    var drops = Array.isArray(event && event.drops) ? event.drops.slice(0, 8) : [];
    var warning = clamp(Number(event && event.warning) || BELL_RINGER_BELL_DROP_WARNING, 1.2, 5);
    var bossSequence = Math.max(0, Math.floor(Number(event && event.bossSequence) || 0));
    var visuals = 0;
    for (var i = 0; i < drops.length; i++) {
      var source = drops[i];
      if (!source || !Number.isFinite(Number(source.x)) || !Number.isFinite(Number(source.z))) continue;
      var spec = {
        id: String(source.id || (bossSequence + "-" + i)),
        targetPlayerId: String(source.targetPlayerId || ""),
        x: Number(source.x),
        z: Number(source.z),
      };
      if (spawnBellRingerBellDrop(encounter, spec, true, warning)) visuals += 1;
    }
    encounter.bellDropSequence = Math.max(encounter.bellDropSequence || 0, bossSequence);
    return { sound: null, visuals: visuals };
  }

  function applyGuestHazardRemoveEvent(event) {
    var key = String(event.hazardId == null ? "" : event.hazardId);
    var kind = String(event.kind || "");
    if (kind === "fire") {
      var fire = multiplayerState.guestFirePatchMap[key];
      if (fire) {
        removeHazardSpatialEntry(guestFirePatchSpatialIndex, fire);
        detachFirePatchVisual(fire);
      }
      delete multiplayerState.guestFirePatchMap[key];
      var fallbackGround = getCurrentVisibleGroundRect();
      syncFireFallbackVisuals(queryLocallyRelevantFirePatches(guestFirePatchSpatialIndex, fallbackGround, []), fallbackGround);
    } else if (kind === "trap") {
      var trap = multiplayerState.guestRifleTrapMap[key];
      if (trap && trap.visual) releaseRifleTrapVisual(trap.visual);
      delete multiplayerState.guestRifleTrapMap[key];
    } else if (kind === "acid") {
      var puddle = multiplayerState.guestAcidPuddleMap[key];
      if (puddle && puddle.visual) releaseAcidPuddleVisual(puddle.visual);
      delete multiplayerState.guestAcidPuddleMap[key];
    }
    return { sound: null, visuals: 1 };
  }

  function getGuestProjectileEntryFromEvent(event, atImpact) {
    var startX = Number(event.startX) || 0;
    var startY = Number(event.startY) || 0.9;
    var startZ = Number(event.startZ) || 0;
    return {
      id: event.projectileId,
      ownerId: event.ownerId || "",
      clientFireSequence: Math.max(0, Math.floor(Number(event.clientFireSequence) || 0)),
      type: String(event.projectileType || "revolver"),
      x: atImpact ? getFiniteMultiplayerNumber(event.impactX, startX) : getFiniteMultiplayerNumber(event.x, startX),
      y: atImpact ? getFiniteMultiplayerNumber(event.impactY, startY) : getFiniteMultiplayerNumber(event.y, startY),
      z: atImpact ? getFiniteMultiplayerNumber(event.impactZ, startZ) : getFiniteMultiplayerNumber(event.z, startZ),
      startX: startX,
      startY: startY,
      startZ: startZ,
      dirX: Number(event.dirX) || 0,
      dirZ: getFiniteMultiplayerNumber(event.dirZ, 1),
      speed: Math.max(0, Number(event.speed) || 0),
      life: Math.max(0.12, Number(event.life) || 0.12),
      hitRadius: Math.max(0.01, Number(event.hitRadius) || 0.1),
      visualWidth: Math.max(0.04, Number(event.visualWidth) || 0.1),
      visualLength: Math.max(0.12, Number(event.visualLength) || 0.5),
      chainLightning: !!event.chainLightning,
      piercing: !!event.piercing,
      minimumVisibleMs: Math.max(MULTIPLAYER_PROJECTILE_MIN_VISIBLE_MS, Number(event.minimumVisibleMs) || 0),
    };
  }

  function applyGuestProjectileSpawnEvent(event) {
    if (event.projectileId == null) return null;
    if (multiplayerState.guestProjectileTombstones[String(event.projectileId)]) return { sound: null, visuals: 0 };
    applyMultiplayerBulletSnapshot([getGuestProjectileEntryFromEvent(event, false)], false);
    return { sound: null, visuals: 1 };
  }

  function finishGuestProjectileEvent(event, showImpact) {
    if (!event || event.projectileId == null) return null;
    var key = String(event.projectileId);
    multiplayerState.guestProjectileTombstones[key] = performance.now();
    var bullet = multiplayerState.guestBulletMap[key];
    if (bullet) removeGuestMultiplayerBullet(key, bullet);
    var clientFireSequence = Math.max(0, Math.floor(Number(event.clientFireSequence) || 0));
    if (clientFireSequence) {
      Object.keys(multiplayerState.guestBulletMap).forEach(function (replicaKey) {
        var replica = multiplayerState.guestBulletMap[replicaKey];
        if (
          replica && replica.ownerPlayerId === String(event.ownerId || "") &&
          Math.max(0, Math.floor(Number(replica.clientFireSequence) || 0)) === clientFireSequence
        ) removeGuestMultiplayerBullet(replicaKey, replica);
      });
    }
    if (event.ownerId === multiplayerState.localPlayerId && clientFireSequence) {
      delete multiplayerState.guestPredictedShotRecords[String(clientFireSequence)];
    }
    var impactX = getFiniteMultiplayerNumber(event.impactX, Number(event.x) || Number(event.startX) || 0);
    var impactZ = getFiniteMultiplayerNumber(event.impactZ, Number(event.z) || Number(event.startZ) || 0);
    var impactVisible = showImpact && !pointOutsideVisibleGround(
      impactX,
      impactZ,
      1.5,
      getCurrentVisibleGroundRect(combatEffectVisibleGroundScratch)
    );
    if (impactVisible) {
      addHitSpark(
        impactX,
        impactZ
      );
    }
    return { sound: null, visuals: impactVisible ? 1 : 0 };
  }

  function applyGuestProjectileDespawnEvent(event) {
    return finishGuestProjectileEvent(event, false);
  }

  function applyGuestProjectileDespawnBatchEvent(event) {
    var projectiles = Array.isArray(event && event.projectiles) ? event.projectiles : [];
    for (var i = 0; i < projectiles.length; i++) finishGuestProjectileEvent(projectiles[i], false);
    return { sound: null, visuals: 0 };
  }

  function applyGuestProjectileImpactEvent(event) {
    return finishGuestProjectileEvent(event, true);
  }

  function applyGuestRifleLightningEvent(event) {
    var path = Array.isArray(event.path) ? event.path : [];
    if (path.length < 4) return null;
    var segmentCount = Math.min(MAX_LIGHTNING_BOLTS, Math.floor(path.length / 2) - 1);
    var visuals = 0;
    var visibleGround = getCurrentVisibleGroundRect(combatEffectVisibleGroundScratch);
    for (var i = 0; i < segmentCount; i++) {
      var offset = i * 2;
      var x1 = Number(path[offset]) || 0;
      var z1 = Number(path[offset + 1]) || 0;
      var x2 = Number(path[offset + 2]) || 0;
      var z2 = Number(path[offset + 3]) || 0;
      if (addLightningBolt(x1, z1, x2, z2)) visuals += 1;
      playLightningChainSound(x1, z1, x2, z2, i, segmentCount);
      if (i === 0 && !pointOutsideVisibleGround(x2, z2, 2.4, visibleGround)) {
        addLightFlash(x2, 1.45, z2, 0x86f3ff, 3.4, 8.5, 0.18);
        addShockwave(x2, z2, 1.8, 0.28, 0x86f3ff);
      }
    }
    return { sound: "rifleLightning", visuals: visuals };
  }

  function applyGuestCoachGunVolleyEvent(event) {
    var startX = Number(event.startX) || 0;
    var startZ = Number(event.startZ) || 0;
    var dirX = Number(event.dirX) || 0;
    var dirZ = getFiniteMultiplayerNumber(event.dirZ, 1);
    var dirLength = Math.hypot(dirX, dirZ) || 1;
    dirX /= dirLength;
    dirZ /= dirLength;
    var variant = String(event.variant || "standard");
    var grave = variant === "graveWarden";
    var breach = variant === "breachMarshal";
    var speed = grave ? 56 : breach ? 46 : 50;
    var width = grave ? 0.09 : breach ? 0.115 : 0.1;
    var length = grave ? 1.05 : breach ? 0.72 : 0.78;
    var material = grave ? mats.rifleTracer : mats.coachTracer;
    var rays = Array.isArray(event.visualRays) ? event.visualRays : [];
    var tracerCount = Math.min(24, Math.floor(rays.length / 4));
    var visibleGround = getCurrentVisibleGroundRect(combatEffectVisibleGroundScratch);
    var visibleTracerCount = 0;
    for (var visibleIndex = 0; visibleIndex < tracerCount; visibleIndex++) {
      var visibleOffset = visibleIndex * 4;
      var visibleRayX = Number(rays[visibleOffset]) || dirX;
      var visibleRayZ = Number(rays[visibleOffset + 1]) || dirZ;
      var visibleRayDistance = clamp(Number(rays[visibleOffset + 2]) || 0.1, 0.1, 64);
      if (!segmentOutsideVisibleGround(
        startX,
        startZ,
        startX + visibleRayX * visibleRayDistance,
        startZ + visibleRayZ * visibleRayDistance,
        1.4,
        visibleGround
      )) visibleTracerCount += 1;
    }
    reserveCoachGunTracerSlots(visibleTracerCount);
    for (var i = 0; i < tracerCount; i++) {
      var offset = i * 4;
      var rayX = Number(rays[offset]) || dirX;
      var rayZ = Number(rays[offset + 1]) || dirZ;
      var rayDistance = clamp(Number(rays[offset + 2]) || 0.1, 0.1, 64);
      if (segmentOutsideVisibleGround(startX, startZ, startX + rayX * rayDistance, startZ + rayZ * rayDistance, 1.4, visibleGround)) continue;
      var ball = Number(rays[offset + 3]) === 1;
      spawnCoachGunTracer(
        startX,
        WEAPONS.coachGun.muzzleY,
        startZ,
        rayX,
        rayZ,
        rayDistance,
        ball ? speed * 1.08 : speed,
        ball ? width * 1.5 : width,
        ball ? length * 1.35 : length,
        material,
        ball
      );
    }
    var start = { x: startX, y: WEAPONS.coachGun.muzzleY, z: startZ };
    var clientFireSequence = Math.max(0, Math.floor(Number(event.clientFireSequence) || 0));
    var predictedRecord = getGuestPredictedShotRecord(event.ownerId || "", "coachGun", clientFireSequence);
    var locallyPredicted = event.ownerId === multiplayerState.localPlayerId && (
      !!predictedRecord || (!clientFireSequence &&
        multiplayerState.guestPredictedShotType === "coachGun" &&
        performance.now() - (multiplayerState.guestPredictedShotAt || 0) <= 350)
    );
    var muzzleVisible = !pointOutsideVisibleGround(startX, startZ, 2, visibleGround);
    var muzzleParticleCount = locallyPredicted || !muzzleVisible ? 0 : 9;
    if (locallyPredicted) {
      if (predictedRecord) delete multiplayerState.guestPredictedShotRecords[String(clientFireSequence)];
      multiplayerState.guestPredictedShotType = "";
      multiplayerState.guestPredictedShotAt = 0;
    } else {
      if (muzzleVisible) {
        addLightFlash(startX, start.y, startZ, grave ? 0xffefbd : 0xffb057, 2.5, 6.4, 0.12);
        addSmokePuff(startX - dirX * 0.16, start.y, startZ - dirZ * 0.16, 0.48, 0.42);
      }
      playCoachGunShotSound(start, { x: dirX, z: dirZ }, !!event.lastShell);
      reserveParticleSlots(muzzleParticleCount);
      for (var particleIndex = 0; particleIndex < muzzleParticleCount; particleIndex++) {
        spawnParticle(
          start.x + rand(-0.1, 0.1),
          start.y + rand(-0.08, 0.08),
          start.z + rand(-0.1, 0.1),
          dirX * rand(3.8, 7.4) + rand(-2.3, 2.3),
          rand(0.7, 2.7),
          dirZ * rand(3.8, 7.4) + rand(-2.3, 2.3),
          rand(0.1, 0.2),
          rand(0.06, 0.14),
          particleIndex % 3 ? mats.coachTracer : mats.flash,
          true
        );
      }
    }
    return { sound: locallyPredicted ? null : "coachGun", visuals: visibleTracerCount + muzzleParticleCount + (!locallyPredicted && muzzleVisible ? 2 : 0) };
  }

  function applyGuestLauncherExplosionEvent(event) {
    var x = Number(event.x) || 0;
    var z = Number(event.z) || 0;
    var radius = clamp(Number(event.radius) || 1, 0.2, 12);
    var kind = String(event.kind || "main");
    var chain = kind === "chain";
    var emitVisuals = !pointOutsideVisibleGround(
      x,
      z,
      radius + 2,
      getCurrentVisibleGroundRect(combatEffectVisibleGroundScratch)
    );
    var smokeCount = kind === "cluster" ? 7 : 12;
    var particleCount = kind === "cluster" ? 22 : 34;
    if (emitVisuals) {
      addShockwave(x, z, radius, chain ? 0.38 : 0.5, chain ? 0xffb347 : 0xffe0a0);
      addScorchMark(x, z, radius * 0.62);
      addLightFlash(x, 1.2, z, chain ? 0xffb347 : 0xff7a22, chain ? 4.6 : 5.8, 12, 0.28);
      reserveSmokePuffSlots(smokeCount);
      for (var i = 0; i < smokeCount; i++) {
        addSmokePuff(x + rand(-0.8, 0.8), rand(0.45, 1.25), z + rand(-0.8, 0.8), rand(0.48, 0.95), rand(0.55, 1.05), true);
      }
      reserveParticleSlots(particleCount);
      for (var particleIndex = 0; particleIndex < particleCount; particleIndex++) {
        var angle = rand(0, Math.PI * 2);
        var speed = rand(1.4, kind === "cluster" ? 5.4 : 7.2);
        spawnParticle(
          x + Math.cos(angle) * rand(0, 0.5),
          rand(0.35, 1.35),
          z + Math.sin(angle) * rand(0, 0.5),
          Math.cos(angle) * speed,
          rand(1.2, 5.2),
          Math.sin(angle) * speed,
          rand(0.28, 0.58),
          rand(0.12, 0.38),
          particleIndex % 4 === 0 ? mats.flash : mats.explosion,
          true
        );
      }
    }
    var sound = null;
    if (event.audio !== false) {
      playLauncherExplosionSound(x, z, radius, kind);
      sound = "launcherExplosion";
    }
    return { sound: sound, visuals: emitVisuals ? smokeCount + particleCount + 3 : 0 };
  }

  function removeGuestRifleTrapReplicaById(trapId) {
    var trapKey = String(trapId == null ? "" : trapId);
    var trapReplica = multiplayerState.guestRifleTrapMap[trapKey];
    if (!trapReplica) return false;
    if (trapReplica.visual) releaseRifleTrapVisual(trapReplica.visual);
    delete multiplayerState.guestRifleTrapMap[trapKey];
    return true;
  }

  function applyGuestRifleTrapTriggerVisual(event) {
    var x = Number(event.x) || 0;
    var z = Number(event.z) || 0;
    var radius = clamp(Number(event.radius) || RIFLE_TRAP_BASE_BLAST_RADIUS, 0.2, 12);
    var color = event.lure ? 0xffd36b : 0xffb35f;
    var particleCount = 18;
    var emitVisuals = !pointOutsideVisibleGround(
      x,
      z,
      radius + TRAP_VISUAL_CULL_PAD,
      getCurrentVisibleGroundRect(combatEffectVisibleGroundScratch)
    );
    if (emitVisuals) {
      addShockwave(x, z, radius, 0.36, color);
      addLightFlash(x, 0.9, z, color, 3.2, 7, 0.2);
      reserveParticleSlots(particleCount);
      for (var i = 0; i < particleCount; i++) {
        var angle = rand(0, Math.PI * 2);
        spawnParticle(x, rand(0.25, 1.1), z, Math.cos(angle) * rand(1.4, 5), rand(0.8, 3.6), Math.sin(angle) * rand(1.4, 5), rand(0.18, 0.36), rand(0.055, 0.13), i % 2 ? mats.trapMetal : mats.flash, true);
      }
    }
    removeGuestRifleTrapReplicaById(event.trapId);
    return { sound: null, visuals: emitVisuals ? particleCount + 2 : 0 };
  }

  function applyGuestRifleTrapTriggerEvent(event) {
    if (Object.prototype.hasOwnProperty.call(event || {}, "v") || Object.prototype.hasOwnProperty.call(event || {}, "r")) {
      var visibleEntries = decodeMultiplayerRifleTrapTriggerEntries(event.v);
      var removalIds = decodeMultiplayerRifleTrapRemovalIds(event.r);
      if (!Array.isArray(visibleEntries) || !Array.isArray(removalIds)) return null;
      var visuals = 0;
      for (var i = 0; i < visibleEntries.length; i++) {
        visuals += applyGuestRifleTrapTriggerVisual(visibleEntries[i]).visuals;
      }
      for (var removalIndex = 0; removalIndex < removalIds.length; removalIndex++) {
        removeGuestRifleTrapReplicaById(removalIds[removalIndex]);
      }
      return { sound: null, visuals: visuals };
    }
    return applyGuestRifleTrapTriggerVisual(event || {});
  }

  function applyGuestProjectileSpawnEffects(entry, bullet, start) {
    var type = String(bullet.type || "revolver");
    var dir = { x: bullet.dirX, z: bullet.dirZ };
    var sound = null;
    var emitVisuals = !pointOutsideVisibleGround(
      start.x,
      start.z,
      2,
      getCurrentVisibleGroundRect(combatEffectVisibleGroundScratch)
    );
    if (type === "revolver") {
      if (emitVisuals) {
        addLightFlash(start.x, start.y, start.z, 0xffd36b, 1.7, 5, 0.08);
        addSmokePuff(start.x - bullet.dirX * 0.18, start.y, start.z - bullet.dirZ * 0.18, 0.28, 0.28);
      }
      playRevolverShotSound(start, dir, 0, false);
      sound = "revolver";
    } else if (type === "rifle") {
      if (emitVisuals) {
        addLightFlash(start.x, start.y, start.z, 0xffd36b, 1.7, 5, 0.08);
        addSmokePuff(start.x - bullet.dirX * 0.18, start.y, start.z - bullet.dirZ * 0.18, 0.28, 0.28);
      }
      playRifleShotSound(start, dir, !!entry.chainLightning);
      sound = "rifle";
    } else if (type === "launcher") {
      if (emitVisuals) {
        addLightFlash(start.x, start.y, start.z, 0xff7a24, 3.2, 8, 0.16);
        addSmokePuff(start.x - bullet.dirX * 0.18, start.y, start.z - bullet.dirZ * 0.18, 0.55, 0.48);
      }
      playLauncherLaunchSound(start, dir);
      sound = "launcher";
    }
    multiplayerState.guestProjectileSoundLog.push({
      id: entry.id,
      type: type,
      sound: sound,
    });
    if (multiplayerState.guestProjectileSoundLog.length > MULTIPLAYER_COMBAT_EVENT_HISTORY * 2) {
      multiplayerState.guestProjectileSoundLog.splice(0, multiplayerState.guestProjectileSoundLog.length - MULTIPLAYER_COMBAT_EVENT_HISTORY * 2);
    }
  }

  function getGuestProjectileVisualKind(type, chainLightning) {
    if (type === "launcher") return "launcher";
    if (type === "launcherFireShard") return "fireShard";
    if (type === "rifle" && chainLightning) return "electric";
    return "standard";
  }

  function createGuestProjectileVisual(type, start, angle, size, chainLightning) {
    if (type === "launcherFireShard") return createLauncherFireShardMesh(start.x, start.z, angle);
    var weapon = type === "launcherShrapnel"
      ? WEAPONS.revolver
      : WEAPONS[type] || (type.indexOf("launcher") === 0 ? WEAPONS.launcher : WEAPONS.revolver);
    return createProjectileMesh(weapon, start, angle, size, { electric: type === "rifle" && !!chainLightning });
  }

  function reconcileGuestProjectileVisual(bullet, type, size, chainLightning) {
    if (!bullet) return;
    var expectedKind = getGuestProjectileVisualKind(type, chainLightning);
    var currentKind = bullet.visual && bullet.visual.kind || "";
    if (!bullet.mesh || currentKind !== expectedKind) {
      var start = { x: bullet.x, y: bullet.y, z: bullet.z };
      if (bullet.visual) releaseProjectileVisual(bullet.visual);
      else if (bullet.mesh) removeObject3D(bullet.mesh);
      bullet.mesh = createGuestProjectileVisual(type, start, Math.atan2(bullet.dirX || 0, getFiniteMultiplayerNumber(bullet.dirZ, 1)), size, chainLightning);
      bullet.visual = getProjectileVisualForObject(bullet.mesh);
      return;
    }
    if (currentKind === "standard") {
      bullet.mesh.scale.set(size.width, size.width, size.length);
      syncStandardProjectileVisual(bullet.visual);
    }
  }

  function applyMultiplayerBulletSnapshot(entries, reconcileMissing, snapshotTime) {
    var seen = Object.create(null);
    var receivedAt = performance.now();
    var authoritativeSampleTime = Number(snapshotTime);
    var hasAuthoritativeSampleTime = Number.isFinite(authoritativeSampleTime);
    for (var i = 0; i < entries.length; i++) {
      var entry = entries[i];
      var key = String(entry.id);
      if (multiplayerState.guestProjectileTombstones[key]) {
        if (multiplayerState.guestBulletMap[key]) removeGuestMultiplayerBullet(key, multiplayerState.guestBulletMap[key]);
        continue;
      }
      var remainingLife = Math.max(0, Number(entry.life) || 0);
      if (remainingLife <= 0.001) {
        if (multiplayerState.guestBulletMap[key]) removeGuestMultiplayerBullet(key, multiplayerState.guestBulletMap[key]);
        continue;
      }
      seen[key] = true;
      var bullet = multiplayerState.guestBulletMap[key];
      var created = false;
      if (!bullet) {
        var start = {
          x: Number.isFinite(Number(entry.startX)) ? Number(entry.startX) : Number(entry.x) || 0,
          y: Number.isFinite(Number(entry.startY)) ? Number(entry.startY) : Number(entry.y) || 1,
          z: Number.isFinite(Number(entry.startZ)) ? Number(entry.startZ) : Number(entry.z) || 0,
        };
        var projectileType = String(entry.type || "revolver");
        var clientFireSequence = Math.max(0, Math.floor(Number(entry.clientFireSequence) || 0));
        var projectileWeapon = projectileType === "launcherShrapnel"
          ? WEAPONS.revolver
          : WEAPONS[projectileType] || (projectileType.indexOf("launcher") === 0 ? WEAPONS.launcher : WEAPONS.revolver);
        var entrySpeed = Math.max(0, Number(entry.speed) || projectileWeapon.speed);
        var sampleDistance = Math.hypot(
          (Number(entry.x) || 0) - start.x,
          (Number(entry.z) || 0) - start.z
        );
        var projectileSampleAge = entrySpeed > 0.001 ? sampleDistance / entrySpeed : 0;
        var projectileArcMaxLife = Math.max(0.05, projectileSampleAge + remainingLife);
        var predictionRecord = getGuestPredictedShotRecord(entry.ownerId || "", projectileType, clientFireSequence);
        bullet = takePredictedMultiplayerProjectile(entry.ownerId || "", projectileType, clientFireSequence);
        var adoptedPrediction = !!bullet;
        var locallyPredictedShot = adoptedPrediction || !!predictionRecord;
        if (adoptedPrediction) {
          bullet.networkId = entry.id;
          bullet.networkLocallyPredicted = true;
          bullet.ownerPlayerId = entry.ownerId || "";
          bullet.type = projectileType;
          bullet.speed = entrySpeed;
        } else {
          var size = {
            width: Math.max(0.04, Number(entry.visualWidth) || getWeaponProjectileVisualSize(projectileWeapon, false).width),
            length: Math.max(0.12, Number(entry.visualLength) || getWeaponProjectileVisualSize(projectileWeapon, false).length),
          };
          var mesh = createGuestProjectileVisual(projectileType, start, Math.atan2(Number(entry.dirX) || 0, getFiniteMultiplayerNumber(entry.dirZ, 1)), size, !!entry.chainLightning);
          bullet = {
            networkId: entry.id,
            ownerPlayerId: entry.ownerId || "",
            type: projectileType,
            x: start.x,
            y: start.y,
            z: start.z,
            dirX: Number(entry.dirX) || 0,
            dirZ: getFiniteMultiplayerNumber(entry.dirZ, 1),
            speed: entrySpeed,
            life: remainingLife,
            maxLife: projectileArcMaxLife,
            age: projectileSampleAge,
            hitRadius: Math.max(0.01, Number(entry.hitRadius) || projectileWeapon.hitRadius || 0.1),
            networkLocallyPredicted: locallyPredictedShot,
            visual: getProjectileVisualForObject(mesh),
            mesh: mesh,
          };
          created = true;
          state.bullets.push(bullet);
        }
        bullet.clientFireSequence = clientFireSequence;
        multiplayerState.guestBulletMap[key] = bullet;
        if (predictionRecord) predictionRecord.bulletKey = key;
        if (!locallyPredictedShot) applyGuestProjectileSpawnEffects(entry, bullet, start);
        var owner = getMultiplayerPlayer(bullet.ownerPlayerId);
        if (!locallyPredictedShot && owner && owner.entity && !owner.local) {
          var kick = projectileType === "launcher" ? 1 : projectileType === "rifle" ? 0.72 : 0.55;
          owner.entity.shootKick = Math.max(owner.entity.shootKick || 0, kick);
        }
      }
      bullet.networkTargetX = Number(entry.x) || 0;
      bullet.networkTargetY = Number(entry.y) || 1;
      bullet.networkTargetZ = Number(entry.z) || 0;
      bullet.networkTargetAt = receivedAt;
      bullet.networkTargetSampleTime = hasAuthoritativeSampleTime ? authoritativeSampleTime : null;
      bullet.networkSampleLead = hasAuthoritativeSampleTime
        ? clamp(state.time - authoritativeSampleTime, 0, MULTIPLAYER_PROJECTILE_SAMPLE_LEAD_MAX)
        : 0;
      bullet.dirX = Number(entry.dirX) || 0;
      bullet.dirZ = getFiniteMultiplayerNumber(entry.dirZ, 1);
      bullet.type = String(entry.type || bullet.type || "revolver");
      if (Number.isFinite(Number(entry.speed)) && Number(entry.speed) >= 0) bullet.speed = Number(entry.speed);
      bullet.clientFireSequence = Math.max(0, Math.floor(Number(entry.clientFireSequence) || bullet.clientFireSequence || 0));
      bullet.hitRadius = Math.max(0.01, Number(entry.hitRadius) || bullet.hitRadius || 0.1);
      bullet.visualWidth = Math.max(0.04, Number(entry.visualWidth) || bullet.visualWidth || 0.1);
      bullet.visualLength = Math.max(0.12, Number(entry.visualLength) || bullet.visualLength || 0.5);
      bullet.chainLightning = !!entry.chainLightning;
      bullet.piercing = !!entry.piercing;
      if (bullet.type === "launcher") {
        var launcherSpeed = Math.max(0.001, Number(bullet.speed) || WEAPONS.launcher.speed);
        var launcherStartX = Number.isFinite(Number(entry.startX)) ? Number(entry.startX) : bullet.x;
        var launcherStartZ = Number.isFinite(Number(entry.startZ)) ? Number(entry.startZ) : bullet.z;
        var launcherSampleAge = Math.hypot(
          bullet.networkTargetX - launcherStartX,
          bullet.networkTargetZ - launcherStartZ
        ) / launcherSpeed;
        var launcherMaxLife = Math.max(0.05, launcherSampleAge + remainingLife);
        bullet.networkArcSampleAge = launcherSampleAge;
        bullet.networkArcMaxLife = launcherMaxLife;
        if (!Number.isFinite(Number(bullet.age))) bullet.age = launcherSampleAge;
        if (created) bullet.age = launcherSampleAge;
        bullet.maxLife = launcherMaxLife;
      }
      reconcileGuestProjectileVisual(bullet, String(entry.type || bullet.type || "revolver"), {
        width: bullet.visualWidth,
        length: bullet.visualLength,
      }, bullet.chainLightning);
      bullet.mesh.rotation.y = Math.atan2(bullet.dirX, bullet.dirZ);
      bullet.life = remainingLife;
      if (entry.minimumVisibleMs) {
        bullet.networkMinimumVisibleUntil = Math.max(
          bullet.networkMinimumVisibleUntil || 0,
          receivedAt + Math.max(MULTIPLAYER_PROJECTILE_MIN_VISIBLE_MS, Number(entry.minimumVisibleMs) || 0)
        );
      }
      bullet.networkExpiresAt = state.time + Math.max(
        0,
        remainingLife - (Number(bullet.networkSampleLead) || 0)
      ) + MULTIPLAYER_GUEST_BULLET_EXPIRY_GRACE;
      var recoverFromVisualContact = false;
      if (bullet.networkVisualContactAt) {
        var contactKind = String(bullet.networkVisualContactKind || "enemy");
        var contactTarget = null;
        if (contactKind === "enemy") {
          contactTarget = multiplayerState.guestEnemyMap[String(bullet.networkVisualContactEnemyId || "")];
          if (!contactTarget) contactTarget = findActiveBossDamageTargetByNetworkId(bullet.networkVisualContactEnemyId);
        } else if (contactKind === "player") {
          var contactPlayer = getMultiplayerPlayer(bullet.networkVisualContactPlayerId || "");
          contactTarget = contactPlayer && contactPlayer.entity;
        }
        if (contactKind === "world") {
          recoverFromVisualContact = Math.hypot(
            bullet.networkTargetX - (bullet.networkVisualContactX || bullet.x),
            bullet.networkTargetZ - (bullet.networkVisualContactZ || bullet.z)
          ) > 1.25;
        } else {
          var clearDistance = (contactTarget && contactTarget.radius || 0.75) + (bullet.hitRadius || 0.1) + 1.1;
          recoverFromVisualContact = !contactTarget || Math.hypot(
            bullet.networkTargetX - contactTarget.x,
            bullet.networkTargetZ - contactTarget.z
          ) > clearDistance;
        }
      }
      if (recoverFromVisualContact) {
        bullet.networkVisualContactAt = 0;
        bullet.networkVisualContactKind = "";
        bullet.networkVisualContactEnemyId = 0;
        bullet.networkVisualContactPlayerId = "";
        bullet.networkVisualContactX = 0;
        bullet.networkVisualContactZ = 0;
        bullet.mesh.visible = true;
      }
      if (created || recoverFromVisualContact || Math.hypot(bullet.networkTargetX - bullet.x, bullet.networkTargetZ - bullet.z) > MULTIPLAYER_INTERPOLATION_TELEPORT_DISTANCE) {
        bullet.x = bullet.networkTargetX;
        bullet.y = bullet.networkTargetY;
        bullet.z = bullet.networkTargetZ;
      }
      bullet.mesh.position.set(bullet.x, bullet.y, bullet.z);
      syncStandardProjectileVisual(bullet.visual);
    }
    if (reconcileMissing !== false) {
      Object.keys(multiplayerState.guestBulletMap).forEach(function (key) {
        if (seen[key]) return;
        var bullet = multiplayerState.guestBulletMap[key];
        if (bullet && bullet.networkPredicted) {
          var record = getGuestPredictedShotRecord(bullet.ownerPlayerId || "", bullet.type || "revolver", bullet.clientFireSequence);
          if (isLocalFireActionPending(bullet.ownerPlayerId, bullet.clientFireSequence) || record && record.result === "accepted") return;
        }
        removeGuestMultiplayerBullet(key, bullet);
      });
    }
  }

  function removeGuestMultiplayerBullet(key, bullet) {
    var replica = bullet || multiplayerState.guestBulletMap[key];
    if (replica) {
      var record = getGuestPredictedShotRecord(
        replica.ownerPlayerId || "",
        replica.type || "revolver",
        replica.clientFireSequence
      );
      if (record && record.bulletKey === String(key)) record.bulletKey = "";
      var index = state.bullets.indexOf(replica);
      if (index !== -1) removeBullet(index);
      else if (replica.visual) releaseProjectileVisual(replica.visual);
      else if (replica.mesh) removeObject3D(replica.mesh);
    }
    delete multiplayerState.guestBulletMap[key];
  }

  function startGame() {
    if (multiplayerState.active) {
      stopNearbyConnections(false);
      releaseMultiplayerPlayerEntities();
      resetMultiplayerSessionState();
      if (multiplayerLobby) setPanel(multiplayerLobby, false);
      if (multiplayerDeathPanel) setPanel(multiplayerDeathPanel, false);
      if (multiplayerResultPanel) setPanel(multiplayerResultPanel, false);
      if (multiplayerScoreboard) {
        multiplayerScoreboard.classList.remove("is-open");
        multiplayerScoreboard.hidden = true;
      }
      if (multiplayerScoreboardToggle) multiplayerScoreboardToggle.hidden = true;
    }
    if (ammoHud) ammoHud.hidden = false;
    lockLandscapeIfPossible();
    resetRun("playing");
    warmupGameplayEffectResources();
    warmupLauncherExplosionAudioGraph();
    if (isRifleListenSceneRequested()) setupRifleListenScene();
    setPanel(menu, false);
    setPanel(gameOverPanel, false);
    setPanel(revolverUpgradePanel, false);
    setPanel(rifleUpgradePanel, false);
    setPanel(launcherUpgradePanel, false);
    setPanel(marshalUpgradePanel, false);
    setPanel(levelUpPanel, false);
    updateModeClass();
  }

  function canOpenPauseMenu() {
    return state.mode === "playing" && !isIntroActive() && !(multiplayerState.active && multiplayerState.phase === "match");
  }

  function clearActiveInput() {
    pointerDown = false;
    Object.keys(keys).forEach(function (code) {
      keys[code] = false;
    });
    resetTouchControls();
  }

  function showPauseMenuView(view) {
    var showSettings = view === "settings";
    if (pauseMainPanel) pauseMainPanel.classList.toggle("is-visible", !showSettings);
    if (pauseSettingsPanel) pauseSettingsPanel.classList.toggle("is-visible", showSettings);
    if (showSettings) updatePauseVolumeControls();
  }

  function syncPauseMenuUi() {
    var open = !!state.paused;
    if (pauseMenu) {
      pauseMenu.classList.toggle("is-visible", open);
      pauseMenu.setAttribute("aria-hidden", open ? "false" : "true");
    }
    if (pauseMenuBtn) pauseMenuBtn.setAttribute("aria-expanded", open ? "true" : "false");
    updateModeClass();
  }

  function setPauseMenuOpen(open) {
    var shouldOpen = !!open && canOpenPauseMenu();
    if (!shouldOpen && controlLayoutState.editing) finishControlLayoutEdit(false);
    state.paused = shouldOpen;
    clearActiveInput();
    if (shouldOpen) {
      showPauseMenuView("main");
      updatePauseVolumeControls();
    }
    syncPauseMenuUi();
  }

  function exitToMainMenu() {
    setPauseMenuOpen(false);
    resetRun("menu");
    updateModeClass();
  }

  function setupEnemyBestiaryPreview(variant) {
    resetRun("playing");
    setIntroActive(false);
    releaseAllEnemiesToPool();
    state.spawnLeft = 0;
    state.waveInitialPressureLeft = 0;
    state.waveSuspended = true;
    state.paused = true;
    state.enemyAnimationPreview = true;
    var center = findNearestClearGroundPoint(state.player ? state.player.x : 0, state.player ? state.player.z : 0, 4.8);
    if (state.player) {
      state.player.x = center.x;
      state.player.z = center.z;
      state.player.group.position.set(state.player.x, 0, state.player.z);
      state.player.group.visible = false;
    }
    var types = variant === "miner" || variant === "miner-damaged" ? ["armoredMiner"]
      : variant === "preacher" ? ["gravePreacher"]
        : ["armoredMiner", "gravePreacher"];
    var spacing = types.length > 1 ? 3.4 : 0;
    var entries = types.map(function (type, index) {
      var enemy = acquireZombie(type);
      enemy.x = center.x + (index - (types.length - 1) * 0.5) * spacing;
      enemy.z = center.z;
      enemy.facingAngle = 0;
      enemy.group.position.set(enemy.x, 0, enemy.z);
      enemy.group.rotation.y = 0;
      enemy.moveAmount = type === "armoredMiner" ? 0.32 : 0.18;
      if (enemy.group.userData.healthBack) enemy.group.userData.healthBack.visible = false;
      if (enemy.group.userData.healthFill) enemy.group.userData.healthFill.visible = false;
      state.enemies.push(enemy);
      dynamicRoot.add(enemy.group);
      if (variant === "miner-damaged" && type === "armoredMiner") {
        var firstArmorDebris = state.debris.length;
        enemy.renderVisible = true;
        enemy.hp = enemy.maxHp * 0.32;
        updateArmoredMinerArmorVisual(enemy);
        var armorPreviewLayout = [
          [-0.7, 0.38, -0.18, 0.18, 0.5, -0.28],
          [0.76, 0.32, 0.2, -0.22, -0.35, 0.4],
          [0.18, -0.62, -0.14, 0.35, 0.12, -0.2],
        ];
        for (var armorPreviewIndex = firstArmorDebris; armorPreviewIndex < state.debris.length; armorPreviewIndex++) {
          var armorPiece = state.debris[armorPreviewIndex];
          var armorLayout = armorPreviewLayout[armorPreviewIndex - firstArmorDebris] || armorPreviewLayout[0];
          armorPiece.x = enemy.x + armorLayout[0];
          armorPiece.y = 0.12;
          armorPiece.z = enemy.z + armorLayout[1];
          armorPiece.vx = 0;
          armorPiece.vy = 0;
          armorPiece.vz = 0;
          armorPiece.mesh.position.set(armorPiece.x, armorPiece.y, armorPiece.z);
          armorPiece.mesh.rotation.set(armorLayout[2], armorLayout[3], armorLayout[4]);
        }
      }
      updateZombieVisual(enemy);
      updateEnemyHealthBar(enemy);
      return { type: type, groupId: enemy.group.uuid, parts: enemy.group.children.length };
    });
    camera.zoom = types.length === 1 ? 4.15 : 2.25;
    camera.updateProjectionMatrix();
    cameraTarget.set(center.x, 0, center.z + 0.3);
    camera.position.set(cameraTarget.x + cameraBaseOffset.x, cameraBaseOffset.y, cameraTarget.z + cameraBaseOffset.z);
    camera.lookAt(cameraTarget);
    zombieSpatialDirty = true;
    updateModeClass();
    updateHud();
    render();
    return entries;
  }

