  function setupGhostTrainDeathPreview() {
    if (!setupGhostTrainPreview(true)) return false;
    var encounter = state.ghostTrain;
    if (!encounter || !encounter.boss) return false;
    for (var segmentIndex = GHOST_TRAIN_WAGON_COUNT; segmentIndex >= 1; segmentIndex--) {
      var destroyedWagon = encounter.segments[segmentIndex];
      destroyedWagon.hp = 0;
      destroyedWagon.attached = false;
      destroyedWagon.active = false;
      destroyedWagon.detaching = false;
      destroyedWagon.vulnerableTarget = false;
      if (destroyedWagon.group) removeObject3D(destroyedWagon.group);
      destroyedWagon.group = null;
    }
    encounter.activeTailIndex = 0;
    encounter.phase = 4;
    recomputeGhostTrainHealth(encounter);
    encounter.materialized = true;
    encounter.vulnerable = true;
    damageGhostTrainSegment(encounter.segments[0], 99999, encounter.segments[0].x, encounter.segments[0].z, { type: "preview" });
    if (state.player) {
      state.player.x = encounter.boss.x;
      state.player.z = encounter.boss.z;
      state.player.group.position.set(state.player.x, 0, state.player.z);
    }
    state.time += 1.9;
    updateGhostTrainDeathVisual(encounter, 0);
    updateGhostTrainHud();
    render();
    return getGhostTrainDiagnostics();
  }

  function setupMaxRifleTestPlayer() {
    state.level = 30;
    state.xp = 0;
    state.xpToNext = getXpToNextLevel(state.level);
    state.playerClass = "ranger";
    state.classChoicePending = false;
    state.classChoiceOffered = true;
    state.rifleUpgrade = "leverBarrage";
    state.rifleUpgradePending = false;
    state.rifleUpgradeOffered = true;
    state.rifleAmmoPickupBonus = RIFLE_UPGRADES.leverBarrage.rifleAmmoPickupBonus || 0;

    ["extendedTube", "trailLoader", "chainLightning", "stormTempo"].forEach(function (id) {
      var spec = getStandardUpgradeById(id);
      if (spec) applyStandardUpgrade(spec);
    });
    [
      ["steadyHand", 10],
      ["quickReload", 8],
      ["hairTrigger", 8],
      ["longReach", 5],
      ["swiftBoots", 5],
      ["scavengerLuck", 5],
      ["grit", 10],
      ["desertMender", 8],
    ].forEach(function (entry) {
      var spec = getStandardUpgradeById(entry[0]);
      if (!spec) return;
      for (var stack = 0; stack < entry[1]; stack++) applyStandardUpgrade(spec);
    });

    grantWeapon("rifle", true);
    state.ammo.rifle = getWeaponMagazine(WEAPONS.rifle);
    state.ammoReserve.rifle = 9999;
    state.reloadTimers.rifle = 0;
    if (state.player) {
      state.player.hp = state.player.maxHp;
      state.player.group.visible = true;
      // Give the browser hand-off enough time to finish before the test player
      // can be hit. This only runs in dedicated playable boss test scenes.
      state.player.invuln = Math.max(state.player.invuln || 0, 10);
    }
  }

