  function setupOilBaronStarPreview() {
    if (!setupOilBaronRifleTestScene()) return false;
    var encounter = state.oilBaron;
    if (!encounter || !encounter.boss || !state.player) return false;
    releaseAllEnemiesToPool();
    state.spawnLeft = 0;
    state.waveInitialPressureLeft = 0;
    state.waveSuspended = true;
    state.player.maxHp = Math.max(state.player.maxHp, 500);
    state.player.hp = state.player.maxHp;
    state.player.invuln = 999;
    encounter.aiEnabled = false;
    encounter.starLoopPreview = true;
    encounter.bribeOffered = true;
    encounter.bribeState = "expired";
    encounter.boss.hp = encounter.boss.maxHp * OIL_BARON_STAR_HP_RATIO;
    encounter.hudLagRatio = OIL_BARON_STAR_HP_RATIO;
    beginOilBaronStarAttack(encounter);
    var starPreviewFrame = String(new URLSearchParams(window.location.search).get("starFrame") || "").toLowerCase();
    if (starPreviewFrame === "flight" || starPreviewFrame === "landing" || starPreviewFrame === "soak") {
      var previewElapsed = starPreviewFrame === "soak"
        ? OIL_BARON_STAR_SOAK_TIME * 0.68
        : OIL_BARON_STAR_SOAK_TIME + OIL_BARON_STAR_JUMP_TIME * (starPreviewFrame === "landing" ? 0.82 : 0.46);
      encounter.boss.actionTimer = Math.max(0, OIL_BARON_STAR_TOTAL_TIME - previewElapsed);
      encounter.dealMessageTimer = 0;
      updateOilBaronStarAttack(encounter, 0);
      encounter.starPreviewFrozen = true;
    }
    if (starPreviewFrame === "soak") {
      state.player.x = encounter.boss.x - 4.2;
      state.player.z = encounter.boss.z + 2.2;
      resolveMoverPosition(state.player, state.player.radius, 0);
      state.player.group.position.set(state.player.x, 0, state.player.z);
    }
    camera.zoom = starPreviewFrame === "soak" ? 1.08 : 0.68;
    camera.updateProjectionMatrix();
    if (starPreviewFrame === "soak") cameraTarget.set(encounter.boss.x, 0, encounter.boss.z);
    else {
      cameraTarget.set(
        (state.player.x + encounter.boss.x) * 0.5,
        0,
        (state.player.z + encounter.boss.z) * 0.5
      );
    }
    camera.position.set(cameraTarget.x + cameraBaseOffset.x, cameraBaseOffset.y, cameraTarget.z + cameraBaseOffset.z);
    camera.lookAt(cameraTarget);
    updateOilBaronVisuals(encounter, 0);
    updateOilBaronHud();
    updateHud();
    render();
    return getOilBaronDiagnostics();
  }

  function setupBellRingerRifleTestScene() {
    resetRun("playing");
    setIntroActive(false);
    setupMaxRifleTestPlayer();
    var previousWave10BossOverride = wave10BossOverride;
    wave10BossOverride = "bellRinger";
    try {
      startWave(BELL_RINGER_WAVE);
    } finally {
      wave10BossOverride = previousWave10BossOverride;
    }
    var encounter = state.bellRinger;
    var bossTestParams = new URLSearchParams(window.location.search);
    var requestedBossBars = Math.floor(Number(bossTestParams.get("bossBars")) || 4);
    requestedBossBars = clamp(requestedBossBars, 1, 4);
    var completedBossSections = 4 - requestedBossBars;
    if (encounter && encounter.boss && completedBossSections > 0) {
      var previousBossPhase = encounter.phase;
      encounter.phase = completedBossSections;
      encounter.shieldCycle = completedBossSections;
      encounter.boss.hp = encounter.boss.maxHp * (1 - completedBossSections / 6);
      encounter.hudLagRatio = encounter.boss.hp / encounter.boss.maxHp;
      encounter.ascensionTimer = encounter.phase >= 1 ? BELL_RINGER_ASCENSION_INTERVAL : encounter.ascensionTimer;
      rescaleBellRingerPhaseTimers(encounter, previousBossPhase);
      updateBellRingerShieldVisual(encounter, true);
      updateBellRingerVisuals(encounter, 0);
      updateBellRingerHud();
    }
    if (encounter && encounter.boss && bossTestParams.get("bossVulnerable") === "1") {
      encounter.shielded = false;
      for (var churchIndex = 0; churchIndex < encounter.churches.length; churchIndex++) {
        var church = encounter.churches[churchIndex];
        church.active = false;
        church.captured = true;
        church.captureProgress = 1;
        if (church.chain) church.chain.visible = false;
      }
      updateBellRingerShieldVisual(encounter, false);
      updateBellRingerVisuals(encounter, 0);
      updateBellRingerHud();
    }
    if (encounter && encounter.boss) {
      state.pointerWorld.x = encounter.boss.x;
      state.pointerWorld.z = encounter.boss.z;
      pointerHit.set(state.pointerWorld.x, 0, state.pointerWorld.z);
      updateAim();
    }
    updateModeClass();
    updateHud();
    render();
    return getBellRingerDiagnostics();
  }

