    state.spawnLeft = 0;
    state.waveInitialPressureLeft = 0;
    state.waveSuspended = true;
    state.wave = BELL_RINGER_WAVE;
    state.paused = false;
    var center = findNearestClearGroundPoint(state.player ? state.player.x : 0, state.player ? state.player.z : 0, 2.5);
    var encounter = startBellRingerEncounter({ x: center.x, z: center.z, preview: true, aiEnabled: false });
