    getOilBaronMusicPlan: function (phase, action, startStep, count) {
      var normalizedPhase = clamp(Math.floor(Number(phase) || 0), 0, 2);
      var normalizedAction = ["combat", "offer", "starfall"].indexOf(String(action || "combat")) >= 0
        ? String(action || "combat")
        : "combat";
      var firstStep = Math.max(0, Math.floor(Number(startStep) || 0));
      var total = clamp(Math.floor(Number(count) || OIL_BARON_MUSIC_STEPS_PER_BAR), 1, OIL_BARON_MUSIC_STEPS_PER_BAR * OIL_BARON_MUSIC_PHRASE_BARS);
      var result = [];
      for (var planIndex = 0; planIndex < total; planIndex++) {
        var planStep = firstStep + planIndex;
        var plan = getOilBaronMusicStepPlan(planStep, normalizedPhase, normalizedAction);
        var eventCount = [
          plan.pump,
          plan.chain,
          !!plan.bassFrequency,
          plan.chord,
          plan.brass,
          !!plan.tackFrequency,
          !!plan.coinFrequency,
          !!plan.lead,
        ].filter(Boolean).length;
        result.push({
          step: planStep,
          bar: plan.bar,
          beat: plan.beat,
          section: plan.section,
          harmony: plan.barInfo.name,
          motifFamily: "black-gold-brand",
          pump: plan.pump,
          chain: plan.chain,
          bass: Number((plan.bassFrequency || 0).toFixed(2)),
          chord: plan.chord,
          brass: plan.brass,
          tack: Number((plan.tackFrequency || 0).toFixed(2)),
          coin: Number((plan.coinFrequency || 0).toFixed(2)),
          lead: Number((plan.lead && plan.lead.frequency || 0).toFixed(2)),
          eventCount: eventCount,
        });
      }
      return result;
    },
